begin;
    with j as (select * from jsonb_to_recordset($law7v027$[{"code_id":"NK_RF_2","article_number":"311","version_date":"2000-07-31","article_text":"Зачет производится при условии представления налогоплательщиком документа, подтверждающего уплату (удержание) налога за пределами Российской Федерации: для налогов, уплаченных самой организацией, - заверенного налоговым органом соответствующего иностранного государства, а для налогов, удержанных в соответствии с законодательством иностранных государств или международным договором налоговыми агентами, - подтверждения налогового агента. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nПодтверждение, указанное в настоящем пункте, действует в течение налогового периода, в котором оно представлено налогоплательщику. (Дополнение абзацем - Федеральный закон от 29.05.2002 № 57-ФЗ) (В редакции Федерального закона от 28.11.2015 № 326-ФЗ)","article_title":"Статья 311. Устранение двойного налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"75a0a28d3dbc3e06b114af3bac76297204f447f05430c413f092458a9adfa5e6"},{"code_id":"NK_RF_2","article_number":"312","version_date":"2000-07-31","article_text":"1. При применении положений международных договоров Российской Федерации иностранная организация, имеющая фактическое право на получение дохода, должна предоставить налоговому агенту, выплачивающему такой доход, подтверждение того, что эта иностранная организация имеет постоянное местонахождение в государстве, с которым Российская Федерация имеет международный договор Российской Федерации по вопросам налогообложения, которое должно быть заверено компетентным органом соответствующего иностранного государства. В случае, если такое подтверждение составлено на иностранном языке, налоговому агенту предоставляется также перевод на русский язык. Помимо этого иностранная организация должна представить налоговому агенту, выплачивающему доход, для применения положений международных договоров Российской Федерации подтверждение, что эта организация имеет фактическое право на получение соответствующего дохода.\n\nПредоставление иностранной организацией, имеющей фактическое право на получение дохода, указанных подтверждений налоговому агенту, выплачивающему доход, до даты выплаты дохода, в отношении которого международным договором Российской Федерации предусмотрен льготный режим налогообложения в Российской Федерации, является основанием для освобождения такого дохода от удержания налога у источника выплаты или удержания налога у источника выплаты по пониженным ставкам.\n\nНа международные организации, созданные в соответствии с международными договорами Российской Федерации, требование о предоставлении подтверждения постоянного местонахождения не распространяется. Для целей настоящей статьи такие международные организации предоставляют подтверждение, что они имеют фактическое право на получение соответствующего дохода. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\nПри этом последующее лицо, которое прямо участвует в лице, признавшем отсутствие фактического права на доход в виде дивидендов, вправе признать фактическое право на указанный доход. В случае признания последующим лицом отсутствия фактического права на доход в виде дивидендов, выплаченных российской организацией, право на применение положений международных договоров Российской Федерации и (или) настоящего Кодекса возникает у последующего лица в соответствующей последовательности участия. (В редакции Федерального закона от 27.11.2018 № 424-ФЗ)\n\nВ случае, если лицом, имеющим фактическое право на получение доходов в виде дивидендов и косвенно участвующим в организации, выплатившей доход в виде дивидендов, является налоговый резидент Российской Федерации, к налоговой базе, определяемой по доходам, полученным в виде дивидендов, может быть применена налоговая ставка, установленная подпунктом 2 пункта 3 статьи 284 настоящего Кодекса, при условии предоставления налоговому агенту, выплачивающему такой доход, информации (документов), указанной в настоящей статье. (В редакции федеральных законов от 03.08.2018 № 294-ФЗ, от 23.11.2020 № 374-ФЗ)\n\nПри этом косвенное участие каждого последующего лица, имеющего фактическое право на получение дохода, в российской организации, выплачивающей доход в виде дивидендов, в целях настоящей статьи  приравнивается к прямому участию в российской организации, выплачивающей доход в виде дивидендов. (В редакции федеральных законов от 03.08.2018 № 294-ФЗ, от 23.11.2020 № 374-ФЗ)\n\nАбзац. (Утратил силу  - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nАбзац. (Утратил силу  - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nВ случае, если российская организация прямо участвует в иностранной организации и такая иностранная организация признает отсутствие у нее фактического права на доход в виде дивидендов по акциям (долям) этой российской организации (депозитарным распискам, удостоверяющим права на акции этой российской организации), эта российская организация признается имеющей фактическое право на такой доход в порядке и с учетом особенностей, которые установлены пунктом 16 настоящей статьи. (Дополнение абзацем - Федеральный закон от 27.11.2018 № 424-ФЗ) (В редакции Федерального закона от 25.12.2018 № 493-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 24.11.2014 № 376-ФЗ) (В редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n1) документальное подтверждение признания этой иностранной организацией отсутствия фактического права на получение указанных доходов;\n\n2) информацию о лице, которое иностранная организация признает фактическим получателем дохода (с указанием доли и документальным подтверждением порядка прямого участия в этой иностранной организации и косвенного участия в российской организации, являющейся источником дивидендов, а также государства (территории) налогового резидентства лица).\n\n(Дополнение пунктом - Федеральный закон от 24.11.2014 № 376-ФЗ) (В редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n12-1. В случае выплаты налоговым агентом дохода по ценным бумагам, являющимся объектом операции РЕПО или предметом займа ценными бумагами (или иных аналогичных договоров) в пользу иностранной организации, являющейся покупателем ценных бумаг по первой части РЕПО или заемщиком по договору займа ценными бумагами (или иных аналогичных договоров), между датами исполнения первой и второй частей РЕПО или в течение срока договора займа ценными бумагами (или иных аналогичных договоров) для применения положений международных договоров Российской Федерации и (или) ставок налога, установленных настоящим Кодексом, налоговому агенту предоставляется следующая информация (документы) до даты выплаты дохода по ценным бумагам:\n\n1) письмо-подтверждение, что иностранная организация, в пользу которой выплачивается доход по ценным бумагам, в соответствии с условиями договора РЕПО, договора займа ценными бумагами или иного аналогичного договора не является лицом, имеющим фактическое право на эти доходы;\n\n2) копии договоров, указанных в подпункте 1 настоящего пункта;\n\n3) информация о лице, которое признает фактическое право на доходы по ценным бумагам;\n\n4) документы, предусмотренные пунктом 1 настоящей статьи, в отношении лица (лиц), признающего (признающих) фактическое право на указанный доход.\n\nПри этом в случае выплаты дохода в виде дивидендов требование пункта 11 настоящей статьи о прямом и (или) косвенном участии лица, имеющего фактическое право на дивиденды, в российской организации, выплачивающей доход, считается выполненным для целей применения положений международных договоров Российской Федерации и (или) ставок налога, установленных настоящим Кодексом.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2018 № 424-ФЗ)\n\n16. Российская организация признается имеющей фактическое право на доход, указанный в абзаце восьмом пункта 11 настоящей статьи, в части, соответствующей доле прямого участия этой российской организации в иностранной организации, признавшей отсутствие у нее фактического права на такой доход, и не превышающей суммы дивидендов по акциям (долям) такой иностранной организации, полученных этой российской организацией в срок, установленный абзацем вторым настоящего пункта, увеличенной на соответствующую сумму налогов, удержанных у источника выплаты таких дивидендов по акциям (долям) иностранной организации.\n\nДля целей настоящего пункта дивиденды по акциям (долям) иностранной организации, признавшей отсутствие у нее фактического права на доход, должны быть выплачены российской организации в течение 120 календарных дней, следующих за\n\nднем выплаты такой иностранной организации дивидендов по акциям (долям) этой российской организации (депозитарным распискам, удостоверяющим права на акции этой российской организации).\n\nПри выполнении условий, предусмотренных настоящим пунктом, доход в виде дивидендов по акциям (долям) российской организации (депозитарным распискам, удостоверяющим права на акции этой российской организации), полученных иностранной организацией, в отношении которого российская организация признается имеющей фактическое право на доход в соответствующей части, освобождается от налогообложения.\n\nВ случае, если российская организация прямо участвует в иностранной организации и такая иностранная организация признает отсутствие у нее фактического права на доход в виде дивидендов по акциям этой российской организации (депозитарным распискам, удостоверяющим права на акции этой российской организации), эта российская организация обязана уведомить депозитарий, осуществляющий выплату дохода в виде указанных дивидендов, до даты выплаты такого дохода о признании иностранной организацией отсутствия у нее фактического права на такой доход, о количестве акций этой российской организации (депозитарных расписок, удостоверяющих права на акции этой российской организации), по которым выплачиваются указанные дивиденды, и о доле прямого участия этой российской организации в иностранной организации, признавшей отсутствие фактического права на такой доход.\n\nВ случае, если доход иностранной организации, в отношении которого такая иностранная организация признала отсутствие фактического права и который получен в виде дивидендов по акциям (долям) российской организации (депозитарным распискам, удостоверяющим права на акции этой российской организации), прямо участвующей в такой иностранной организации, в части, соответствующей доле участия этой российской организации в такой иностранной организации, превышает сумму дивидендов по акциям (долям) иностранной организации, выплаченных этой российской организации в срок, установленный абзацем вторым настоящего пункта, увеличенную на сумму налогов, удержанных у источника выплаты таких дивидендов по акциям (долям) иностранной организации, доход в виде такого превышения подлежит налогообложению по ставке, установленной подпунктом 3 пункта 3 статьи 284 настоящего Кодекса. В этом случае уплата (перечисление) налога производится указанной в подпункте 4 пункта 7 статьи 275 настоящего Кодекса российской организацией - налоговым агентом в срок не позднее десяти дней со дня истечения срока, установленного абзацем вторым настоящего пункта. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nВ целях применения положений настоящего пункта суммы выплаченных дивидендов, а также суммы налогов, удержанных у источника выплаты дивидендов по акциям (долям) иностранной организации, выраженные в иностранной валюте, пересчитываются в рубли по официальному курсу, установленному Центральным банком Российской Федерации на дату принятия решения о выплате соответствующих дивидендов.\n\n(Дополнение пунктом - Федеральный закон от 25.12.2018 № 493-ФЗ)\n\nзаявления на возврат удержанного налога по форме, устанавливаемой федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов; (В редакции федеральных законов от 29.06.2004 № 58-ФЗ; от 29.07.2004 № 95-ФЗ)\n\nподтверждения того, что эта иностранная организация на момент выплаты дохода имела постоянное местонахождение в том государстве, с которым Российская Федерация имеет международный договор (соглашение), регулирующий вопросы налогообложения, которое должно быть заверено компетентным органом соответствующего иностранного государства;\n\nкопии договора (или иного документа), в соответствии с которым выплачивался доход иностранному юридическому лицу, за исключением случаев выплаты дохода по ценным бумагам российских организаций. (В редакции  федеральных законов от 27.07.2006 № 137-ФЗ, от 29.12.2012 № 282-ФЗ, от 14.07.2022 № 263-ФЗ)\n\nВ случае возврата налога, удержанного в соответствии со статьей 2146 или 3101 настоящего Кодекса, дополнительно представляются следующие документы: (Дополнение абзацем - Федеральный закон от 29.12.2012 № 282-ФЗ) (В редакции Федерального закона от 02.11.2013 № 306-ФЗ)\n\nдокумент, подтверждающий осуществление заявителем прав по ценным бумагам российской организации (ценным бумагам иностранной организации, удостоверяющим права в отношении ценных бумаг российской организации), по которым была осуществлена выплата доходов, на дату, определенную решением российской организации о выплате дохода, или документ, подтверждающий, что права по таким ценным бумагам на дату, определенную решением российской организации о выплате дохода по ценным бумагам, осуществлялись в интересах заявителя управляющей компанией; (Дополнение абзацем - Федеральный закон от 29.12.2012 № 282-ФЗ) (В редакции Федерального закона от 02.11.2013 № 306-ФЗ)\n\nдокумент, подтверждающий сумму дохода по ценным бумагам российской организации (ценным бумагам иностранной организации, удостоверяющим права в отношении ценных бумаг российской организации), в том числе по ценным бумагам, переданным заявителем в доверительное управление, фактически выплаченного заявителю (управляющей компании заявителя); (Дополнение абзацем - Федеральный закон от 29.12.2012 № 282-ФЗ) (В редакции Федерального закона от 02.11.2013 № 306-ФЗ)\n\nдокумент, содержащий сведения о депозитарии (депозитариях), который непосредственно или через третьих лиц перечислил сумму доходов по ценным бумагам российской организации в пользу иностранной организации, которая в соответствии с ее личным законом вправе осуществлять учет и переход прав по ценным бумагам и которая осуществляла учет ценных бумаг заявителя (управляющей компании заявителя); (Дополнение абзацем - Федеральный закон от 02.11.2013 № 306-ФЗ)\n\nдокумент, подтверждающий соблюдение лицом, осуществлявшим права по акциям российской организации (ценным бумагам иностранной организации, удостоверяющим права в отношении акций российской организации), или лицом, в интересах которого доверительный управляющий осуществлял права по указанным ценным бумагам, на дату, определенную решением российской организации о выплате доходов в виде дивидендов, дополнительных условий, предусмотренных настоящим Кодексом или международным договором Российской Федерации, необходимых для применения к выплачиваемым (выплаченным) доходам в виде дивидендов пониженной налоговой ставки (в случае возврата налога в связи с применением пониженной налоговой ставки). (Дополнение абзацем - Федеральный закон от 02.11.2013 № 306-ФЗ)\n\nВ случае, если вышеупомянутые документы составлены на иностранном языке, то налоговый орган вправе потребовать их перевод на русский язык. Нотариального заверения контрактов, платежных документов и их перевода на русский язык не требуется. Требования каких-либо иных, кроме вышеперечисленных, документов не допускается.\n\nЗаявление о возврате сумм ранее удержанных в Российской Федерации налогов, а также иные перечисленные в настоящем пункте документы представляются иностранным (фактическим) получателем дохода (его уполномоченным представителем) в налоговый орган по месту постановки на учет налогового агента в течение трех лет с момента окончания налогового периода, в котором был выплачен доход, если иное не предусмотрено по результатам проведения взаимосогласительной процедуры в соответствии с международным договором Российской Федерации по вопросам налогообложения. (В редакции  федеральных законов от 29.05.2002 № 57-ФЗ, от 24.11.2014 № 376-ФЗ, от 29.09.2019 № 325-ФЗ, от 14.07.2022 № 263-ФЗ)\n\nПо результатам проверки представленных документов выносится решение о подтверждении возможности возврата ранее удержанного (и уплаченного) налога. Возврат осуществляется налоговым органом по месту постановки на учет налогового агента в валюте Российской Федерации после подачи заявления и иных документов, предусмотренных в настоящем пункте, путем направления денежных средств, указанных в решении о подтверждении возможности возврата ранее удержанного (и уплаченного) налога, на открытый в банке счет налогоплательщика (его уполномоченного представителя) в порядке, аналогичном порядку, установленному статьей 79 настоящего Кодекса для сумм налогов, заявленных к возмещению. Денежные средства, подлежащие возврату на основании решения о подтверждении возможности возврата ранее удержанного (и уплаченного) налога, не участвуют при формировании сальдо единого налогового счета налогоплательщика, плательщика сбора, плательщика страховых взносов и (или) налогового агента. (В редакции  федеральных законов от 14.07.2022 № 263-ФЗ, от 28.12.2022 № 565-ФЗ)","article_title":"Статья 312. Специальные положения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b7029ea33b774f4e7f39f6fcdc9915afe2ea8bf48e91f5ab8411efcc625ffbc7"},{"code_id":"NK_RF_2","article_number":"313","version_date":"2000-07-31","article_text":"Налогоплательщики исчисляют налоговую базу по итогам каждого отчетного (налогового) периода на основе данных налогового учета. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nНалоговый учет - система обобщения информации для определения налоговой базы по налогу на основе данных первичных документов, сгруппированных в соответствии с порядком, предусмотренным настоящим Кодексом.\n\nВ случае, если в регистрах бухгалтерского учета содержится недостаточно информации для определения налоговой базы в соответствии с требованиями настоящей главы, налогоплательщик вправе самостоятельно дополнять применяемые регистры бухгалтерского учета дополнительными реквизитами, формируя тем самым регистры налогового учета, либо вести самостоятельные регистры налогового учета. (Дополнение частью - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\nНалоговый учет осуществляется в целях формирования полной и достоверной информации о порядке учета для целей налогообложения хозяйственных операций, осуществленных налогоплательщиком в течение отчетного (налогового) периода, а также обеспечения информацией внутренних и внешних пользователей для контроля за правильностью исчисления, полнотой и своевременностью исчисления и уплаты в бюджет налога.\n\nСистема налогового учета организуется налогоплательщиком самостоятельно, исходя из принципа последовательности применения норм и правил налогового учета, то есть применяется последовательно от одного налогового периода к другому. Порядок ведения налогового учета устанавливается налогоплательщиком в учетной политике для целей налогообложения, утверждаемой соответствующим приказом (распоряжением) руководителя. Налоговые и иные органы не вправе устанавливать для налогоплательщиков обязательные формы документов налогового учета. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nИзменение порядка учета отдельных хозяйственных операций и (или) объектов в целях налогообложения осуществляется налогоплательщиком в случае изменения законодательства о налогах и сборах или применяемых методов учета. Решение о внесении изменений в учетную политику для целей налогообложения при изменении применяемых методов учета принимается с начала нового налогового периода, а при изменении законодательства о налогах и сборах не ранее чем с момента вступления в силу изменений норм указанного законодательства. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nВ случае, если налогоплательщик начал осуществлять новые виды деятельности, он также обязан определить и отразить в учетной политике для целей налогообложения принципы и порядок отражения для целей налогообложения этих видов деятельности.\n\nДанные налогового учета должны отражать порядок формирования суммы доходов и расходов, порядок определения доли расходов, учитываемых для целей налогообложения в текущем налоговом (отчетном) периоде, сумму остатка расходов (убытков), подлежащую отнесению на расходы в следующих налоговых периодах, порядок формирования сумм создаваемых резервов, а также сумму задолженности по расчетам с бюджетом по налогу. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nПодтверждением данных налогового учета являются:\n\n1. первичные учетные документы (включая справку бухгалтера);\n\n2. аналитические регистры налогового учета;\n\n3. расчет налоговой базы.\n\nФормы аналитических регистров налогового учета для определения налоговой базы, являющиеся документами для налогового учета, в обязательном порядке должны содержать следующие реквизиты:\n\nнаименование регистра;\n\nпериод (дату) составления;\n\nизмерители операции в натуральном (если это возможно) и в денежном выражении;\n\nнаименование хозяйственных операций;\n\nподпись (расшифровку подписи) лица, ответственного за составление указанных регистров.\n\nСодержание данных налогового учета (в том числе данных первичных документов) является налоговой тайной. Лица, получившие доступ к информации, содержащейся в данных налогового учета, обязаны хранить налоговую тайну. За ее разглашение они несут ответственность, установленную действующим законодательством. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nНалогоплательщики, которые на день принятия в Российскую Федерацию Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и образования в составе Российской Федерации новых субъектов имели в соответствии с учредительными документами место нахождения постоянно действующего исполнительного органа либо в случае отсутствия постоянно действующего исполнительного органа иного органа или лица, имеющих право действовать от имени юридического лица без доверенности, на территории Донецкой Народной Республики, Луганской Народной Республики, Запорожской области или Херсонской области, в целях выявления фактического наличия имущества, имущественных прав, сопоставления фактического наличия имущества, имущественных прав с данными бухгалтерского учета, проверки полноты отражения в учете обязательств (требований) и последующего отражения в регистрах налогового учета согласно положениям настоящей статьи и статьи 314 настоящего Кодекса объектов учета для целей налогообложения в срок до 31 марта 2023 года включительно проводят инвентаризацию имеющихся имущества, имущественных прав, требований и обязательств на дату, непосредственно предшествующую дате начала применения в отношении указанных налогоплательщиков положений законодательства Российской Федерации о налогах и сборах. (Дополнение частью - Федеральный закон от 21.11.2022 № 443-ФЗ)\n\nИнвентаризация проводится на основании первичных учетных документов, в том числе договоров, приходных и расходных документов, отчетов о движении материальных ценностей и денежных средств, и иных документов, предусмотренных законодательством. При этом в случае отсутствия первичных учетных документов подтверждение фактического наличия и стоимости соответствующих объектов налогового учета может осуществляться в ином порядке, если это предусмотрено законодательством. (Дополнение частью - Федеральный закон от 21.11.2022 № 443-ФЗ)\n\nСведения о фактическом наличии имущества, имущественных прав, требований и обязательств и их стоимость в рублях записываются в инвентаризационные описи. Стоимость, выраженная в иностранной валюте, пересчитывается в рубли по официальному курсу Центрального банка Российской Федерации, установленному на дату, непосредственно предшествующую дате начала применения в отношении налогоплательщика положений законодательства Российской Федерации о налогах и сборах. (Дополнение частью - Федеральный закон от 21.11.2022 № 443-ФЗ)\n\nРезультаты инвентаризации оформляются актом об итогах инвентаризации (далее в настоящей статье - акт), подписанным руководителем юридического лица. К акту прилагаются инвентаризационные описи. (Дополнение частью - Федеральный закон от 21.11.2022 № 443-ФЗ)\n\nНалогоплательщик в срок, установленный частью двенадцатой настоящей статьи, представляет в налоговый орган по месту своего нахождения акт с приложением инвентаризационных описей. (Дополнение частью - Федеральный закон от 21.11.2022 № 443-ФЗ)\n\nСведения инвентаризационных описей последующему уточнению налогоплательщиком не подлежат и являются начальными данными налогоплательщика об объектах налогового учета с даты начала применения в отношении налогоплательщика положений законодательства Российской Федерации о налогах и сборах. (Дополнение частью - Федеральный закон от 21.11.2022 № 443-ФЗ)","article_title":"Статья 313. Налоговый учет. Общие положения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5decbf2b02c4e854877302e8a7fdbd8a219d55d3c6455cec7735158717441a72"},{"code_id":"NK_RF_2","article_number":"314","version_date":"2000-07-31","article_text":"Аналитические регистры налогового учета - сводные формы систематизации данных налогового учета за отчетный (налоговый) период, сгруппированных в соответствии с требованиями настоящей главы, без распределения (отражения) по счетам бухгалтерского учета.\n\nДанные налогового учета - данные, которые учитываются в разработочных таблицах, справках бухгалтера и иных документах налогоплательщика, группирующих информацию об объектах налогообложения.\n\nФормирование данных налогового учета предполагает непрерывность отражения в хронологическом порядке объектов учета для целей налогообложения (в том числе операций, результаты которых учитываются в нескольких отчетных периодах либо переносятся на ряд лет).\n\nПри этом аналитический учет данных налогового учета должен быть так организован налогоплательщиком, чтобы он раскрывал порядок формирования налоговой базы. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nАналитические регистры налогового учета предназначены для систематизации и накопления информации, содержащейся в принятых к учету первичных документах, аналитических данных налогового учета для отражения в расчете налоговой базы.\n\nРегистры налогового учета ведутся в виде специальных форм на бумажных носителях, в электронной форме и (или) любых машинных носителях. (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\nПри этом формы регистров налогового учета и порядок отражения в них аналитических данных налогового учета, данных первичных учетных документов разрабатываются налогоплательщиком самостоятельно и устанавливаются приложениями к учетной политике организации для целей налогообложения.\n\nПравильность отражения хозяйственных операций в регистрах налогового учета обеспечивают лица, составившие и подписавшие их.\n\nПри хранении регистров налогового учета должна обеспечиваться их защита от несанкционированных исправлений.\n\nИсправление ошибки в регистре налогового учета должно быть обосновано и подтверждено подписью ответственного лица, внесшего исправление, с указанием даты и обоснованием внесенного исправления. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)","article_title":"Статья 314. Аналитические регистры налогового учета","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"116c58533d9b7044d3eac1b9f04919115a91147af246f2c57a0414e3bc454c38"},{"code_id":"NK_RF_2","article_number":"315","version_date":"2000-07-31","article_text":"Расчет налоговой базы\n\nза отчетный (налоговый) период составляется налогоплательщиком самостоятельно в соответствии с нормами, установленными настоящей главой, исходя из данных налогового учета нарастающим итогом с начала года.\n\nРасчет налоговой базы должен содержать следующие данные:\n\n1. Период, за который определяется налоговая база (с начала налогового периода нарастающим итогом).\n\n2. Сумма доходов от реализации, полученных в отчетном (налоговом) периоде, в том числе:\n\n1) выручка от реализации товаров (работ, услуг) собственного производства, а также выручка от реализации имущества, имущественных прав, за исключением выручки, указанной в подпунктах 2 - 7 настоящего пункта; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n2) выручка от реализации ценных бумаг, не обращающихся на организованном рынке;\n\n3) выручка от реализации ценных бумаг, обращающихся на организованном рынке; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n4) выручка от реализации покупных товаров; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n5) (Подпункт утратил силу - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\n6) выручка от реализации основных средств; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n7) выручка от реализации товаров (работ, услуг) обслуживающих производств и хозяйств. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n3. Сумма расходов, произведенных в отчетном (налоговом) периоде, уменьшающих сумму доходов от реализации, в том числе:\n\n1) расходы на производство и реализацию товаров (работ, услуг) собственного производства, а также расходы, понесенные при реализации имущества, имущественных прав, за исключением расходов, указанных в подпунктах 2 - 6 настоящего пункта. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nПри этом общая сумма расходов уменьшается на суммы остатков незавершенного производства, остатков продукции на складе и продукции отгруженной, но нереализованной на конец отчетного (налогового) периода, определяемых в соответствии со статьей 319 настоящего Кодекса;\n\n2) расходы, понесенные при реализации ценных бумаг, не обращающихся на организованном рынке;\n\n3) расходы, понесенные при реализации ценных бумаг, обращающихся на организованном рынке; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n4) расходы, понесенные при реализации покупных товаров; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n(Подпункт 4 исключен - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n5) расходы, связанные с реализацией основных средств;\n\n6) расходы, понесенные обслуживающими производствами и хозяйствами при реализации ими товаров (работ, услуг).\n\n4. Прибыль (убыток) от реализации, в том числе:\n\n1) прибыль от реализации товаров (работ, услуг) собственного производства, а также прибыль (убыток) от реализации имущества, имущественных прав, за исключением прибыли (убытка), указанной в подпунктах 2, 3, 4 и 5 настоящего пункта; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n2) прибыль (убыток) от реализации ценных бумаг, не обращающихся на организованном рынке;\n\n3) прибыль (убыток) от реализации ценных бумаг, обращающихся на организованном рынке; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n4) прибыль (убыток) от реализации покупных товаров; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n(Подпункт 4 исключен - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n5) прибыль (убыток) от реализации основных средств;\n\n6) прибыль (убыток) от реализации обслуживающих производств и хозяйств.\n\n5. Сумма внереализационных доходов, в том числе:\n\n1) доходы по операциям с производными финансовыми инструментами, обращающимися на организованном рынке;\n\n2) доходы по операциям с производными финансовыми инструментами, не обращающимися на организованном рынке.\n\n(Пункт в редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n6. Сумма внереализационных расходов, в частности:\n\n1) расходы по операциям с производными финансовыми инструментами, обращающимися на организованном рынке;\n\n2) расходы по операциям с производными финансовыми инструментами, не обращающимися на организованном рынке.\n\n(Пункт в редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n7. Прибыль (убыток) от внереализационных операций.\n\n8. Итого налоговая база за отчетный (налоговый) период.\n\n9. Для определения суммы прибыли, подлежащей налогообложению, из налоговой базы исключается сумма убытка, подлежащего переносу в порядке, предусмотренном статьей 283 настоящего Кодекса.","article_title":"Статья 315. Порядок составления расчета налоговой базы","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"58eb6bd4697c6157bda561616836c41336569b7e72a8be0dd77517be06b0b2c5"},{"code_id":"NK_RF_2","article_number":"316","version_date":"2000-07-31","article_text":"Доходы от реализации определяются по видам деятельности в случае, если для данного вида деятельности предусмотрен иной порядок налогообложения, применяется иная ставка налога либо предусмотрен иной отличный от общего порядок учета прибыли и убытка, полученного от данного вида деятельности. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nСумма выручки от реализации определяется в соответствии со статьей 249 настоящего Кодекса с учетом положений статьи 251 настоящего Кодекса на дату признания доходов и расходов в соответствии с выбранным налогоплательщиком методом признания доходов и расходов для целей налогообложения.\n\nВ случае, если цена реализуемого товара (работ, услуг), имущественных прав выражена в валюте иностранного государства, сумма выручки от реализации пересчитывается в рубли на дату реализации. В случае получения аванса, задатка налогоплательщиком, определяющим доходы и расходы по методу начисления, сумма выручки от реализации в части, приходящейся на аванс, задаток, определяется по официальному курсу, установленному Центральным банком Российской Федерации на дату получения аванса, задатка. (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 28.12.2010 № 395-ФЗ)\n\nЧасть. (Утратила силу - Федеральный закон от 20.04.2014 № 81-ФЗ)\n\nВ случае если реализация производится через комиссионера, то налогоплательщик-комитент определяет сумму выручки от реализации на дату реализации на основании извещения комиссионера о реализации принадлежащего комитенту имущества (имущественных прав). При этом комиссионер обязан в течение трех дней с момента окончания отчетного периода, в котором произошла такая реализация, известить комитента о дате реализации принадлежавшего ему имущества.\n\nЕсли при реализации расчеты производятся на условиях предоставления товарного кредита, то сумма выручки определяется также на дату реализации и включает в себя сумму процентов, начисленных за период от момента отгрузки до момента перехода права собственности на товары.\n\nПроценты, начисленные за пользование товарным кредитом с момента перехода права собственности на товары до момента полного расчета по обязательствам, включаются в состав внереализационных доходов.\n\nПо производствам с длительным (более одного налогового периода) технологическим циклом в случае, если условиями заключенных договоров не предусмотрена поэтапная сдача работ (услуг), доход от реализации указанных работ (услуг) распределяется налогоплательщиком самостоятельно с учетом принципа равномерности признания дохода на основании данных учета. При этом принципы и методы, в соответствии с которыми распределяется доход от реализации, должны быть утверждены налогоплательщиком в учетной политике для целей налогообложения. (Дополнение частью - Федеральный закон от 31.12.2002 № 191-ФЗ)","article_title":"Статья 316. Порядок налогового учета доходов от реализации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c8d075c0af99c92aec908ca2a5e04dc5d65e356d77add1b91d4a3e18ef2d0ec7"},{"code_id":"NK_RF_2","article_number":"317","version_date":"2000-07-31","article_text":"При определении внереализационных доходов в виде штрафов, пеней или иных санкций за нарушение договорных обязательств, а также сумм возмещения убытков или ущерба налогоплательщики, определяющие доходы по методу начисления, отражают причитающиеся суммы в соответствии с условиями договора. В случае, если условиями договора не установлен размер штрафных санкций или возмещения убытков, у налогоплательщика-получателя не возникает обязанности для начисления внереализационных доходов по этому виду доходов. При взыскании долга в судебном порядке обязанность по начислению этого внереализационного дохода у налогоплательщика возникает на основании решения суда, вступившего в законную силу. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)","article_title":"Статья 317. Порядок налогового учета отдельных видов внереализационных доходов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"baa77b030d7b84728444acd52146db0af3b803e25143515e04c75f94534d7704"},{"code_id":"NK_RF_2","article_number":"318","version_date":"2000-07-31","article_text":"1. Если налогоплательщик определяет доходы и расходы по методу начисления, расходы на производство и реализацию определяются с учетом положений настоящей статьи.\n\nДля целей настоящей главы расходы на производство и реализацию, осуществленные в течение отчетного (налогового) периода, подразделяются на:\n\n1) прямые;\n\n2) косвенные.\n\nК прямым расходам могут быть отнесены, в частности: (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 06.06.2005 № 58-ФЗ)\n\nматериальные затраты, определяемые в соответствии с подпунктами 1 и 4 пункта 1 статьи 254 настоящего Кодекса; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nрасходы на оплату труда персонала, участвующего в процессе производства товаров, выполнения работ, оказания услуг, а также расходы на обязательное пенсионное страхование, на обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством, обязательное медицинское страхование, обязательное социальное страхование от несчастных случаев на производстве и профессиональных заболеваний, начисленные на указанные суммы расходов на оплату труда; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 06.06.2005 № 58-ФЗ; от 24.07.2009 № 213-ФЗ; от 29.06.2015 № 177-ФЗ)\n\nсуммы начисленной амортизации по основным средствам, используемым при производстве товаров, работ, услуг. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nК косвенным расходам относятся все иные суммы расходов, за исключением внереализационных расходов, определяемых в соответствии со статьей 265 настоящего Кодекса, осуществляемых налогоплательщиком в течение отчетного (налогового) периода. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nНалогоплательщик самостоятельно определяет в учетной политике для целей налогообложения перечень прямых расходов, связанных с производством товаров (выполнением работ, оказанием услуг). (Дополнение абзацем - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\nПрямые расходы относятся к расходам текущего отчетного (налогового) периода по мере реализации продукции, работ, услуг, в стоимости которых они учтены в соответствии со статьей 319 настоящего Кодекса. (В редакции Федерального закона от 06.06.2005 № 58-ФЗ)\n\nНалогоплательщики, оказывающие услуги, вправе относить сумму прямых расходов, осуществленных в отчетном (налоговом) периоде, в полном объеме на уменьшение доходов от производства и реализации данного отчетного (налогового) периода без распределения на остатки незавершенного производства. (Дополнение абзацем - Федеральный закон от 06.06.2005 № 58-ФЗ)","article_title":"Статья 318. Порядок определения суммы расходов на производство и реализацию","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4765785b3d45112c249fa1c903c7e2c11d9668527ceb3d2f3f2fde7aa590d63b"},{"code_id":"NK_RF_2","article_number":"319","version_date":"2000-07-31","article_text":"Оценка остатков НЗП на конец текущего месяца производится налогоплательщиком на основании данных первичных учетных документов о движении и об остатках (в количественном выражении) сырья и материалов, готовой продукции по цехам (производствам и прочим производственным подразделениям налогоплательщика) и данных налогового учета о сумме осуществленных в текущем месяце прямых расходов. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nНалогоплательщик самостоятельно определяет порядок распределения прямых расходов на НЗП и на изготовленную в текущем месяце продукцию (выполненные работы, оказанные услуги) с учетом соответствия осуществленных расходов изготовленной продукции (выполненным работам, оказанным услугам). (Дополнение абзацем - Федеральный закон от 29.05.2002 № 57-ФЗ) (В редакции Федерального закона от 06.06.2005 № 58-ФЗ)\n\nУказанный порядок распределения прямых расходов (формирования стоимости НЗП) устанавливается налогоплательщиком в учетной политике для целей налогообложения и подлежит применению в течение не менее двух налоговых периодов. (Дополнение абзацем - Федеральный закон от 29.05.2002 № 57-ФЗ) (В редакции Федерального закона от 06.06.2005 № 58-ФЗ)\n\nВ случае, если отнести прямые расходы к конкретному производственному процессу по изготовлению данного вида продукции (работ, услуг) невозможно, налогоплательщик в своей учетной политике для целей налогообложения самостоятельно определяет механизм распределения указанных расходов с применением экономически обоснованных показателей. (В редакции Федерального закона от 06.06.2005 № 58-ФЗ)\n\nСумма остатков незавершенного производства на конец текущего месяца включается в состав прямых расходов следующего месяца. При окончании налогового периода сумма остатков незавершенного производства на конец налогового периода включается в состав прямых расходов следующего налогового периода в порядке и на условиях, предусмотренных настоящей статьей. (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 06.06.2005 № 58-ФЗ)","article_title":"Статья 319. Порядок оценки остатков незавершенного производства, остатков готовой продукции, товаров отгруженных","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3f6fcb496a9cefea635a42a9d7aa356db3fb27ead5c524ce84445e291453ab1d"},{"code_id":"NK_RF_2","article_number":"320","version_date":"2000-07-31","article_text":"Налогоплательщики, осуществляющие оптовую, мелкооптовую и розничную торговлю, формируют расходы на реализацию (далее в настоящей статье - издержки обращения) с учетом следующих особенностей.\n\nВ течение текущего месяца издержки обращения формируются в соответствии с настоящей главой. При этом в сумму издержек обращения включаются также расходы налогоплательщика - покупателя товаров на доставку этих товаров, складские расходы и иные расходы текущего месяца, связанные с приобретением, если они не учтены в стоимости приобретения товаров, и реализацией этих товаров. К издержкам обращения не относится стоимость приобретения товаров по цене, установленной условиями договора. При этом налогоплательщик имеет право сформировать стоимость приобретения товаров с учетом расходов, связанных с приобретением этих товаров. Указанная стоимость товаров учитывается при их реализации в соответствии с подпунктом 3 пункта 1 статьи 268 настоящего Кодекса. Стоимость приобретения товаров, отгруженных, но не реализованных на конец месяца, не включается налогоплательщиком в состав расходов, связанных с производством и реализацией, до момента их реализации. Порядок формирования стоимости приобретения товаров определяется налогоплательщиком в учетной политике для целей налогообложения и применяется в течение не менее двух налоговых периодов.\n\nРасходы текущего месяца разделяются на прямые и косвенные. К прямым расходам относятся стоимость приобретения товаров, реализованных в данном отчетном (налоговом) периоде, и суммы расходов на доставку (транспортные расходы) покупных товаров до склада налогоплательщика - покупателя товаров в случае, если эти расходы не включены в цену приобретения указанных товаров. Все остальные расходы, за исключением внереализационных расходов, определяемых в соответствии со статьей 265 настоящего Кодекса, осуществленные в текущем месяце, признаются косвенными расходами и уменьшают доходы от реализации текущего месяца. Сумма прямых расходов в части транспортных расходов, относящаяся к остаткам нереализованных товаров, определяется по среднему проценту за текущий месяц с учетом переходящего остатка на начало месяца в следующем порядке:\n\n1) определяется сумма прямых расходов, приходящихся на остаток нереализованных товаров на начало месяца и осуществленных в текущем месяце;\n\n2) определяется стоимость приобретения товаров, реализованных в текущем месяце, и стоимость приобретения остатка нереализованных товаров на конец месяца;\n\n3) рассчитывается средний процент как отношение суммы прямых расходов (пункт 1 настоящей части) к стоимости товаров (пункт 2 настоящей части);\n\n4) определяется сумма прямых расходов, относящаяся к остатку нереализованных товаров, как произведение среднего процента и стоимости остатка товаров на конец месяца.\n\n(Статья в редакции Федерального закона от 06.06.2005 № 58-ФЗ)","article_title":"Статья 320. Порядок определения расходов по торговым операциям","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"441617430e8ba7a26cb405cbacc71b9047b6876e3692f3e7154273a573e82f9f"},{"code_id":"NK_RF_2","article_number":"321","version_date":"2000-07-31","article_text":"Организации, созданные в соответствии с федеральными законами (Центральный банк Российской Федера\n\nции, Агентство по страхованию вкладов, Государственная корпорация по космической деятельности \"Роскосмос\"), регулирующими деятельность данных организаций, ведут раздельный учет доходов и расходов, полученных (понесенных) при осуществлении деятельности, связанной с исполнением ими функций, предусмотренных законодательством, и доходов и расходов, полученных (понесенных) при осуществлении иной коммерческой деятельности. (В редакции федеральных законов от 29.05.2002 № 57-ФЗ, от 28.07.2004 № 84-ФЗ, от 06.06.2005 № 58-ФЗ, от 09.11.2020 № 368-ФЗ)\n\nПри осуществлении налогового учета коммерческой деятельности такие организации применяют общие нормы настоящей главы, регламентирующие порядок определения доходов и расходов, а также специальные нормы (особенности), предусмотренные для отдельных категорий налогоплательщиков, либо нормы, предусмотренные для особых обстоятельств. Данные нормы некоммерческая организация применяет, если эта организация осуществляет такие виды деятельности в соответствии с федеральными законами. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nЕсли такая некоммерческая организация несет обязательные некомпенсируемые расходы в соответствии с требованиями законодательства Российской Федерации, то такие расходы признаются расходами такой организации, уменьшающими доходы от коммерческой деятельности.","article_title":"Статья 321. Особенности ведения налогового учета организациями, созданными в соответствии с федеральными законами, регулирующими деятельность данных организаций","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3a8258099d16db683ebd9dbac8ad5693cbf57fa36444f0e11714f1d89db5950c"},{"code_id":"NK_RF_2","article_number":"321.1","version_date":"2000-07-31","article_text":"(Статья утратила силу - Федеральный закон от 08.05.2010 № 83-ФЗ)","article_title":"Статья 321.1. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e4f9ccc1434d41f4cee6464ee0888a125ec3d8290dccdb94dabdbc9075e65df4"},{"code_id":"NK_RF_2","article_number":"321.2","version_date":"2000-07-31","article_text":"1. Ответственный участник консолидированной группы налогоплательщиков применительно к порядку ведения налогового учета, установленному настоящим Кодексом, ведет налоговый учет консолидированной налоговой базы на основании информации из налоговых регистров каждого участника этой группы, которые ведутся в соответствии со статьей 313 настоящего Кодекса.\n\n2. Порядок ведения налогового учета консолидированной группы налогоплательщиков устанавливается в учетной политике для целей налогообложения консолидированной группы налогоплательщиков.\n\n(Дополнение статьей - Федеральный закон от 16.11.2011 № 321-ФЗ)","article_title":"Статья 321.2. Особенности ведения налогового учета участниками консолидированной группы налогоплательщиков","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c1e5c5a534f70be1e1cc12d5acf58676f2b2d7a60c2173fe1b55361b9815efc2"},{"code_id":"NK_RF_2","article_number":"322","version_date":"2000-07-31","article_text":"1. На 1-е число налогового периода, с начала которого учетной политикой для целей налогообложения установлено изменение метода начисления амортизации, организации в налоговом учете определяют остаточную стоимость объектов амортизируемого имущества.\n\nПри установлении в учетной политике для целей налогообложения нелинейного метода начисления амортизации в целях определения суммарного баланса амортизационных групп (подгрупп) остаточная стоимость объектов амортизируемого имущества, за исключением объектов, амортизация по которым начисляется линейным методом в соответствии с пунктом 3 статьи 259 настоящего Кодекса, определяется исходя из срока их полезного использования, установленного при введении данных объектов в эксплуатацию, на 1-е число налогового периода, с начала которого учетной политикой для целей налогообложения установлено применение нелинейного метода начисления амортизации.\n\nСумма начисленной за один месяц амортизации по объектам амортизируемого имущества определяется следующим образом:\n\n1) при применении нелинейного метода начисления амортизации в составе амортизационных групп (подгрупп) - как произведение суммарного баланса соответствующей амортизационной группы (подгруппы) на 1-е число месяца, за который определяется сумма начисленной амортизации, и нормы амортизации, установленной пунктом 5 статьи 2592 настоящего Кодекса;\n\n2) при применении линейного метода начисления амортизации - как произведение первоначальной (восстановительной) стоимости и нормы амортизации, установленной налогоплательщиком для указанного имущества в соответствии с пунктом 2 статьи 2591 настоящего Кодекса.\n\n2. По основным средствам, переведенным по решению руководства организации на консервацию продолжительностью свыше трех месяцев, а также по основным средствам, находящимся по решению руководства организации на реконструкции (модернизации) свыше 12 месяцев, начиная с 1-го числа месяца, следующего за месяцем, в котором указанные основные средства были переведены на консервацию или с которого они находятся на реконструкции (модернизации), начисление амортизации не производится.\n\nПри расконсервации, завершении реконструкции (модернизации) объекта основных средств амортизация по нему начисляется с 1-го числа месяца, следующего за месяцем, в котором произошла расконсервация основного средства или завершилась его реконструкция (модернизация).\n\n(Пункт в редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n3. При внесении изменений в учетную политику для целей налогообложения в соответствии с пунктом 1 статьи 259 настоящего Кодекса, согласно которым налогоплательщик, применяющий линейный метод начисления амортизации, переходит к применению нелинейного метода начисления амортизации, объекты, амортизация по которым в соответствии с внесенными налогоплательщиком изменениями в учетную политику для целей налогообложения начисляется нелинейным методом, включаются в состав амортизационных групп (подгрупп) в целях определения их суммарного баланса по остаточной стоимости, определенной на 1-е число налогового периода, с начала которого учетной политикой для целей налогообложения установлено применение нелинейного метода начисления амортизации.\n\nПри этом указанные в настоящем пункте объекты амортизируемого имущества в целях определения суммарного баланса амортизационных групп включаются в состав этих групп исходя из срока полезного использования таких объектов, установленного при введении их в эксплуатацию.\n\nПри внесении указанных в настоящем пункте изменений в учетную политику для целей налогообложения амортизационные подгруппы, предусмотренные пунктом 13 статьи 258 настоящего Кодекса, создаются в составе амортизационных групп, сформированных в соответствии с порядком, установленным настоящим пунктом.\n\n4. При внесении изменений в учетную политику для целей налогообложения в соответствии с пунктом 1 статьи 259 настоящего Кодекса, согласно которым налогоплательщик, применяющий нелинейный метод начисления амортизации, переходит к применению линейного метода начисления амортизации, налогоплательщик в соответствии со статьей 257 настоящего Кодекса определяет остаточную стоимость объектов амортизируемого имущества на 1-е число налогового периода, с начала которого учетной политикой для целей налогообложения установлено применение линейного метода начисления амортизации.\n\nПри этом норма амортизации для каждого объекта амортизируемого имущества определяется в соответствии с пунктом 2 статьи 2591 настоящего Кодекса исходя из оставшегося срока полезного использования объекта амортизируемого имущества, определенного на 1-е число налогового периода, с начала которого учетной политикой для целей налогообложения установлено применение линейного метода начисления амортизации.\n\n(Статья в редакции Федерального закона от 22.07.2008 № 158-ФЗ)","article_title":"Статья 322. Особенности организации налогового учета амортизируемого имущества","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8c892919256a4b722cb3fdb175da338b6d9fccf3a0c5e3a82187e5dd68eaeeb8"},{"code_id":"NK_RF_2","article_number":"323","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nНалогоплательщик определяет прибыль (убыток) от реализации или выбытия амортизируемого имущества на основании аналитического учета по каждому объекту на дату признания дохода (расхода). (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nУчет доходов и расходов по амортизируемому имуществу ведется пообъектно, за исключением начисленной амортизации по объектам амортизируемого имущества при применении нелинейного метода начисления амортизации. (В редакции Федерального закона от 22.07.2008 № 158-ФЗ)\n\nАналитический учет должен содержать информацию:\n\nо первоначальной стоимости амортизируемого имущества, реализованного (выбывшего) в отчетном (налоговом) периоде; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nоб изменениях первоначальной стоимости таких основных средств при достройке, дооборудовании, реконструкции, частичной ликвидации;\n\nо принятых организацией сроках полезного использования основных средств и нематериальных активов; (В редакции Федерального закона от 22.07.2008 № 158-ФЗ)\n\nо сумме начисленной амортизации по амортизируемым основным средствам и нематериальным активам за период с даты начала начисления амортизации до конца месяца, в котором такое имущество реализовано (выбыло), - для объектов, амортизация по которым начисляется линейным методом; (В редакции Федерального закона от 22.07.2008 № 158-ФЗ)\n\nо сумме начисленной амортизации и суммарном балансе каждой амортизационной группы и каждой амортизационной подгруппы (при применении нелинейного метода начисления амортизации); (Дополнение абзацем - Федеральный закон от 22.07.2008 № 158-ФЗ)\n\nоб остаточной стоимости объектов амортизируемого имущества, входящих в амортизационные группы (подгруппы), определенной в соответствии с пунктом 1 статьи 257 настоящего Кодекса, - при выбытии объектов амортизируемого имущества; (Дополнение абзацем - Федеральный закон от 22.07.2008 № 158-ФЗ)\n\nо цене реализации амортизируемого имущества исходя из условий договора купли-продажи;\n\nо дате приобретения и дате реализации (выбытия) имущества; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nо дате передачи имущества в эксплуатацию, о дате исключения из состава амортизируемого имущества по основаниям, предусмотренным пунктом 3 статьи 256 настоящего Кодекса, о дате расконсервации имущества, о дате окончания договора безвозмездного пользования, о дате завершения работ по реконструкции, о дате модернизации; (Дополнение абзацем - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\nо понесенных налогоплательщиком расходах, связанных с реализацией (выбытием) амортизируемого имущества, в частности расходах, предусмотренных подпунктом 8 пункта 1 статьи 265 настоящего Кодекса, а также расходах по хранению, обслуживанию и транспортировке реализованного (выбывшего) имущества. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nНа дату совершения операции налогоплательщик определяет в соответствии с пунктом 3 статьи 268 настоящего Кодекса прибыль (убыток) от реализации амортизируемого имущества. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nВ аналитическом учете на дату реализации амортизируемого имущества фиксируется сумма прибыли (убытка) по указанной операции, которая в целях определения налоговой базы учитывается в следующем порядке. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nПрибыль, полученная налогоплательщиком, подлежит включению в состав налоговой базы в том отчетном периоде, в котором была осуществлена реализация имущества. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nУбыток, полученный налогоплательщиком, отражается в аналитическом учете как прочие расходы налогоплательщика в соответствии с порядком, установленным статьей 268 настоящего Кодекса. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nАналитический учет должен содержать информацию о наименовании объектов, в отношении которых имеются суммы таких расходов, количестве месяцев, в течение которых такие расходы могут быть включены в состав прочих расходов, связанных с производством и реализацией, и сумме расходов, приходящейся на каждый месяц. Срок определяется в месяцах и исчисляется в виде разницы между количеством месяцев срока полезного использования этого имущества и количеством месяцев эксплуатации имущества до момента его реализации, включая месяц, в котором имущество было реализовано. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)","article_title":"Статья 323. Особенности ведения налогового учета операций с амортизируемым имуществом","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"47abb1ae39e1f41864554f8d02e2fbd54e57b22a418fb0f6590d2274faf8b9dd"},{"code_id":"NK_RF_2","article_number":"324","version_date":"2000-07-31","article_text":"1. В аналитическом учете налогоплательщик формирует сумму расходов на ремонт основных средств с учетом группировки всех осуществленных расходов, включая стоимость запасных частей и расходных материалов, используемых для ремонта, расходов на оплату труда работников, осуществляющих ремонт, и прочих расходов, связанных с ведением указанного ремонта собственными силами, а также с учетом затрат на оплату работ, выполненных сторонними силами.\n\n2. Налогоплательщик, образующий резерв предстоящих расходов на ремонт, рассчитывает отчисления в такой резерв, исходя из совокупной стоимости основных средств, рассчитанной в соответствии с порядком, установленным настоящим пунктом, и нормативов отчислений, утверждаемых налогоплательщиком самостоятельно в учетной политике для целей налогообложения.\n\nСовокупная стоимость основных средств определяется как сумма первоначальной стоимости всех амортизируемых основных средств, введенных в эксплуатацию по состоянию на начало налогового периода, в котором образуется резерв предстоящих расходов на ремонт основных средств. Для расчета совокупной стоимости амортизируемых основных средств, введенных в эксплуатацию до вступления в силу настоящей главы, принимается восстановительная стоимость, определенная в соответствии с пунктом 1 статьи 257 настоящего Кодекса.\n\nПри определении нормативов отчислений в резерв предстоящих расходов на ремонт основных средств налогоплательщик обязан определить предельную сумму отчислений в резерв предстоящих расходов на ремонт основных средств, исходя из периодичности осуществления ремонта объекта основных средств, частоты замены элементов основных средств (в частности, узлов, деталей, конструкций) и сметной стоимости указанного ремонта. При этом предельная сумма резерва предстоящих расходов на указанный ремонт не может превышать среднюю величину фактических расходов на ремонт, сложившуюся за последние три года. Если налогоплательщик осуществляет накопление средств для проведения особо сложных и дорогих видов капитального ремонта основных средств в течение более одного налогового периода, то предельный размер отчислений в резерв предстоящих расходов на ремонт основных средств может быть увеличен на сумму отчислений на финансирование указанного ремонта, приходящегося на соответствующий налоговый период в соответствии с графиком проведения указанных видов ремонта при условии, что в предыдущих налоговых периодах указанные либо аналогичные ремонты не осуществлялись.\n\nОтчисления в резерв предстоящих расходов на ремонт основных средств в течение налогового периода списываются на расходы равными долями на последнее число соответствующего отчетного (налогового) периода. (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\nВ случае, если налогоплательщик создает резерв предстоящих расходов на ремонт основных средств, сумма фактически осуществленных затрат на проведение ремонта списывается за счет средств указанного резерва.\n\nВ случае, если сумма фактически осуществленных затрат на ремонт основных средств в отчетном (налоговом) периоде превышает сумму созданного резерва предстоящих расходов на ремонт основных средств, остаток затрат для целей налогообложения включается в состав прочих расходов на дату окончания налогового периода.\n\nЕсли на конец налогового периода остаток средств резерва предстоящих расходов на ремонт основных средств превышает сумму фактически осуществленных в текущем налоговом периоде затрат на ремонт основных средств, то сумма такого превышения на последнюю дату текущего налогового периода для целей налогообложения включается в состав доходов налогоплательщика.\n\nЕсли в соответствии с учетной политикой для целей налогообложения и на основании графика проведения капитального ремонта основных средств налогоплательщик осуществляет накопление средств для финансирования указанного ремонта в течение более одного налогового периода, то на конец текущего налогового периода остаток таких средств не подлежит включению в состав доходов для целей налогообложения.\n\n3. Если налогоплательщик осуществляет виды деятельности, в отношении которых в соответствии со статьей 274 настоящего Кодекса отдельно исчисляется налоговая база по налогу, то аналитический учет расходов на ремонт основных средств для целей налогообложения ведется по видам производства, по видам деятельности.\n\n(Статья в редакции Федерального закона от 29.05.2002 № 57-ФЗ)","article_title":"Статья 324. Порядок ведения налогового учета расходов на ремонт основных средств","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bcb9d4a81dbb5831d44c379b06be0a9b82e1c14103a9dcaff6d26c32c3be89e2"},{"code_id":"NK_RF_2","article_number":"324.1","version_date":"2000-07-31","article_text":"1. Налогоплательщик, принявший решение о равномерном учете для целей налогообложения предстоящих расходов на оплату отпусков работников, обязан отразить в учетной политике для целей налогообложения принятый им способ резервирования, определить предельную сумму отчислений и ежемесячный процент отчислений в указанный резерв.\n\nДля этих целей налогоплательщик обязан составить специальный расчет (смету), в котором отражается расчет размера ежемесячных отчислений в указанный резерв, исходя из сведений о предполагаемой годовой сумме расходов на оплату отпусков, включая сумму страховых взносов на обязательное пенсионное страхование, обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством, обязательное медицинское страхование, обязательное социальное страхование от несчастных случаев на производстве и профессиональных заболеваний с этих расходов. При этом процент отчислений в указанный резерв определяется как отношение предполагаемой годовой суммы расходов на оплату отпусков к предполагаемому годовому размеру расходов на оплату труда. (В редакции Федерального закона от 24.07.2009 № 213-ФЗ)\n\n2. Расходы на формирование резерва предстоящих расходов на оплату отпусков относятся на счета учета расходов на оплату труда соответствующих категорий работников.\n\n3. На конец налогового периода налогоплательщик обязан провести инвентаризацию указанного резерва.\n\nНедоиспользованные на последнее число текущего налогового периода суммы указанного резерва подлежат обязательному включению в состав налоговой базы текущего налогового периода. (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\nПри недостаточности средств фактически начисленного резерва, подтвержденного инвентаризацией на последний день налогового периода, налогоплательщик обязан по состоянию на 31 декабря года, в котором резерв был начислен, включить в расходы сумму фактических расходов на оплату отпусков и соответственно сумму страховых взносов на обязательное пенсионное страхование, обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством, обязательное медицинское страхование, обязательное социальное страхование от несчастных случаев на производстве и профессиональных заболеваний, по которым ранее не создавался указанный резерв. (В редакции федеральных законов от 27.07.2006 № 137-ФЗ; от 24.07.2009\n\nЕсли по итогам инвентаризации резерва предстоящих расходов на оплату отпусков сумма рассчитанного резерва в части неиспользованного отпуска, определенная исходя из среднедневной суммы расходов на оплату труда и количества дней неиспользованного отпуска на конец года, превышает фактический остаток неиспользованного резерва на конец года, то сумма превышения подлежит включению в состав расходов на оплату труда. Если по итогам инвентаризации резерва предстоящих расходов на оплату отпусков сумма рассчитанного резерва в части неиспользованного отпуска, определенная исходя из среднедневной суммы расходов на оплату труда и количества дней неиспользованного отпуска на конец года, оказывается меньше фактического остатка неиспользованного резерва на конец года, то отрицательная разница подлежит включению в состав внереализационных доходов. (Дополнение абзацем - Федеральный закон от 24.07.2007 № 216-ФЗ)\n\nПри определении суммы фактически начисленного вознаграждения за выслугу лет и по итогам работы за год не учитываются расходы, списанные за счет резерва, созданного в предыдущем налоговом периоде.\n\n(Дополнение пунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 29.05.2002 № 57-ФЗ)","article_title":"Статья 324.1. Порядок учета расходов на формирование резерва предстоящих расходов на оплату отпусков, резерва на выплату ежегодного вознаграждения за выслугу лет","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bec69dc380fb7eeeae18b1002f65e63ed42f030fefebec97275af0005ceeb0b2"},{"code_id":"NK_RF_2","article_number":"325","version_date":"2000-07-31","article_text":"1. Налогоплательщики, принявшие решение о приобретении лицензий на право пользования недрами, в аналитических регистрах налогового учета обособленно отражают расходы, осуществляемые в целях приобретения лицензий. При этом расходы, связанные с приобретением каждой конкретной лицензии, учитываются отдельно.\n\nК расходам, осуществляемым в целях приобретения лицензии, в частности, относятся:\n\nрасходы, связанные с предварительной оценкой месторождения;\n\nрасходы, связанные с проведением аудита запасов месторождения;\n\nрасходы на разработку технико-экономического обоснования (иных аналогичных работ), проекта освоения месторождения;\n\nрасходы на приобретение геологической и иной информации;\n\nрасходы на оплату участия в конкурсе (аукционе). (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nВ случае, если налогоплательщик заключает лицензионное соглашение на право пользования недрами (получает лицензию), то расходы, осуществленные налогоплательщиком в целях приобретения лицензии, формируют стоимость лицензионного соглашения (лицензии), которая учитывается налогоплательщиком в составе нематериальных активов, амортизация которых начисляется в порядке, установленном статьями 256 - 2592 настоящего Кодекса, или по выбору налогоплательщика в составе прочих расходов, связанных с производством и реализацией, в течение двух лет. В случае, если налогоплательщик получает право пользования участком недр, на котором расположено новое морское месторождение углеводородного сырья или в границах которого предполагается осуществлять поиск, оценку, разведку и (или) разработку нового морского месторождения углеводородного сырья, суммы указанной амортизации либо указанных понесенных расходов учитываются при исчислении налоговой базы при осуществлении деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, в порядке, предусмотренном пунктом 7 статьи 261 настоящего Кодекса. Избранный налогоплательщиком порядок учета указанных расходов отражается в учетной политике для целей налогообложения. (В редакции федеральных законов от 22.07.2008 № 158-ФЗ; от 27.07.2010 № 229-ФЗ; от 30.09.2013 № 268-ФЗ)\n\nВ случае, если по результатам конкурса (аукциона) налогоплательщик не заключает лицензионное соглашение на право пользования недрами (не получает лицензию), то расходы, осуществленные в целях приобретения лицензии, включаются в состав прочих расходов с 1-го числа месяца, следующего за месяцем проведения конкурса (аукциона), равномерно в течение двух лет. В случае, если после осуществления предварительных расходов, осуществленных в целях приобретения лицензии, налогоплательщик принимает решение об отказе от участия в конкурсе (аукционе) либо о нецелесообразности приобретения лицензии, то указанные расходы также включаются в состав прочих расходов с первого числа месяца, следующего за месяцем, в котором налогоплательщиком принято указанное решение, равномерно в течение двух лет. При этом указанное решение оформляется соответствующим приказом (распоряжением) руководителя. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nВ аналогичном порядке учитываются расходы, осуществленные в целях приобретения лицензий на право пользования недрами, в случае, если указанные лицензии выдаются налогоплательщику без проведения конкурсов.\n\n2. Расходы на освоение природных ресурсов, предусмотренные пунктом 1 статьи 261 настоящего Кодекса, отражаются в аналитических регистрах налогового учета обособленно по каждому участку недр (месторождению) или участку территории (акватории), отраженному в лицензионном соглашении налогоплательщика (лицензии на право пользования недрами).\n\nПри этом в зависимости от конкретного вида расходов расходы группируются как:\n\nобщие расходы по осваиваемому участку (месторождению) в целом;\n\nрасходы, относящиеся к отдельным частям территории разрабатываемого участка;\n\nрасходы, относящиеся к конкретному объекту, создаваемому в процессе освоения участка.\n\nК общим расходам, в частности, относятся:\n\nрасходы на поиски и оценку месторождений полезных ископаемых (включая аудит запасов), разведку полезных ископаемых и (или) гидрогеологические изыскания, осуществляемые на участке недр в соответствии с предоставленными в установленном порядке лицензиями (разрешениями), а также расходы на приобретение необходимой геологической и иной информации у третьих лиц; (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nК расходам, относящимся к отдельным частям территории осваиваемого участка, относятся на основании первичных учетных документов расходы, в частности:\n\nрасходы на подготовку территории к ведению горных, строительных и других работ в соответствии с установленными требованиями к безопасности, охране земель, недр и других природных ресурсов;\n\nпрочие расходы, связанные с освоением части территории участка.\n\nСумма общих расходов учитывается по каждой части территории осваиваемого участка (месторождения) в доле, определяемой исходя из отношения суммы расходов, относящихся к отдельным частям территории осваиваемого участка, к общей сумме расходов, осуществленных по освоению данного участка (месторождения).\n\nК расходам, относящимся к конкретному объекту, создаваемому в процессе освоения участка, относятся расходы, непосредственно связанные со строительством сооружений, которые в дальнейшем на основании решения налогоплательщика могут быть признаны постоянно эксплуатируемыми объектами основных средств.\n\nНалогоплательщик организует налоговый учет указанных расходов по каждому договору и каждому объекту, связанному с освоением природных ресурсов.\n\nАналитические регистры налогового учета должны содержать информацию об окончании работ в разрезе каждого договора, связанного с указанными работами по каждому конкретному участку недр.\n\nРасходы, понесенные по договору с подрядчиком, включаются в состав прочих расходов с 1-го числа месяца, в котором подписан соответствующий акт выполненных работ (этапов работ) по данному договору (если иное не установлено пунктом 7 статьи 261 настоящего Кодекса). Понесенные расходы равными долями включаются в состав прочих расходов в сроки, предусмотренные статьей 261 настоящего Кодекса. (В редакции Федерального закона от 30.09.2013 № 268-ФЗ)\n\nТекущие расходы на содержание объектов, связанных с освоением природных ресурсов (в том числе расходы на оплату труда, расходы, связанные с содержанием и эксплуатацией временных сооружений, и иные подобные расходы), а также расходы на доразведку месторождения или его участков, находящихся в пределах горного или земельного отвода организации, в полной сумме включаются в состав расходов того отчетного (налогового) периода, в котором они произведены (если иное не установлено пунктом 7 статьи 261 настоящего Кодекса). При этом к расходам на доразведку относятся расходы, связанные с осуществлением работ по доразведке по введенным в эксплуатацию и промышленно освоенным месторождениям. (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 30.09.2013 № 268-ФЗ)\n\nУказанный порядок учета относится к расходам по всем геолого-поисковым и геолого-разведочным работам, в том числе осуществленным расходам по работам, признаваемым безрезультатными, бесперспективными, либо продолжение которых признано нецелесообразным (если иное не установлено пунктом 7 статьи 261 настоящего Кодекса). (В редакции Федерального закона от 30.09.2013 № 268-ФЗ)\n\nВ случае, если осваиваемый участок (часть территории осваиваемого участка) признается налогоплательщиком бесперспективным либо продолжение его освоения признается нецелесообразным, суммы расходов, осуществленные налогоплательщиком по освоению данного участка, включаются в состав прочих расходов в общем порядке, предусмотренном статьей 261 настоящего Кодекса (если иное не установлено пунктом 7 статьи 261 настоящего Кодекса). (В редакции Федерального закона от 30.09.2013 № 268-ФЗ)\n\nРасходы на строительство временных сооружений (в том числе временных подъездных путей и дорог; площадок, сооружений для хранения плодородного слоя почвы, добываемых пород, отходов; временных сооружений для проживания участников геолого-разведочных работ и иных подобных объектов) включаются в состав прочих расходов с 1-го числа месяца, следующего за месяцем, в котором закончены работы по их созданию на основании актов выполненных работ (если иное не установлено пунктом 7 статьи 261 настоящего Кодекса). (В редакции Федерального закона от 30.09.2013 № 268-ФЗ)\n\nВ случае, если переход (передача) права пользования участком (участками) недр происходит в связи с реорганизацией организации, учет расходов осуществляется в соответствии с пунктом 21 статьи 252 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 27.07.2010 № 229-ФЗ)","article_title":"Статья 325. Порядок ведения налогового учета расходов на освоение природных ресурсов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"838b18ddeee8098395164b2ce85599a8d18f9c96981df7b89ad1cd9163e17fab"},{"code_id":"NK_RF_2","article_number":"325.1","version_date":"2000-07-31","article_text":"1. В случае применения налогового вычета по налогу на добычу полезных ископаемых в соответствии со статьей 3431 настоящего Кодекса налогоплательщик обеспечивает обособленный учет расходов, связанных с обеспечением безопасных условий и охраны труда при добыче угля на данном участке недр, от других расходов, связанных с освоением этого участка недр.\n\n2. Расходы, связанные с обеспечением безопасных условий и охраны труда при добыче угля, осуществленные (понесенные) налогоплательщиком, учитываются отдельно по каждому участку недр в том отчетном (налоговом) периоде, в котором они произведены.\n\n3. При осуществлении (несении) указанных в пункте 2 настоящей статьи расходов, относящихся к нескольким участкам недр (в случае невозможности разделения расходов), в целях применения установленного статьей 3431 настоящего Кодекса налогового вычета указанные расходы учитываются отдельно по каждому участку недр в доле, определяемой налогоплательщиком в соответствии с принятой им учетной политикой для целей налогообложения.\n\n4. Перечень видов расходов, связанных с обеспечением безопасных условий и охраны труда при добыче угля, принимаемых к вычету из суммы налога на добычу полезных ископаемых, определяется Правительством Российской Федерации с учетом положений пункта 5 статьи 3431 настоящего Кодекса.\n\n5. Сумма расходов, не учтенная при исчислении налогового вычета в соответствии с порядком, установленным пунктом 4 статьи 3431 настоящего Кодекса, в течение 36 налоговых периодов по налогу на добычу полезных ископаемых, признается расходом налогоплательщика при исчислении налоговой базы по налогу на прибыль организаций в соответствии с главой 25 настоящего Кодекса в следующем порядке:\n\n1) расходы, указанные в подпункте 1 пункта 5 статьи 3431 настоящего Кодекса, учитываются равномерно в течение года начиная со дня, следующего за днем окончания признания таких расходов в соответствии со статьей 3431 настоящего Кодекса;\n\n2) расходы, указанные в подпунктах 2 и 3 пункта 5 статьи 3431 настоящего Кодекса, учитываются в порядке, установленном статьями 256 - 2593 настоящего Кодекса. При этом остаточной стоимостью амортизируемого имущества признается разница между первоначальной стоимостью, определяемой в установленном статьей 257 настоящего Кодекса порядке, и суммами, учтенными при применении налогового вычета по налогу на добычу полезных ископаемых в соответствии со статьей 3431 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 28.12.2010 № 425-ФЗ)","article_title":"Статья 325.1. Порядок налогового учета расходов, связанных с обеспечением безопасных условий и охраны труда при добыче угля","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"40573de368ea431de8377d782a2b15631a73b2a979c08f7e50421f67f924bf94"},{"code_id":"NK_RF_2","article_number":"326","version_date":"2000-07-31","article_text":"Налогоплательщик по операциям с производными финансовыми инструментами определяет налоговую базу на основании данных регистров налогового учета. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nДанные регистров налогового учета должны отражать порядок формирования суммы доходов (расходов) по срочным сделкам, учитываемым для целей налогообложения.\n\nАналитический учет требований (обязательств) по производным финансовым инструментам налогоплательщики обязаны вести по каждому виду производных финансовых инструментов. Аналитический учет прав требований (обязательств) ведется раздельно по операциям с производными финансовыми инструментами, обращающимися на организованном рынке, по операциям с производными финансовыми инструментами, не обращающимися на организованном рынке, а также по операциям, совершенным в целях хеджирования. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nДанные регистров налогового учета должны содержать в денежном выражении суммы требований (обязательств) налогоплательщика к контрагентам в соответствии с условиями заключенных договоров:\n\nпо поставочным срочным сделкам;\n\nпо расчетным срочным сделкам.\n\nТребования (обязательства) по производным финансовым инструментам, как обращающимся, так и не обращающимся на организованном рынке, не подлежат текущей переоценке в связи с изменением рыночной цены, рыночной котировки, курса валюты, значений процентных ставок, фондовых индексов или иных показателей базисного актива с учетом положений настоящей статьи. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nНалогоплательщики учитывают в составе налоговой базы изменение текущей стоимости производных финансовых инструментов, обращающихся на организованном рынке, в размере денежных сумм, рассчитанных биржей (клиринговой организацией). Указанное требование не распространяется на производные финансовые инструменты, в соответствии с условиями которых исполнение обязанности одной стороны производного финансового инструмента возникает в случае предъявления требований другой стороной указанной сделки, в том числе в зависимости от обстоятельств, в отношении которых заранее неизвестно, наступят они или не наступят. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nТребования (обязательства) по сделкам, квалифицированным как сделки на поставку предмета сделки с отсрочкой исполнения, также не подлежат текущей переоценке в связи с изменением рыночной цены, рыночной котировки, курса валюты, значений процентных ставок, фондовых индексов или иных показателей базисного актива с учетом положений настоящей\n\nНалогоплательщик на дату заключения сделки отражает в аналитическом учете сумму возникших требований (обязательств) к контрагентам, исходя из условий сделки и требований (обязательств) в отношении базисного актива (в том числе товаров, денежных средств, драгоценных металлов, ценных бумаг, процентных ставок).\n\nНалоговая база определяется налогоплательщиком на дату исполнения срочной сделки с учетом положений настоящей главы.\n\nПри поставке ценных бумаг, обращающихся на организованном рынке и являющихся базисным активом производного финансового инструмента, финансовый результат от операций с таким базисным активом определяется исходя из фактической цены поставки базисного актива в соответствии с условиями, на которых осуществляется исполнение производного финансового инструмента. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nЕсли по условиям производного финансового инструмента или срочной сделки, квалифицированной как сделка на поставку предмета сделки с отсрочкой исполнения, предусмотрено проведение промежуточных расчетов (за исключением авансов), в том числе при изменении стоимостной оценки требований (обязательств) в связи с изменением рыночной цены, рыночной котировки, курса валюты, значений процентных ставок, фондовых индексов или иных показателей базисного актива, налогоплательщик определяет доходы (расходы) на каждую дату проведения таких расчетов в соответствии с условиями указанной сделки. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nПремия по опционному контракту в соответствии с соглашением сторон независимо от его квалификации как производного финансового инструмента или как сделки с отсрочкой исполнения признается в соответствующих доходах (расходах) единовременно на дату осуществления расчетов по опционной премии в соответствии с условиями договора для налогоплательщиков, применяющих метод начисления, независимо от того, исполнен или не исполнен опционный контракт, а также независимо от вида базисного актива. (В редакции федеральных законов от 28.12.2013 № 420-ФЗ; от 03.07.2016 № 242-ФЗ)\n\nПри наступлении срока исполнения производного финансового инструмента налогоплательщик производит оценку требований и обязательств на дату его исполнения в соответствии с условиями его заключения и определяет сумму доходов (расходов), подлежащих включению в налоговую базу. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nНалогоплательщик выделяет для отдельного налогового учета операции с производными финансовыми инструментами, совершенные в целях компенсации возможных убытков, возникающих в результате неблагоприятного изменения цены или иного показателя базисного актива (объекта хеджирования). (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nСправка составляется налогоплательщиком по каждой операции хеджирования отдельно и содержит следующие данные:\n\nописание операции хеджирования, включающее наименование объекта хеджирования, типы страхуемых рисков (ценовой, валютный, кредитный, процентный или другие подобные риски), планируемые действия относительно объекта хеджирования (покупка, продажа, иные действия), производные финансовые инструменты, которые планируется использовать, условия исполнения сделок; (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nдату начала операции хеджирования, дату ее окончания и (или) ее продолжительность, промежуточные условия расчета. Дата начала операции хеджирования может устанавливаться путем закрепления порядка ее определения;\n\nобъем, дату и цену сделки (сделок) с объектом хеджирования (для ожидаемых (планируемых) сделок - объем, дату, цену и иные существенные условия сделки);\n\nобъем, дату и цену сделки (сделок) с производными финансовыми инструментами. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nСправка может содержать и иные сведения на усмотрение налогоплательщика, подтверждающие совершение операции в целях хеджирования.\n\nЕсли объектом хеджирования являются требования (обязательства), вытекающие из совокупности сделок, а также если объектом хеджирования является имущество налогоплательщика, дата начала и дата окончания операции хеджирования определяются налогоплательщиком самостоятельно на основании прогноза показателей объекта хеджирования.\n\nС учетом положений настоящей статьи и статей 301 - 305 настоящего Кодекса доходы (расходы), связанные с производными финансовыми инструментами, заключенными в целях компенсации неблагоприятных последствий, которые могут возникнуть для налогоплательщиков в результате изменения цены, курса валюты, значений процентных ставок, фондовых индексов или иных показателей объекта хеджирования, учитываются на конец отчетного (налогового) периода и на дату исполнения сделки (сделок) независимо от даты возникновения доходов (расходов), связанных с объектом хеджирования. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nПо окончании операции хеджирования доходы (расходы), связанные с производными финансовыми инструментами, определяются с учетом доходов (расходов), учтенных в налоговой базе в предыдущих налоговых периодах. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nЕсли объектом хеджирования являются требования (обязательства) по конкретной сделке, в случае ее досрочного расторжения (прекращения по иным основаниям) доходы (расходы), связанные с производными финансовыми инструментами, определяются на конец отчетного (налогового) периода, в котором произошло досрочное расторжение сделки (ее прекращение по иным основаниям) с объектом хеджирования, или на дату исполнения сделки (сделок), если указанная дата исполнения наступила ранее отчетной даты периода, и включаются в налоговую базу, при расчете которой учитываются доходы (расходы), связанные с объектом хеджирования. При этом доходы (расходы), связанные с производными финансовыми инструментами, возникающие после отчетной даты периода, в котором произошло досрочное расторжение указанной конкретной сделки, учитываются при определении налоговой базы с производными финансовыми инструментами с учетом доходов (расходов), учтенных ранее в налоговой базе по операциям, связанным с объектом хеджирования. (В редакции федеральных законов от 28.12.2013 № 420-ФЗ; от 03.07.2016 № 242-ФЗ)\n\nДоходы (расходы), связанные с досрочным расторжением производных финансовых инструментов (их прекращением по иным основаниям), используемых для операции хеджирования, учитываются в том же порядке и в той же налоговой базе, в которых учитываются доходы (расходы) по производным финансовым инструментам, используемым в целях хеджирования. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nДопускается превышение объема базисного актива производного финансового инструмента, обращающегося на организованном рынке и совершенного в целях хеджирования (инструмента хеджирования), над объемом объекта хеджирования в рамках одного инструмента хеджирования, если такое превышение обусловлено стандартизацией биржей объема базисного актива производного финансового инструмента. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nПревышение на конец отчетного (налогового) периода или на дату исполнения сделки расходов по производным финансовым инструментам, совершенных в целях хеджирования, а также расходов, понесенных в связи с соответствующими операциями хеджирования, над доходами по таким производным финансовым инструментам не влечет переквалификации операции хеджирования в обычные операции с производными финансовыми инструментами. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nВ целях определения доходов (расходов), учитываемых в налоговой базе, налогоплательщик вправе в учетной политике для целей налогообложения предусмотреть возможность осуществления текущей переоценки производных финансовых инструментов, используемых в целях хеджирования, в зависимости от изменения рыночной цены, рыночной котировки, курса валюты, значения процентной ставки, фондового индекса или иных показателей, характеризующих базисный актив, при условии, что объект хеджирования подлежит переоценке в соответствии с требованиями настоящего Кодекса. При этом доходы (расходы) в результате такой переоценки определяются на конец отчетного (налогового) периода в зависимости от изменения показателей, определенных в учетной политике для целей налогообложения, по отношению к соответствующим показателям, закрепленным производным финансовым инструментом. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nНалогоплательщик производит оценку требований (обязательств) на дату исполнения производного финансового инструмента в соответствии с ее условиями и определяет сумму доходов (расходов) с учетом сумм, ранее учтенных для целей налогообложения в составе доходов (расходов). (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nПо производным финансовым инструментам, предусматривающим куплю-продажу иностранной валюты, либо драгоценных металлов, либо ценных бумаг, номинированных в иностранной валюте, налогоплательщик на дату исполнения сделки определяет доходы (расходы) с учетом курсовых разниц, определенных как разница между закрепленным договором курсом иностранной валюты, по которому производится исполнение сделки, и установленным Центральным банком Российской Федерации официальным курсом иностранной валюты к рублю Российской Федерации и официальных цен на драгоценные металлы на дату исполнения сделки. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n(Статья в редакции Федерального закона от 25.11.2009 № 281-ФЗ)","article_title":"Статья 326. Порядок ведения налогового учета по срочным сделкам при применении метода начисления","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7277e16165ee826787a04d024a9b755a2d52d7e4df784f6905cf388382bd3268"},{"code_id":"NK_RF_2","article_number":"327","version_date":"2000-07-31","article_text":"Налогоплательщики, применяющие кассовый метод определения доходов и расходов, организуют налоговый учет в соответствии с изложенными в настоящей главе принципами. Исчисление доходов и расходов по операциям с производными финансовыми инструментами налогоплательщики, применяющие кассовый метод определения доходов и расходов, определяют на дату фактического поступления (перечисления) денежных средств. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)","article_title":"Статья 327. Порядок организации налогового учета по срочным сделкам при применении кассового метода","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c2e92924df36a5d0b25381596f20fa2d59523cfcf0b038b183f48cd7fd61bca7"},{"code_id":"NK_RF_2","article_number":"328","version_date":"2000-07-31","article_text":"1. Налогоплательщик на основании аналитического учета внереализационных доходов и расходов ведет расшифровку доходов (расходов) в виде процентов по ценным бумагам, по договорам займа, кредита, банковского счета, банковского вклада и (или) иным образом оформленным долговым обязательствам.\n\nВ аналитическом учете налогоплательщик самостоятельно отражает сумму доходов (расходов) в сумме причитающихся в соответствии с условиями указанных договоров (а по ценным бумагам - в соответствии с условиями эмиссии, по векселям - условиями выпуска или передачи (продажи)) процентов отдельно по каждому виду долгового обязательства с учетом статьи 269 настоящего Кодекса. (В редакции Федерального закона от 24.07.2002 № 110-ФЗ)\n\nСумма дохода (расхода) в виде процентов по долговым обязательствам учитывается в аналитическом учете исходя из установленной по каждому виду долговых обязательств доходности и срока действия такого долгового обязательства в отчетном периоде на дату признания доходов (расходов), определяемую в соответствии с положениями статей 271 - 273 настоящего Кодекса.\n\nНалогоплательщик, определяющий доходы (расходы) по методу начисления, определяет сумму дохода (расхода), полученного (выплаченного) либо подлежащего получению (выплате) в отчетном периоде в виде процентов, по каждому виду долговых обязательств, исходя из установленных условиями договора доходности и срока действия такого долгового обязательства в отчетном периоде с учетом положений настоящего пункта.\n\nПризнание доходов (расходов) в виде процентов по долговым обязательствам осуществляется налогоплательщиком, определяющим доходы (расходы) по методу начисления, ежемесячно независимо от срока их уплаты, предусмотренного договором, по которому срок его действия приходится более чем на один отчетный (налоговый) период. Налогоплательщик в аналитическом учете на основании справок ответственного лица, которому поручено ведение учета доходов (расходов) по долговым обязательствам, обязан отразить в составе доходов (расходов) сумму процентов, определяемую в порядке, установленном соответственно пунктом 6 статьи 271 и пунктом 8 статьи 272 настоящего Кодекса. Положения первого предложения настоящего абзаца не применяются к доходам (расходам) в виде процентов по долговым обязательствам в случаях, указанных в подпункте 14 пункта 4 статьи 271 и подпункте 12 пункта 7 статьи 272 настоящего Кодекса. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n(Пункт в редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\nЕсли налогоплательщик определяет доходы и расходы по кассовому методу, то проценты признаются полученными на дату поступления денежных средств. Основанием для включения таких сумм в состав доходов, полученных в виде процентов, является выписка банка о движении денежных средств на банковских счетах.\n\nЕсли налогоплательщик при определении доходов и расходов применяет метод начисления, то сумма процентов, полученная налогоплательщиком (причитающаяся налогоплательщику) по государственным и муниципальным ценным бумагам, признается доходом на дату реализации ценной бумаги, либо на дату выплаты таких процентов (погашения купона) в соответствии с условиями эмиссии, либо на последнюю дату отчетного периода в соответствии с положениями настоящей главы.\n\nЕсли в цену реализации государственных и муниципальных ценных бумаг включается накопленный купонный доход, то налогоплательщик самостоятельно на дату реализации таких ценных бумаг определяет сумму дохода в виде процентов на основании договора купли-продажи с учетом положений пунктов 6 и 7 настоящей статьи. (В редакции Федерального закона от 06.06.2005 № 58-ФЗ)\n\nПри этом доходом отчетного (налогового) периода в виде процентов признается разница между суммой накопленного процентного (купонного) дохода, исчисленной на конец отчетного (налогового) периода в соответствии с условиями эмиссии, и суммой накопленного процентного (купонного) дохода, исчисленной на конец предыдущего налогового периода, если после окончания предыдущего налогового периода не осуществлялось выплат процентов (погашений купона) эмитентом.\n\nЕсли в текущем отчетном (налоговом) периоде выплаты процентов (погашения купона) эмитентом осуществлялись, то в дополнение к доходу в виде процентов, исчисленному и учтенному при таких выплатах (погашениях) в соответствии с абзацем четвертым настоящего пункта, доход в виде процентов принимается равным сумме накопленного процентного (купонного) дохода, исчисленной на конец указанного отчетного (налогового) периода.\n\nПри первой выплате процентов (погашении купона) в отчетном (налоговом) периоде доход в виде процентов исчисляется как разница между суммой выплачиваемых процентов (погашаемого купона) и суммой накопленного процентного (купонного) дохода, исчисленной на конец предыдущего налогового периода. При последующих в отчетном (налоговом) периоде выплатах процентов (погашениях купона) доход в виде процентов принимается равным сумме выплачиваемых процентов (погашаемого купона).\n\nЕсли указанная ценная бумага приобретена в текущем налоговом периоде, то исчисление дохода в виде процентов осуществляется в соответствии с положениями абзацев первого - четвертого, где сумма накопленного процентного (купонного) дохода, исчисленная на конец предыдущего налогового периода, заменяется при вычислениях на сумму накопленного процентного (купонного) дохода, уплаченного налогоплательщиком продавцу ценной бумаги.\n\nПри реализации указанной ценной бумаги доход в виде процентов исчисляется в соответствии с положениями абзацев первого - четвертого настоящего пункта, где сумма накопленного процентного (купонного) дохода, исчисленная на конец отчетного (налогового) периода, заменяется при вычислениях на сумму накопленного процентного (купонного) дохода, исчисленную на дату реализации. (В редакции Федерального закона от 29.12.2014 № 478-ФЗ)\n\n(Статья в редакции Федерального закона от 29.05.2002 № 57-ФЗ)","article_title":"Статья 328. Порядок ведения налогового учета доходов (расходов) в виде процентов по договорам займа, кредита, банковского счета, банковского вклада, а также процентов по ценным бумагам и другим долговым обязательствам","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b6ddb6fe0a526e3756e2bf9453e5ac28fa51c315fc1affe417ed05e8d6c670f3"},{"code_id":"NK_RF_2","article_number":"329","version_date":"2000-07-31","article_text":"Доходом по операциям с цен\n\nными бумагами признается выручка от продажи ценных бумаг в соответствии с условиями договора реализации. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nДоходы и расходы по операциям с ценными бумагами признаются в соответствии с порядком, установленным статьей 271 или статьей 273 настоящего Кодекса, в зависимости от применяемого налогоплательщиком порядка признания доходов и расходов. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nПри реализации ценных бумаг расходом признается цена приобретения реализованных ценных бумаг, рассчитанная с учетом установленного налогоплательщиком метода учета ценных бумаг (ФИФО, по стоимости единицы). (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 28.12.2013 № 420-ФЗ)\n\nЕсли в цену реализации государственных и муниципальных ценных бумаг, обращающихся на организованном рынке ценных бумаг, включается часть накопленного купонного дохода, то сумма дохода и расхода по таким ценным бумагам исчисляется без накопленного купонного дохода.\n\nПрибыль (убыток) от реализации ценных бумаг при реализации ценных бумаг, обращающихся на организованном рынке ценных бумаг, и ценных бумаг, не обращающихся на организованном рынке ценных бумаг, в налоговом учете учитывается раздельно. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nПроцентный доход по государственным и муниципальным ценным бумагам, по которым предусмотрено исключение из цены сделки части накопленного процентного дохода, определяется на дату реализации на основании договора купли-продажи с учетом положений статьи 328 настоящего Кодекса и подлежит отражению в налоговом учете на основании справки ответственного лица, которое исчисляет прибыль (доход) по операциям с ценными бумагами. (Дополнение частью - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\nЧасть. (Дополнение частью - Федеральный закон от 28.12.2013 № 420-ФЗ) (Утратила силу - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nБанки и профессиональные участники рынка ценных бумаг вправе вести налоговый учет поступлений и выбытия ценных бумаг по соответствующим портфелям ценных бумаг, сформированным в зависимости от срока и целей их приобретения, в соответствии с требованиями Центрального банка Российской Федерации и (или) Министерства финансов Российской Федерации и применять один из методов, указанных в статье 280 настоящего Кодекса, в отношении каждого портфеля ценных бумаг. При этом порядок такого учета должен быть закреплен в учетной политике налогоплательщика для целей налогообложения. (Дополнение частью - Федеральный закон от 28.12.2013 № 420-ФЗ)","article_title":"Статья 329. Порядок ведения налогового учета при реализации ценных бумаг","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5a1a2d307af4653817ef0dc2493d6b1249acd28642d8864540a236c448d87493"},{"code_id":"NK_RF_2","article_number":"330","version_date":"2000-07-31","article_text":"Налогоплательщики - страховые организации ведут налоговый учет доходов (расходов), полученных (понесенных) по договорам страхования, сострахования, перестрахования, по заключенным договорам, по видам страхования.\n\nДоходы налогоплательщика в виде всей суммы страхового взноса, причитающейся к получению, признаются на дату возникновения ответственности налогоплательщика перед страхователем по заключенному договору, вытекающей из условий договоров страхования, сострахования, перестрахования, вне зависимости от порядка уплаты страхового взноса, указанного в соответствующем договоре (за исключением договоров страхования жизни и пенсионного страхования). По договорам страхования жизни и пенсионного страхования доход в виде части страхового взноса признается в момент возникновения у налогоплательщика права на получение очередного страхового взноса в соответствии с условиями указанных договоров. (В редакции Федерального закона от 24.07.2007 № 216-ФЗ)\n\nНалогоплательщик в порядке и на условиях, которые установлены законодательством Российской Федерации, образует страховые резервы. Налогоплательщики отражают изменение размеров страховых резервов по видам страхования.\n\nСтраховые выплаты по договору, подлежащие выплате в соответствии с условиями указанного договора, включаются в состав расходов на дату возникновения у налогоплательщика обязательства по выплате страхового возмещения в пользу страхователя либо застрахованных лиц (при страховании ответственности - выгодоприобретателя) по фактически наступившему страховому случаю, выраженного в абсолютной денежной сумме, которая должна быть рассчитана в соответствии с законодательством Российской Федерации и правилами страхования. Доход (расход) в виде сумм возмещений доли страховых выплат признается на дату возникновения обязательства у перестраховщика по оплате перестрахователю по фактически наступившему страховому случаю, выраженному в абсолютной денежной сумме, согласно условиям договора перестрахования.\n\nСуммы возмещений, причитающиеся налогоплательщику в результате удовлетворения регрессных исков либо признанные виновными лицами, признаются доходом:\n\nна дату вступления в законную силу решения суда;\n\nна дату письменного обязательства виновного лица по возмещению причиненных убытков.\n\nПри этом доля указанных сумм, подлежащих возмещению перестраховщикам от перестрахователя, включается в доходы (расходы) перестрахователя и перестраховщика соответственно, в момент, установленный для указанных налогоплательщиков в соответствии с настоящей статьей.\n\nНалогоплательщик ведет учет страховых премий (взносов) по договорам сострахования в части, приходящейся на долю налогоплательщика в соответствии с условиями этих договоров.\n\nДоход налогоплательщика, осуществляющего обязательное медицинское страхование, в виде средств, полученных от территориальных фондов обязательного медицинского страхования, признается на дату перечисления указанных средств, определенную договором финансирования, в размере, определяемом исходя из порядка финансирования, указанного в таком договоре. (Дополнение частью - Федеральный закон от 29.12.2004 № 204-ФЗ)\n\nСтраховые выплаты по договору обязательного страхования гражданской ответственности владельцев транспортных средств, осуществленные от имени налогоплательщика - страховой организации другим страховщиком - участником соглашения о прямом возмещении убытков в соответствии с законодательством Российской Федерации об обязательном страховании гражданской ответственности владельцев транспортных средств, включаются в состав расходов на дату поступления от страховщика, осуществившего прямое возмещение убытков, требования об оплате возмещенного им вреда потерпевшему. (Дополнение частью - Федеральный закон от 25.12.2008 № 282-ФЗ)\n\nПризнание доходов, указанных в подпунктах 111 и 112 пункта 2 статьи 293 настоящего Кодекса, и расходов, указанных в подпунктах 91 и 92 пункта 2 статьи 294 настоящего Кодекса, осуществляется в случае, если исполнение обязательств между страховщиками по соглашению о прямом возмещении убытков осуществляется исходя из числа удовлетворенных требований в течение отчетного периода и средних сумм страховых выплат. Определение указанных доходов и расходов осуществляется по итогам каждого отчетного периода путем сопоставления совокупных сумм накопленных положительных и отрицательных разниц, возникших в результате осуществления расчетов с каждым отдельным страховщиком. При этом учитываются только те операции по прямому возмещению убытков, по которым завершены расчеты на конец отчетного (налогового) периода:\n\nу страховщика, застраховавшего гражданскую ответственность потерпевшего, при условиях, что выплата потерпевшему осуществлена и получено ее возмещение в размере средней суммы страховой выплаты от страховщика, застраховавшего гражданскую ответственность лица, причинившего вред;\n\nу страховщика, застраховавшего гражданскую ответственность лица, причинившего вред, при условиях, что страховая выплата, осуществленная страховщиком, застраховавшим гражданскую ответственность потерпевшего, признана расходом и осуществлено ее возмещение в размере средней суммы страховой выплаты.\n\n(Дополнение частью - Федеральный закон от 15.11.2010 № 300-ФЗ)\n\nОперации по прямому возмещению убытков, по которым расчеты не завершены, учитываются в следующем отчетном (налоговом) периоде. (Дополнение частью - Федеральный закон от 15.11.2010 № 300-ФЗ)\n\nОсобенности, предусмотренные положениями частей первой - седьмой настоящей статьи, распространяются на налоговый учет доходов и расходов организации, осуществляющей деятельность по страхованию экспортных кредитов и инвестиций от предпринимательских и (или) политических рисков в соответствии с Федеральным законом от 8 декабря 2003 года № 164-ФЗ \"Об основах государственного регулирования внешнеторговой деятельности\". (Дополнение частью - Федеральный закон от 07.06.2013 № 131-ФЗ) (В редакции Федерального закона от 15.04.2019 № 63-ФЗ)\n\n(Статья в редакции Федерального закона от 29.05.2002 № 57-ФЗ)","article_title":"Статья 330. Особенности ведения налогового учета доходов и расходов страховых организаций","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4048d4dcb3f60d191c77c28ecf330955686328c4d1a97b0ec1abfe05ad370791"},{"code_id":"NK_RF_2","article_number":"331","version_date":"2000-07-31","article_text":"Налогоплательщики-банки ведут налоговый учет доходов и расходов, полученных от (понесенных при) осуществления банковской деятельности, на основании отражения операций и сделок в аналитическом учете в соответствии с установленным настоящей главой порядком признания дохода и расхода.\n\nАналитический учет доходов и расходов, полученных (понесенных) в виде процентов по долговым обязательствам, ведется в соответствии с порядком, предусмотренным статьей 328 настоящего Кодекса.\n\nДоходы и расходы по хозяйственным и другим операциям, относящимся к будущим отчетным периодам, по которым были произведены в текущем отчетном периоде авансовые платежи, учитываются в сумме средств, подлежащих отнесению на расходы при наступлении того отчетного периода, к которому они относятся. Аналитический учет доходов и расходов по хозяйственным операциям ведется в разрезе каждого договора с отражением даты и суммы полученного (выплаченного) аванса и периода, в течение которого указанная сумма относится на доходы и расходы.\n\nКомиссионные сборы за услуги по корреспондентским отношениям, уплаченные налогоплательщиком, расходы по расчетно-кассовому обслуживанию, открытию счетов в других банках и другим аналогичным операциям относятся на расходы на дату совершения операции, если в соответствии с договором предусмотрены расчеты по каждой конкретной операции, либо на последнее число отчетного (налогового) периода. В аналогичном порядке налогоплательщиком ведется учет по доходам, связанным с осуществлением операций по расчетно-кассовому обслуживанию клиентов, корреспондентским отношениям и другим аналогичным операциям. (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 27.07.2006 № 137-ФЗ)\n\nЧасть. (Утратила силу - Федеральный закон от 28.11.2015 № 328-ФЗ)\n\nЧасть. (Утратила силу - Федеральный закон от 28.12.2010 № 395-ФЗ)\n\nПо сделкам, связанным с операцией купли-продажи драгоценных камней, налогоплательщик отражает в налоговом учете количественную и стоимостную (масса и цена) характеристику приобретенных и реализованных драгоценных камней. Переоценка покупной стоимости драгоценных камней на прейскурантные цены не признается доходом (расходом) налогоплательщика. При выбытии реализованных драгоценных камней доход (убыток) определяется в виде разницы между ценой реализации и учетной стоимостью. Под учетной стоимостью понимается цена приобретения драгоценных камней.\n\nАналитический учет ведется по каждому договору купли-продажи драгоценных камней. В аналитическом учете отражаются даты совершения операций купли-продажи, цена покупки, цена продажи, количественные и качественные характеристики драгоценных камней.","article_title":"Статья 331. Особенности ведения налогового учета доходов и расходов банков","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9fc9e60a7b12c7fb05a355bd69491f4be7ce12b6c4630d839b44b298f892e5a4"},{"code_id":"NK_RF_2","article_number":"331.1","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 18.07.2011 № 239-ФЗ) (Утратила силу  - Федеральный закон от 23.11.2020 № 374-ФЗ)","article_title":"Статья 331.1. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fad3230cb0b01dfa5709ecf68bc1425a8a2de77ef38df97ceeb7e57747becb6d"},{"code_id":"NK_RF_2","article_number":"332","version_date":"2000-07-31","article_text":"Налогоплательщик - организация, которая по условиям договора доверительного управления является управляющей имуществом, обязана вести раздельный аналитический учет по доходам и расходам, связанным с исполнением договора доверительного управления, и по доходам, полученным в виде вознаграждения от доверительного управления, в разрезе каждого договора доверительного управления. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nАналитический учет должен обеспечить информацию, позволяющую определить учредителя договора доверительного управления и выгодоприобретателя, дату вступления в силу и дату прекращения договора доверительного управления, стоимость и состав полученного в доверительное управление имущества, порядок и сроки расчетов по доверительному управлению. При совершении операций с имуществом, полученным в доверительное управление, доходы и расходы отражаются в соответствии с установленными настоящей главой правилами формирования доходов и расходов. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nДоходы учредителя управления и доверительного управляющего по договору доверительного управления формируются в каждом отчетном (налоговом) периоде независимо от того, предусмотрено ли таким договором осуществление расчетов в течение срока действия договора доверительного управления или нет. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nСумма вознаграждения доверительному управляющему признается расходом по договору доверительного управления и уменьшает сумму дохода, полученного от операций с имуществом, переданным в доверительное управление. Если выгодоприобретателем по договору доверительного управления предусмотрено третье лицо - выгодоприобретатель, то расходы (убытки) (за исключением вознаграждения) при исполнении договора доверительного управления не уменьшают доходы, полученные учредителем договора доверительного управления по другим основаниям. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nПри возврате амортизируемого имущества учредителю договора доверительного управления такое имущество подлежит включению в ту же амортизационную группу, начисление амортизации осуществляется по тем же ставкам и в том же порядке, что и до начала договора доверительного управления. Начисленная за весь период эксплуатации такого имущества амортизация до даты возврата учредителю договора доверительного управления учитывается при определении остаточной стоимости такого имущества. Если выгодоприобретателем является третье лицо, то при возврате имущества расходы (убытки) от снижения стоимости такого имущества не принимаются в уменьшение налоговой базы учредителя.","article_title":"Статья 332. Особенности ведения налогового учета доходов и расходов при исполнении договора доверительного управления имуществом","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2e84aa08c1463da83e50d94ca981cb66ea7fb40bbac0000302d4af65910e9ee9"},{"code_id":"NK_RF_2","article_number":"332.1","version_date":"2000-07-31","article_text":"1. В аналитическом учете налогоплательщик формирует сумму расходов на научные исследования и (или) опытно-конструкторские разработки с учетом группировки по видам работ (договорам) всех осуществленных расходов, включая стоимость расходных материалов и энергии, амортизацию объектов основных средств и нематериальных активов, используемых при выполнении научных исследований и (или) опытно-конструкторских разработок, расходы на оплату труда работников, выполняющих научные исследования и (или) опытно-конструкторские разработки, другие расходы, непосредственно связанные с выполнением научных исследований и (или) опытно-конструкторских разработок собственными силами, а также с учетом затрат на оплату работ по договорам на выполнение научно-исследовательских работ, договорам на выполнение опытно-конструкторских и технологических работ.\n\n2. Данные регистров налогового учета должны содержать информацию:\n\n1) о суммах расходов на научные исследования и (или) опытно-конструкторские разработки с учетом группировки по видам работ (договорам);\n\n2) о суммах расходов по статьям расходов (амортизация объектов основных средств, амортизация объектов нематериальных активов, оплата труда работников, материальные расходы, прочие расходы, непосредственно связанные с выполнением научных исследований и (или) опытно-конструкторских разработок) по каждому виду научных исследований и (или) опытно-конструкторских разработок, выполняемых собственными силами;\n\n3) о суммах расходов на научные исследования и (или) опытно-конструкторские разработки, осуществленных в отчетном (налоговом) периоде в форме отчислений на формирование фондов поддержки научной, научно-технической и инновационной деятельности, созданных в соответствии с Федеральным законом \"О науке и государственной научно-технической политике\";\n\n4) о суммах расходов на научные исследования и (или) опытно-конструкторские разработки, осуществленных в отчетном (налоговом) периоде за счет резерва предстоящих расходов на научные исследования и (или) опытно-конструкторские разработки, - для налогоплательщика, формирующего указанный резерв;\n\n5) о суммах расходов на научные исследования и (или) опытно-конструкторские разработки, давшие положительный результат и не давшие положительного результата, включенных в состав прочих расходов отчетного (налогового) периода;\n\n6) о суммах расходов на научные исследования и (или) опытно-конструкторские разработки, давшие положительный результат и не давшие положительного результата, включенных в состав прочих расходов отчетного (налогового) периода с применением повышающего коэффициента. (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\n3. Если налогоплательщик создал резерв предстоящих расходов на научные исследования и (или) опытно-конструкторские разработки в соответствии со статьей 2672 настоящего Кодекса, расходы, осуществляемые при реализации программ проведения научных исследований и (или) опытно-конструкторских разработок, уменьшающие сумму указанного резерва, отражаются в регистрах налогового учета в порядке, установленном настоящей статьей.\n\n(Дополнение статьей - Федеральный закон от 07.06.2011 № 132-ФЗ)","article_title":"Статья 332.1. Особенности ведения налогового учета расходов на научные исследования и (или) опытно-конструкторские разработки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"835b694036e6aa7ba8b1e8da80d6a65240f5b05c5208c761c78edeca5ca4323e"},{"code_id":"NK_RF_2","article_number":"333","version_date":"2000-07-31","article_text":"Аналитический учет операций РЕПО ведется на отдельно выделенных для этих целей аналитических регистрах налогового учета в отношении каждой операции, для денежных средств в иностранной валюте - в двойной оценке: в иностранной валюте и рублях.\n\nУчет стоимости ценных бумаг, подлежащих передаче при исполнении второй части РЕПО, осуществляет налогоплательщик, являющийся продавцом по первой части РЕПО.\n\nПокупатель по первой части РЕПО осуществляет учет стоимости ценных бумаг за период с даты приобретения ценных бумаг по первой части РЕПО по дату их реализации по второй части РЕПО.\n\nВ аналитическом учете отражаются дата реализации (приобретения) и стоимость реализованных (приобретенных) ценных бумаг по первой части РЕПО, дата приобретения (реализации) и стоимость ценных бумаг, подлежащих приобретению (реализации) при исполнении второй части РЕПО.\n\nВ случаях, если объектом операции РЕПО выступают ценные бумаги, номинированные в иностранной валюте, возникающие у покупателя (продавца) по первой части РЕПО обязательства (требования) по их обратному выкупу не подлежат переоценке в связи с изменением официальных курсов иностранных валют к рублю Российской Федерации, установленных Центральным банком Российской Федерации.\n\nОбязательства (требования) по денежным средствам в иностранной валюте по второй части РЕПО, когда доходы (расходы) по операции РЕПО рассматриваются в соответствии с пунктами 3 и 4 статьи 282 настоящего Кодекса как проценты по займу, предоставленному (полученному) ценными бумагами, подлежат переоценке, проводимой в связи с изменением официального курса иностранной валюты к рублю Российской Федерации, установленного Центральным банком Российской Федерации.\n\nОбязательства (требования) по денежным средствам в иностранной валюте по возврату (получению) привлеченных (размещенных) средств в случаях, если доходы (расходы) по операции РЕПО признаются в соответствии с пунктами 3 и 4 статьи 282 настоящего Кодекса как проценты по размещенным (привлеченным) средствам, подлежат переоценке, проводимой в связи с изм\n\nенением официального курса иностранной валюты к рублю Российской Федерации, установленного Центральным банком Российской Федерации. (Дополнение частью - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\nСумма денежных обязательств (требований), подлежащих переоценке в связи с изменением официального курса иностранной валюты к рублю Российской Федерации, установленного Центральным банком Российской Федерации, может быть изменена, если в соответствии с условиями договора репо выплаты эмитента по ценным бумагам либо предусмотренные договором денежные расчеты в случае изменения цены ценных бумаг или в иных случаях, предусмотренных договором репо, в период между датами исполнения первой и второй частей РЕПО уменьшают сумму денежных средств, подлежащих уплате продавцом по первой части РЕПО при последующем приобретении ценных бумаг по второй части РЕПО.\n\nРезультат указанной переоценки учитывается в составе внереализационных доходов (расходов) организации.\n\n(Статья в редакции Федерального закона от 25.11.2009 № 281-ФЗ)\n\nГЛАВА 251. СБОРЫ ЗА ПОЛЬЗОВАНИЕ ОБЪЕКТАМИ ЖИВОТНОГО МИРА И ЗА ПОЛЬЗОВАНИЕ ОБЪЕКТАМИ ВОДНЫХ БИОЛОГИЧЕСКИХ РЕСУРСОВ\n\n(Дополнение главой - Федеральный закон от 11.11.2003 № 148-ФЗ)","article_title":"Статья 333. Особенности ведения налогового учета доходов (расходов) по операциям РЕПО","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c4aad9450a15895c208910bdcbb229bb7d3fca778494deaff7f4c8283a839158"},{"code_id":"NK_RF_2","article_number":"333.10","version_date":"2000-07-31","article_text":"1. По каждому виду водопользования, признаваемому объектом налогообложения в соответствии со статьей 3339 настоящего Кодекса, налоговая база определяется налогоплательщиком отдельно в отношении каждого водного объекта.\n\nВ случае, если в отношении водного объекта установлены различные налоговые ставки, налоговая база определяется налогоплательщиком применительно к каждой налоговой ставке.\n\n2. При заборе воды налоговая база определяется как объем воды, забранной из водного объекта за налоговый период.\n\nОбъем воды, забранной из водного объекта, определяется на основании показаний водоизмерительных приборов, отражаемых в журнале первичного учета использования воды.\n\nВ случае отсутствия водоизмерительных приборов объем забранной воды определяется исходя из времени работы и производительности технических средств. В случае невозможности определения объема забранной воды исходя из времени работы и производительности технических средств объем забранной воды определяется исходя из норм водопотребления.\n\nПлощадь предоставленного водного пространства определяется по данным лицензии на водопользование (договора на водопользование), а в случае отсутствия в лицензии (договоре) таких данных по материалам соответствующей технической и проектной документации.","article_title":"Статья 333.10. Налоговая база","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5b3b9c8594e39e2487f5b2f9a0fd1beec3dd1cfe6765bd4496067addc3772c12"},{"code_id":"NK_RF_2","article_number":"333.11","version_date":"2000-07-31","article_text":"Налоговым периодом признается квартал.","article_title":"Статья 333.11. Налоговый период","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8993f368d451eb3472af0d372cf560b5fbf228c1b16b470c32ddc868034ce820"},{"code_id":"NK_RF_2","article_number":"333.12","version_date":"2000-07-31","article_text":"1. Налоговые ставки устанавливаются по бассейнам рек, озер, морей и экономическим районам в следующих размерах:\n\n1) при заборе воды из:\n\nповерхностных водных объектов в пределах установленных квартальных (годовых) лимитов водопользования и подземных водных объектов в пределах установленного в лицензии на пользование недрами для добычи подземных вод разрешенного (предельно допустимого) водоотбора в сутки (год): (В редакции Федерального закона от 24.11.2014 № 366-ФЗ)\n\nСеверная Двина\n\nПрочие реки и озера\n\nСеверо-Западный\n\nЗападная Двина\n\nПрочие реки и озера\n\nЦентральный\n\nЗападная Двина\n\nПрочие реки и озера\n\nВолго-Вятский\n\nСеверная Двина\n\nПрочие реки и озера\n\nЦентрально-Черноземный\n\nПрочие реки и озера\n\nПоволжский\n\nПрочие реки и озера\n\nСеверо-Кавказский\n\nПрочие реки и озера\n\nПрочие реки и озера\n\nЗападно-Сибирский\n\nПрочие реки и озера\n\nВосточно-Сибирский\n\nОзеро Байкал и его бассейн\n\nПрочие реки и озера\n\nДальневосточный\n\nПрочие реки и озера\n\nКалининградская область\n\nПрочие реки и озера\n\nтерриториального моря Российской Федерации и внутренних морских вод в пределах установленных квартальных (годовых) лимитов водопользования:\n\nБалтийское\n\nКаспийское\n\nВосточно-Сибирское\n\nТихий океан (в пределах территориального моря Российской Федерации)\n\n2) при использовании акватории:\n\nповерхностных водных объектов, за исключением сплава древесины в плотах и кошелях: (В редакции Федерального закона от 04.12.2006 № 201-ФЗ)\n\nСеверо-Западный\n\nЦентральный\n\nВолго-Вятский\n\nЦентрально-Черноземный\n\nПоволжский\n\nСеверо-Кавказский\n\nЗападно-Сибирский\n\nВосточно-Сибирский\n\nДальневосточный\n\nКалининградская область\n\nтерриториального моря Российской Федерации и внутренних морских вод:\n\nБалтийское\n\nКаспийское\n\nВосточно-Сибирское\n\nТихий океан (в пределах территориального моря Российской Федерации)\n\n3) при использовании водных объектов без забора воды для целей гидроэнергетики:\n\nРеки бассейнов Ладожского и Онежского озер и озера Ильмень\n\nПрочие реки бассейна Балтийского моря\n\nСеверная Двина\n\nПрочие реки бассейна Белого моря\n\nРеки бассейна Баренцева моря\n\nБассейн озера Байкал и река Ангара\n\nРеки бассейна Восточно-Сибирского моря\n\nРеки бассейнов Чукотского и Берингова морей\n\nПрочие реки и озера\n\n4) при использовании водных объектов для целей сплава древесины в плотах и кошелях: (В редакции Федерального закона от 04.12.2006 № 201-ФЗ)\n\nРеки бассейнов Ладожского и Онежского озер и озера Ильмень\n\nПрочие реки бассейна Балтийского моря\n\nСеверная Двина\n\nПрочие реки бассейна Белого моря\n\nПрочие реки и озера, по которым осуществляется сплав древесины в плотах и кошелях\n\n(В редакции Федерального закона от 04.12.2006 № 201-ФЗ)\n\n11. Налоговые ставки, установленные в пункте 1 настоящей статьи с учетом положений пунктов 2, 4 и 5 настоящей статьи, применяются в 2015 году с коэффициентом 1,15, в 2016 году - с коэффициентом 1,32, в 2017 году - с коэффициентом 1,52, в 2018 году - с коэффициентом 1,75, в 2019 году - с коэффициентом 2,01, в 2020 году - с коэффициентом 2,31, в 2021 году - с коэффициентом 2,66, в 2022 году - с коэффициентом 3,06, в 2023 году - с коэффициентом 3,52, в 2024 году - с коэффициентом 4,05, в 2025 году - с коэффициентом 4,65.\n\nНачиная с 2026 года налоговые ставки, указанные в пункте 1 настоящей статьи, применяются с коэффициентами, определенными в соответствии с настоящим пунктом для года, предшествующего году налогового периода, умноженными на коэффициент, учитывающий фактическое изменение (в среднем за год) потребительских цен на товары (работы, услуги) в Российской Федерации, определенный федеральным органом исполнительной власти, осуществляющим функции по нормативно-правовому регулированию в сфере анализа и прогнозирования социально-экономического развития, в соответствии с данными государственной статистической отчетности для второго по порядку года, предшествующего году налогового периода.\n\nНалоговая ставка с учетом указанных коэффициентов округляется до полного рубля в соответствии с действующим порядком округления.\n\n(Дополнение пунктом - Федеральный закон от 24.11.2014 № 366-ФЗ)\n\nПри добыче подземных вод сверх установленного в лицензии на пользование недрами для добычи подземных вод разрешенного (предельно допустимого) водоотбора в сутки (год) в расчете за налоговый период налоговые ставки в части такого превышения устанавливаются в пятикратном размере налоговых ставок, установленных пунктом 1 настоящей статьи с учетом коэффициентов, установленных пунктом 11 настоящей статьи. В случае отсутствия у налогоплательщика установленного в лицензии на пользование недрами для добычи подземных вод разрешенного (предельно допустимого) водоотбора в сутки (год) в расчете по кварталам квартальные значения определяются расчетно как одна четвертая утвержденного годового объема. (Дополнение абзацем - Федеральный закон от 24.11.2014 № 366-ФЗ)\n\nс 1 января по 31 декабря 2015 года включительно - в размере 81 рубля за одну тысячу кубических метров водных ресурсов, забранных (изъятых) из водного объекта;\n\nс 1 января по 31 декабря 2016 года включительно - в размере 93 рублей за одну тысячу кубических метров водных ресурсов, забранных (изъятых) из водного объекта;\n\nс 1 января по 31 декабря 2017 года включительно - в размере 107 рублей за одну тысячу кубических метров водных ресурсов, забранных (изъятых) из водного объекта;\n\nс 1 января по 31 декабря 2018 года включительно - в размере 122 рублей за одну тысячу кубических метров водных ресурсов, забранных (изъятых) из водного объекта;\n\nс 1 января по 31 декабря 2019 года включительно - в размере 141 рубля за одну тысячу кубических метров водных ресурсов, забранных (изъятых) из водного объекта;\n\nс 1 января по 31 декабря 2020 года включительно - в размере 162 рублей за одну тысячу кубических метров водных ресурсов, забранных (изъятых) из водного объекта;\n\nс 1 января по 31 декабря 2021 года включительно - в размере 186 рублей за одну тысячу кубических метров водных ресурсов, забранных (изъятых) из водного объекта;\n\nс 1 января по 31 декабря 2022 года включительно - в размере 214 рублей за одну тысячу кубических метров водных ресурсов, забранных (изъятых) из водного объекта;\n\nс 1 января по 31 декабря 2023 года включительно - в размере 246 рублей за одну тысячу кубических метров водных ресурсов, забранных (изъятых) из водного объекта;\n\nс 1 января по 31 декабря 2024 года включительно - в размере 283 рублей за одну тысячу кубических метров водных ресурсов, забранных (изъятых) из водного объекта;\n\nс 1 января по 31 декабря 2025 года включительно - в размере 326 рублей за одну тысячу кубических метров водных ресурсов, забранных (изъятых) из водного объекта.\n\nНачиная с 2026 года ставка водного налога при заборе (изъятии) водных ресурсов из водных объектов для водоснабжения населения определяется ежегодно путем умножения ставки водного налога для этого вида водопользования, действовавшей в предыдущем году, на коэффициент, учитывающий фактическое изменение (в среднем за год) потребительских цен на товары (работы, услуги) в Российской Федерации, определенный федеральным органом исполнительной власти, осуществляющим функции по нормативно-правовому регулированию в сфере анализа и прогнозирования социально-экономического развития, в соответствии с данными государственной статистической отчетности для второго по порядку года, предшествующего году налогового периода.\n\n(Пункт в редакции Федерального закона от 24.11.2014 № 366-ФЗ)","article_title":"Статья 333.12. Налоговые ставки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6739de4751fc1488a01588b094bc79d0139851c483bdbe3bad9f99680b79f1f5"},{"code_id":"NK_RF_2","article_number":"333.13","version_date":"2000-07-31","article_text":"1. Налогоплательщик исчисляет сумму налога самостоятельно.","article_title":"Статья 333.13. Порядок исчисления налога","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a4f847432a804e5a661992e4e5ee19a83d7951d9e3eb123af998e2044b2b39fe"},{"code_id":"NK_RF_2","article_number":"333.14","version_date":"2000-07-31","article_text":"1. Общая сумма налога, исчисленная в соответствии с пунктом 3 статьи 33313 настоящего Кодекса, уплачивается по местонахождению объекта налогообложения.","article_title":"Статья 333.14. Порядок и сроки уплаты налога","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9e9af861fe2a40f7e0459d39f61978a7fa4f63c503c33d3e87ef8c189087e36a"},{"code_id":"NK_RF_2","article_number":"333.15","version_date":"2000-07-31","article_text":"При этом налогоплательщики, в соответствии со статьей 83 настоящего Кодекса отнесенные к категории крупнейших, представляют налоговые декларации (расчеты) в налоговый орган по месту учета в качестве крупнейших налогоплательщиков. (Дополнение абзацем - Федеральный закон от 30.12.2006 № 268-ФЗ)\n\nГЛАВА 253. ГОСУДАРСТВЕННАЯ ПОШЛИНА\n\n(Дополнение главой - Федеральный закон от 02.11.2004 № 127-ФЗ)","article_title":"Статья 333.15. Налоговая декларация","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"179dcb0e01b6d27ecb396ae53661ca5425a9b70f887ee08cfe9bbb558ac09f66"},{"code_id":"NK_RF_2","article_number":"333.16","version_date":"2000-07-31","article_text":"В целях настоящей главы выдача документов (их дубликатов) приравнивается к юридически значимым действиям. (В редакции Федерального закона от 27.12.2009 № 374-ФЗ)","article_title":"Статья 333.16. Государственная пошлина","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d918ad00eebe01bd1ea55c43b787db2b0d5487b2c096d570448ae2e7d43dff67"},{"code_id":"NK_RF_2","article_number":"333.17","version_date":"2000-07-31","article_text":"1. Плательщиками государственной пошлины (далее в настоящей главе - плательщики) признаются:\n\n1) организации;\n\n2) физические лица.\n\n2. Указанные в пункте 1 настоящей статьи лица признаются плательщиками в случае, если они:\n\n1) обращаются за совершением юридически значимых действий, предусмотренных настоящей главой;\n\n2) выступают ответчиками (административными ответчиками) в судах общей юрисдикции, Верховном Суде Российской Федерации, арбитражных судах или по делам, рассматриваемым мировыми судьями, и если при этом решение суда принято не в их пользу и истец (административный истец) освобожден от уплаты государственной пошлины в соответствии с настоящей главой. (В редакции Федерального закона от 08.03.2015 № 23-ФЗ)","article_title":"Статья 333.17. Плательщики государственной пошлины","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"396941c6010e84bd6c757b4857c2cc00488d5ddd036bb9c79ae083a498bef370"},{"code_id":"NK_RF_2","article_number":"333.18","version_date":"2000-07-31","article_text":"1. Плательщики уплачивают государственную пошлину, если иное не установлено настоящей главой, в следующие сроки:\n\n1) при обращении в Конституционный Суд Российской Федерации, Верховный Суд Российской Федерации, суды общей юрисдикции, арбитражные суды или к мировым судьям - до подачи запроса, ходатайства, заявления, искового заявления, административного искового заявления, жалобы; (В редакции Федерального закона от 08.03.2015 № 23-ФЗ)\n\n2) плательщики, указанные в подпункте 2 пункта 2 статьи 33317 настоящего Кодекса, - в десятидневный срок со дня вступления в законную силу решения суда;\n\n3) при обращении за совершением нотариальных действий - до совершения нотариальных действий;\n\n4) при обращении за выдачей документов (их дубликатов) - до выдачи документов (их дубликатов); (В редакции Федерального закона от 27.12.2009 № 374-ФЗ)\n\n5) при обращении за проставлением апостиля - до проставления апостиля;\n\n51) при обращении за ежегодным подтверждением регистрации судна в Российском международном реестре судов - не позднее 31 марта года, следующего за годом регистрации судна в указанном реестре или за последним годом, в котором было осуществлено такое подтверждение; (Дополнение подпунктом - Федеральный закон от 20.12.2005 № 168-ФЗ)\n\n52) при обращении за совершением юридически значимых действий, за исключением юридически значимых действий, указанных в подпунктах 1 - 51, 53 настоящего пункта, - до подачи заявлений и (или) документов на совершение таких действий либо в случае, если заявления на совершение таких действий поданы в электронной форме, после подачи указанных заявлений, но до принятия их к рассмотрению; (Дополнение подпунктом - Федеральный закон от 03.12.2011 № 383-ФЗ) (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n53) при обращении за совершением юридически значимого действия, указанного в подпункте 138 пункта 1 статьи 33333 настоящего Кодекса, - после подачи заявления и документов на совершение такого действия, но до выдачи федеральных специальных марок и акцизных марок; (Дополнение подпунктом - Федеральный закон от 03.08.2018 № 301-ФЗ)\n\n6) (Подпункт утратил силу  - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n7) при ежегодном подтверждении статуса международной компании - не позднее 31 марта года, следующего за годом регистрации международной компании или за последним годом, в котором было осуществлено такое подтверждение. (Дополнение подпунктом - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\n2. Государственная пошлина уплачивается плательщиком, если иное не установлено настоящей главой.\n\nВ случае, если за совершением юридически значимого действия одновременно обратились несколько плательщиков, не имеющих права на льготы, установленные настоящей главой, государственная пошлина уплачивается плательщиками в равных долях.\n\nВ случае, если среди лиц, обратившихся за совершением юридически значимого действия, одно лицо (несколько лиц) в соответствии с настоящей главой освобождено (освобождены) от уплаты государственной пошлины, размер государственной пошлины уменьшается пропорционально количеству лиц, освобожденных от ее уплаты в соответствии с настоящей главой. При этом оставшаяся часть суммы государственной пошлины уплачивается лицом (лицами), не освобожденным (не освобожденными) от уплаты государственной пошлины в соответствии с настоящей главой.\n\nОсобенности уплаты государственной пошлины в зависимости от вида совершаемых юридически значимых действий, категории плательщиков либо от иных обстоятельств устанавливаются статьями 33320, 33322, 33325, 33327, 33329, 33332 и 33334 настоящего Кодекса.\n\nГосударственная пошлина не уплачивается плательщиком в случае внесения изменений в выданный документ, направленных на исправление ошибок, допущенных по вине органа и (или) должностного лица, осуществившего выдачу документа, при совершении этим органом и (или) должностным лицом юридически значимого действия. (Дополнение абзацем - Федеральный закон от 27.12.2009 № 374-ФЗ)\n\nФакт уплаты государственной пошлины плательщиком в безналичной форме подтверждается платежным поручением с отметкой банка или соответствующего территориального органа Федерального казначейства (иного органа, осуществляющего открытие и ведение счетов), в том числе производящего расчеты в электронной форме, о его исполнении. (В редакции Федерального закона от 27.12.2009 № 374-ФЗ)\n\nФакт уплаты государственной пошлины плательщиком в наличной форме подтверждается либо квитанцией установленной формы, выдаваемой плательщику банком, либо квитанцией, выдаваемой плательщику должностным лицом или кассой органа, в который производилась оплата. (В редакции федеральных законов от 31.12.2005 № 201-ФЗ; от 24.07.2007 № 216-ФЗ)\n\nФакт уплаты государственной пошлины плательщиком подтверждается также с использованием информации об уплате государственной пошлины, содержащейся в Государственной информационной системе о государственных и муниципальных платежах, предусмотренной Федеральным законом от 27 июля 2010 года № 210-ФЗ \"Об организации предоставления государственных и муниципальных услуг\". (Дополнение абзацем - Федеральный закон от 28.07.2012 № 133-ФЗ)\n\nПри наличии информации об уплате государственной пошлины, содержащейся в Государственной информационной системе о государственных и муниципальных платежах, дополнительное подтверждение уплаты плательщиком государственной пошлины не требуется. (Дополнение абзацем - Федеральный закон от 28.07.2012 № 133-ФЗ)\n\nМеждународные компании уплачивают государственную пошлину в порядке и размерах, установленных настоящей главой для организаций. (Дополнение абзацем - Федеральный закон от 26.03.2022 № 66-ФЗ)","article_title":"Статья 333.18. Порядок и сроки уплаты государственной пошлины","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a48d8972a612b33f420ad7575f69f0702b9094f6572cad507771439166f597f4"},{"code_id":"NK_RF_2","article_number":"333.19","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 28.06.2014 № 198-ФЗ)\n\n1. По делам, рассматриваемым Верховным Судом Российской Федерации в соответствии с гражданским процессуальным законодательством Российской Федерации и законодательством об административном судопроизводстве, судами общей юрисдикции, мировыми судьями, государственная пошлина уплачивается в следующих размерах:\n\n1) при подаче искового заявления имущественного характера, административного искового заявления имущественного характера, подлежащих оценке, при цене иска:\n\nдо 100 000 рублей - 4000 рублей;\n\nот 100 001 рубля до 300 000 рублей - 4000 рублей плюс 3 процента суммы, превышающей 100 000 рублей;\n\nот 300 001 рубля до 500 000 рублей - 10 000 рублей плюс 2,5 процента суммы, превышающей 300 000 рублей;\n\nот 500 001 рубля до 1 000 000 рублей - 15 000 рублей плюс 2 процента суммы, превышающей 500 000 рублей;\n\nот 1 000 001 рубля до 3 000 000 рублей - 25 000 рублей плюс 1 процент суммы, превышающей 1 000 000 рублей;\n\nот 3 000 001 рубля до 8 000 000 рублей - 45 000 рублей плюс 0,7 процента суммы, превышающей 3 000 000 рублей;\n\nот 8 000 001 рубля до 24 000 000 рублей - 80 000 рублей плюс 0,35 процента суммы, превышающей 8 000 000 рублей;\n\n00 рублей - 136 000 рублей плюс 0,3 процента суммы, превышающей 24 000 000 рублей;\n\nот 50 000 001 рубля до 100 000 000 рублей - 214 000 рублей плюс 0,2 процента суммы, превышающей 50 000 000 рублей;\n\nсвыше 100 000 000 рублей - 314 000 рублей плюс 0,15 процента суммы, превышающей 100 000 000 рублей, но не более 900 000 рублей;\n\n2) при подаче заявления о вынесении судебного приказа - 50 процентов размера государственной пошлины, взимаемой при подаче искового заявления имущественного характера;\n\n3) при подаче искового заявления имущественного характера, не подлежащего оценке, искового заявления неимущественного характера:\n\nдля физических лиц - 3000 рублей;\n\nдля организаций - 20 000 рублей;\n\n4) при подаче искового заявления по спорам, возникающим при заключении, изменении или расторжении договоров, не содержащего требования о возврате исполненного по сделке или о присуждении имущества, а также искового заявления по спорам о признании сделок недействительными, не содержащего требования о применении последствий недействительности сделок:\n\nдля физических лиц - 3000 рублей;\n\nдля организаций - 20 000 рублей;\n\n5) при подаче искового заявления о расторжении брака - 5000 рублей;\n\n6) при подаче административного искового заявления об оспаривании (полностью или частично) нормативных правовых актов (нормативных актов) государственных органов, Центрального банка Российской Федерации, государственных внебюджетных фондов, органов местного самоуправления, органов публичной власти федеральной территории \"Сириус\", государственных корпораций, должностных лиц, при подаче административного искового заявления об оспаривании ненормативных правовых актов Президента Российской Федерации, Совета Федерации Федерального Собрания Российской Федерации, Государственной Думы Федерального Собрания Российской Федерации, Правительства Российской Федерации, Правительственной комиссии по контролю за осуществлением иностранных инвестиций в Российской Федерации, а также при подаче административного искового заявления об оспаривании актов федеральных органов исполнительной власти, иных федеральных государственных органов, Центрального банка Российской Федерации, государственных внебюджетных фондов, содержащих разъяснения законодательства и обладающих нормативными свойствами:\n\nдля физических лиц - 4000 рублей;\n\nдля организаций - 20 000 рублей;\n\n7) при подаче административного искового заявления о признании ненормативного правового акта недействительным и о признании решений и действий (бездействия) государственных органов, органов местного самоуправления, иных органов, должностных лиц незаконными:\n\nдля физических лиц - 3000 рублей;\n\nдля организаций - 15 000 рублей;\n\n8) при подаче заявления по делам особого производства - 3000 рублей;\n\n9) при подаче заявления о правопреемстве, кроме случаев универсального правопреемства:\n\nдля физических лиц - 2000 рублей;\n\nдля организаций - 15 000 рублей;\n\n10) при подаче заявления о выдаче исполнительных листов на принудительное исполнение решений третейского суда, заявлений о признании и об исполнении решения иностранного суда, иностранных третейских судов (арбитражей) - в размере 30 процентов государственной пошлины, исчисленной по правилам подпункта 1 настоящего пункта, исходя из суммы, подтвержденной соответствующим решением;\n\n11) при подаче заявления об отмене решения третейского суда - в размере государственной пошлины, исчисленной по правилам подпункта 1 настоящего пункта, исходя из оспариваемой заявителем суммы;\n\n12) при подаче заявления о выдаче дубликата исполнительного листа, о пересмотре заочного решения судом, вынесшим это решение, - 1500 рублей;\n\n13) при подаче заявления о восстановлении пропущенного срока для предъявления исполнительного листа к исполнению, об отсрочке или рассрочке исполнения судебного постановления, изменении способа и порядка его исполнения, о повороте исполнения судебного постановления, о разъяснении судебного постановления - 3000 рублей;\n\n14) при подаче заявления о пересмотре судебных постановлений по новым или вновь открывшимся обстоятельствам - 10 000 рублей;\n\n15) при подаче заявления об обеспечении иска, в том числе иска, рассматриваемого в третейском суде, о замене обеспечительной меры, об отмене обеспечения (за исключением заявлений о принятии предварительных обеспечительных мер защиты авторских и (или) смежных прав в информационно-телекоммуникационных сетях, в том числе в сети \"Интернет\") - 10 000 рублей;\n\n16) при подаче заявления по делам о взыскании алиментов - 150 рублей. Если судом выносится решение о взыскании алиментов как на содержание детей, так и на содержание истца, размер государственной пошлины увеличивается в два раза;\n\n17) при подаче административного искового заявления о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок:\n\nдля физических лиц - 300 рублей;\n\nдля организаций - 6000 рублей;\n\n18) при подаче административного искового заявления о присуждении компенсации за нарушение условий содержания под стражей, содержания в исправительном учреждении - 300 рублей;\n\n19) при подаче апелляционной жалобы, частной жалобы, а также при подаче кассационной жалобы на судебный приказ:\n\nдля физических лиц - 3000 рублей;\n\nдля организаций - 15 000 рублей;\n\n20) при подаче кассационной жалобы:\n\nдля физических лиц - 5000 рублей;\n\nдля организаций - 20 000 рублей;\n\n21) при подаче кассационной или надзорной жалобы в Верховный Суд Российской Федерации, а также жалобы на определение судьи Верховного Суда Российской Федерации об отказе в передаче кассационной или надзорной жалобы для рассмотрения в судебном заседании:\n\nдля физических лиц - 7000 рублей;\n\nдля организаций - 25 000 рублей.\n\n(Пункт в редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n2. Положения настоящей статьи применяются с учетом положений статьи 33320 настоящего Кодекса.","article_title":"Статья 333.19. Размеры государственной пошлины по делам, рассматриваемым Верховным Судом Российской Федерации, судами общей юрисдикции, мировыми судьями","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"37a256780fa9cb31141a4c782e44190ccc56bae016a33db345c74eae4b0b6874"},{"code_id":"NK_RF_2","article_number":"333.2","version_date":"2000-07-31","article_text":"1. Объектами обложения признаются:\n\nобъекты животного мира в соответствии с перечнем, установленным пунктом 1 статьи 3333 настоящего Кодекса, изъятие которых из среды их обитания осуществляется на основании разрешения на добычу объектов животного мира, выдаваемого в соответствии с законодательством Российской Федерации; (В редакции Федерального закона от 24.07.2009 № 209-ФЗ)\n\nобъекты водных биологических ресурсов в соответствии с перечнем, установленным пунктами 4 и 5 статьи 3333 настоящего Кодекса, изъятие которых из среды их обитания осуществляется на основании разрешения на добычу (вылов) водных биологических ресурсов, выдаваемого в соответствии с законодательством Российской Федерации, в том числе объекты водных биологических ресурсов, подлежащие изъятию из среды их обитания в качестве разрешенного прилова. (В редакции федеральных законов от 29.11.2007 № 285-ФЗ; от 30.12.2008 № 314-ФЗ)","article_title":"Статья 333.2. Объекты обложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"845994daed7d2909d915cc7dceeeb23835aab204343bd38d6e781c34283bb9f2"},{"code_id":"NK_RF_2","article_number":"333.20","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 28.06.2014 № 198-ФЗ)\n\n1) при подаче исковых заявлений, а также административных исковых заявлений, содержащих требования как имущественного, так и неимущественного характера, одновременно уплачиваются государственная пошлина, установленная для исковых заявлений имущественного характера, и государственная пошлина, установленная для исковых заявлений неимущественного характера; (В редакции Федерального закона от 08.03.2015 № 23-ФЗ)\n\n2) цена иска (административного иска), по которой исчисляется государственная пошлина, определяется истцом (административным истцом), а в случаях, установленных законодательством, судьей по правилам, установленным гражданским процессуальным законодательством Российской Федерации, законодательством об административном судопроизводстве; (В редакции Федерального закона от 08.03.2015 № 23-ФЗ)\n\n3) при подаче исковых заявлений о разделе имущества, находящегося в общей собственности, а также при подаче исковых заявлений о выделе доли из указанного имущества, о признании права на долю в имуществе размер государственной пошлины исчисляется в следующем порядке:\n\nесли спор о признании права собственности истца (истцов) на это имущество ранее не решался судом - в соответствии с подпунктом 1 пункта 1 статьи 33319 настоящего Кодекса;\n\nесли ранее суд вынес решение о признании права собственности истца (истцов) на указанное имущество - в соответствии с подпунктом 3 пункта 1 статьи 33319 настоящего Кодекса;\n\n4) при предъявлении встречного иска, встречного административного иска, а также заявлений о вступлении в дело третьих лиц, заявляющих самостоятельные требования относительно предмета спора, государственная пошлина уплачивается в соответствии с положениями статьи 33319 настоящего Кодекса; (В редакции Федерального закона от 08.03.2015 № 23-ФЗ)\n\n5) при замене по определению суда выбывшей стороны ее правопреемником (в случае смерти физического лица, реорганизации организации, уступки требования, перевода долга и в других случаях перемены лиц в обязательствах) государственная пошлина уплачивается таким правопреемником, если она не была уплачена замененной стороной;\n\n6) в случае выделения судьей одного искового требования (административного искового требования) или нескольких из соединенных исковых требований (административных исковых требований) в отдельное производство государственная пошлина, уплаченная при предъявлении иска (административного иска), не пересчитывается и не возвращается. По делам, выделенным в отдельное производство, государственная пошлина повторно не уплачивается; (В редакции Федерального закона от 08.03.2015 № 23-ФЗ)\n\n7) при подаче кассационной жалобы соучастниками и третьими лицами, выступающими в процессе на той же стороне, что и лицо, подавшее кассационную жалобу, заинтересованными лицами по делам, рассматриваемым в порядке административного судопроизводства, государственная пошлина не уплачивается; (В редакции Федерального закона от 08.03.2015 № 23-ФЗ)\n\n8) в случае, если истец, административный истец освобожден от уплаты государственной пошлины в соответствии с настоящей главой, государственная пошлина уплачивается ответчиком, административным ответчиком (если он не освобожден от уплаты государственной пошлины) пропорционально размеру удовлетворенных судом исковых требований, административных исковых требований, а в случаях, предусмотренных законодательством об административном судопроизводстве, в полном объеме; (В редакции Федерального закона от 08.03.2015 № 23-ФЗ)\n\n9) при затруднительности определения цены иска в момент его предъявления размер государственной пошлины предварительно устанавливается судьей с последующей доплатой недостающей суммы государственной пошлины на основании цены иска, определенной судом при разрешении дела, в срок, установленный подпунктом 2 пункта 1 статьи 33318 настоящего Кодекса;\n\n10) при увеличении истцом размера исковых требований недостающая сумма государственной пошлины доплачивается в соответствии с увеличенной ценой иска в срок, установленный подпунктом 2 пункта 1 статьи 33318 настоящего Кодекса. При уменьшении истцом размера исковых требований сумма излишне уплаченной государственной пошлины возвращается в порядке, предусмотренном статьей 33340 настоящего Кодекса. В аналогичном порядке определяется размер государственной пошлины, если суд в зависимости от обстоятельств дела выйдет за пределы заявленных истцом требований;\n\n11) при подаче исковых заявлений об истребовании наследниками принадлежащей им доли имущества государственная пошлина уплачивается в том порядке, который установлен при подаче исковых заявлений имущественного характера, не подлежащих оценке, если спор о признании права собственности на это имущество судом ранее был разрешен;\n\n12) при подаче исковых заявлений о расторжении брака с одновременным разделом совместно нажитого имущества супругов государственная пошлина уплачивается в размерах, установленных как для исковых заявлений о расторжении брака, так и для исковых заявлений имущественного характера;\n\n13) при отказе в принятии к рассмотрению искового заявления, административного искового заявления или заявления о вынесении судебного приказа либо при отмене судебного приказа уплаченная государственная пошлина при предъявлении иска, административного иска или заявления о вынесении судебного приказа засчитывается в счет подлежащей уплате государственной пошлины; (В редакции Федерального закона от 02.03.2016 № 48-ФЗ)\n\n14) (Подпункт утратил силу - Федеральный закон от 27.12.2009 № 374-ФЗ)\n\n15) при подаче исковых заявлений, содержащих требования о применении последствий недействительности сделок, уплачивается государственная пошлина, установленная для исковых заявлений имущественного характера, в зависимости от стоимости имущества, подлежащего возврату; (Дополнение подпунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n16) при подаче исковых заявлений, содержащих требования об обращении взыскания на заложенное имущество, уплачивается государственная пошлина, установленная для исковых заявлений имущественного характера, в зависимости от стоимости имущества, на которое обращается взыскание. Если одновременно с требованием об обращении взыскания на заложенное имущество предъявлено денежное требование по солидарному обязательству, по которому уплачена государственная пошлина, установленная для исковых заявлений имущественного характера, в отношении такого требования об обращении взыскания на заложенное имущество уплачивается государственная пошлина, установленная для исковых заявлений неимущественного характера. (Дополнение подпунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)","article_title":"Статья 333.20. Особенности уплаты государственной пошлины при обращении в Верховный Суд Российской Федерации, суды общей юрисдикции, к мировым судьям","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"58b5f1e10c846ef97fd527b80921dd22adadf86a2335ba917b64409859a679d4"},{"code_id":"NK_RF_2","article_number":"333.21","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 28.06.2014 № 198-ФЗ)\n\n1. По делам, рассматриваемым Верховным Судом Российской Федерации в соответствии с арбитражным процессуальным законодательством Российской Федерации, арбитражными судами, государственная пошлина уплачивается в следующих размерах:\n\n1) при подаче искового заявления имущественного характера, подлежащего оценке, при цене иска:\n\nдо 100 000 рублей - 10 000 рублей;\n\nот 100 001 рубля до 1 000 000 рублей - 10 000 рублей плюс 5 процентов суммы, превышающей 100 000 рублей;\n\nот 1 000 001 рубля до 10 000 000 рублей - 55 000 рублей плюс 3 процента суммы, превышающей 1 000 000 рублей;\n\nот 10 000 001 рубля до 50 000 000 рублей - 325 000 рублей плюс 1 процент суммы, превышающей 10 000 000 рублей;\n\nсвыше 50 000 000 рублей - 725 000 рублей плюс 0,5 процента суммы, превышающей 50 000 000 рублей, но не более 10 000 000 рублей;\n\n2) при подаче искового заявления по спорам, возникающим при заключении, изменении или расторжении договоров, не содержащего требования о возврате исполненного по сделке или о присуждении имущества, а также искового заявления по спорам о признании сделок недействительными, не содержащего требования о применении последствий недействительности сделок:\n\nдля физических лиц - 15 000 рублей;\n\nдля организаций - 50 000 рублей;\n\n3) при подаче заявления о вынесении судебного приказа - 50 процентов размера государственной пошлины, взимаемой при подаче искового заявления имущественного характера, но не менее 8000 рублей;\n\n4) при подаче искового заявления имущественного характера, не подлежащего оценке, искового заявления неимущественного характера:\n\nдля физических лиц - 15 000 рублей;\n\nдля организаций - 50 000 рублей;\n\n5) при подаче заявления об оспаривании нормативных правовых актов федеральных органов исполнительной власти, затрагивающих права и законные интересы заявителя в области правовой охраны результатов интеллектуальной деятельности и средств индивидуализации, в том числе в сфере патентных прав и прав на селекционные достижения, права на топологии интегральных микросхем, права на секреты производства (ноу-хау), права на средства индивидуализации юридических лиц, товаров, работ, услуг и предприятий, права использования результатов интеллектуальной деятельности в составе единой технологии:\n\nдля физических лиц - 10 000 рублей;\n\nдля организаций - 60 000 рублей;\n\n6) при подаче заявления об оспаривании актов федеральных органов исполнительной власти в сфере патентных прав и прав на селекционные достижения, права на топологии интегральных микросхем, права на секреты производства (ноу-хау), права на средства индивидуализации юридических лиц, товаров, работ, услуг и предприятий, права использования результатов интеллектуальной деятельности в составе единой технологии, содержащих разъяснения законодательства и обладающих нормативными свойствами:\n\nдля физических лиц - 10 000 рублей;\n\nдля организаций - 60 000 рублей;\n\n7) при подаче заявлений о признании ненормативного правового акта недействительным и о признании решений и действий (бездействия) государственных органов, органов местного самоуправления, иных органов, должностных лиц незаконными:\n\nдля физических лиц - 10 000 рублей;\n\nдля организаций - 50 000 рублей;\n\n8) при обращении с заявлением о признании должника несостоятельным (банкротом):\n\nдля физических лиц - 10 000 рублей;\n\nдля организаций - 100 000 рублей.\n\nПри обращении должника с заявлением о признании его несостоятельным (банкротом) государственная пошлина не взимается;\n\n9) по заявлениям, требованиям и иным обособленным спорам, подлежащим рассмотрению в деле о банкротстве, - в размере 50 процентов государственной пошлины, определяемой в соответствии с настоящим пунктом, исходя из существа заявленных требований;\n\n10) при подаче заявления об установлении фактов, имеющих юридическое значение, - 30 000 рублей;\n\n11) при подаче заявления о вступлении в дело третьих лиц, заявляющих самостоятельные требования относительно предмета спора:\n\nпо спорам имущественного характера - в размере государственной пошлины, уплачиваемой исходя из оспариваемой третьим лицом суммы;\n\nпо спорам имущественного характера, если иск не подлежит оценке, а также по спорам неимущественного характера - в размере государственной пошлины, уплачиваемой при подаче искового заявления неимущественного характера;\n\n12) при подаче заявления о правопреемстве, кроме случаев универсального правопреемства:\n\nдля физических лиц - 5000 рублей;\n\nдля организаций - 25 000 рублей;\n\n13) при подаче заявления о выдаче исполнительных листов на принудительное исполнение решений третейского суда, заявлений о признании и приведении в исполнение решения иностранного суда, иностранного арбитражного решения - в размере 30 процентов государственной пошлины, исчисленной по правилам подпункта 1 настоящего пункта, исходя из суммы, подтвержденной соответствующим решением;\n\n14) при подаче заявления об отмене решения третейского суда - в размере государственной пошлины, исчисленной по правилам подпункта 1 настоящего пункта, исходя из оспариваемой заявителем суммы;\n\n15) при подаче заявления о выдаче дубликата исполнительного листа, о восстановлении пропущенного срока для предъявления исполнительного листа к исполнению, об отсрочке или рассрочке исполнения судебного акта, изменении способа и порядка его исполнения, о повороте исполнения судебного акта, о разъяснении судебного акта - 10 000 рублей;\n\n16) при подаче заявления о пересмотре судебного акта по новым или вновь открывшимся обстоятельствам - 30 000 рублей;\n\n17) при подаче заявления об обеспечении иска, в том числе иска, рассматриваемого в третейском суде, о замене обеспечительной меры, об отмене обеспечения - 30 000 рублей;\n\n18) при подаче заявления о присуждении к\n\nомпенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок:\n\nдля физических лиц - 300 рублей;\n\nдля организаций - 6000 рублей;\n\n19) при подаче апелляционной жалобы, а также при подаче кассационной жалобы на судебный приказ:\n\nдля физических лиц - 10 000 рублей;\n\nдля организаций - 30 000 рублей;\n\n20) при подаче кассационной жалобы:\n\nдля физических лиц - 20 000 рублей;\n\nдля организаций - 50 000 рублей;\n\n21) при подаче кассационной или надзорной жалобы в Верховный Суд Российской Федерации, а также жалобы на определение судьи Верховного Суда Российской Федерации об отказе в передаче кассационной или надзорной жалобы для рассмотрения в судебном заседании:\n\nдля физических лиц - 30 000 рублей;\n\nдля организаций - 80 000 рублей.\n\n(Пункт в редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n2. Положения настоящей статьи применяются с учетом положений статьи 33322 настоящего Кодекса.","article_title":"Статья 333.21. Размеры государственной пошлины по делам, рассматриваемым Верховным Судом Российской Федерации, арбитражными судами","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2566f6d87154f23baf72fbd2ad345eee56df28fd557e9a190c44ee5e5c440015"},{"code_id":"NK_RF_2","article_number":"333.22","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 28.06.2014 № 198-ФЗ)\n\n1) при подаче исковых заявлений, содержащих одновременно требования как имущественного, так и неимущественного характера, одновременно уплачиваются государственная пошлина, установленная для исковых заявлений имущественного характера, и государственная пошлина, установленная для исковых заявлений неимущественного характера;\n\n2) цена иска определяется истцом, а в случае неправильного указания цены иска - арбитражным судом. В цену иска включаются указанные в исковом заявлении суммы неустойки (штрафов, пеней) и проценты;\n\n3) при увеличении истцом размера исковых требований недостающая сумма государственной пошлины доплачивается в соответствии с увеличенной ценой иска в срок, установленный подпунктом 2 пункта 1 статьи 33318 настоящего Кодекса. При уменьшении истцом размера исковых требований сумма излишне уплаченной государственной пошлины возвращается в порядке, предусмотренном статьей 33340 настоящего Кодекса. В аналогичном порядке определяется размер государственной пошлины, если суд в зависимости от обстоятельств дела выйдет за пределы заявленных истцом требований. Цена иска, состоящего из нескольких самостоятельных требований, определяется исходя из суммы всех требований;\n\n4) в случае, если истец освобожден от уплаты государственной пошлины в соответствии с настоящей главой, государственная пошлина уплачивается ответчиком (если он не освобожден от уплаты государственной пошлины) пропорционально размеру удовлетворенных арбитражным судом исковых требований;\n\n5) при подаче заявлений о возврате (возмещении) из бюджета денежных средств государственная пошлина уплачивается исходя из оспариваемой денежной суммы в размерах, установленных подпунктом 1 пункта 1 статьи 33321 настоящего Кодекса;\n\n6) (Подпункт утратил силу - Федеральный закон от 03.04.2017 № 57-ФЗ)\n\n7) при отказе в принятии искового заявления (заявления) или заявления о выдаче судебного приказа либо при отмене судебного приказа уплаченная государственная пошлина при предъявлении искового заявления (заявления) или заявления о выдаче судебного приказа засчитывается в счет подлежащей уплате государственной пошлины; (Дополнение подпунктом - Федеральный закон от 02.03.2016 № 48-ФЗ) (В редакции Федерального закона от 03.04.2017 № 57-ФЗ)\n\n8) при подаче исковых заявлений, содержащих требования о применении последствий недействительности сделок, уплачивается государственная пошлина, установленная для исковых заявлений имущественного характера, в зависимости от стоимости имущества, подлежащего возврату; (Дополнение подпунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n9) при подаче исковых заявлений, содержащих требования об обращении взыскания на заложенное имущество, уплачивается государственная пошлина, установленная для исковых заявлений имущественного характера, в зависимости от стоимости имущества, на которое обращается взыскание. Если одновременно с требованием об обращении взыскания на заложенное имущество предъявлено денежное требование по солидарному обязательству, по которому уплачена государственная пошлина, установленная для исковых заявлений имущественного характера, в отношении такого требования об обращении взыскания на заложенное имущество уплачивается государственная пошлина, установленная для исковых заявлений неимущественного характера. (Дополнение подпунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)","article_title":"Статья 333.22. Особенности уплаты государственной пошлины при обращении в Верховный Суд Российской Федерации, арбитражные суды","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3dd0801f7702ceae602071686ba1cfddb599fa2bdbe5e3402aac1893de4accb0"},{"code_id":"NK_RF_2","article_number":"333.23","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 14.07.2022 № 306-ФЗ)\n\n1. По делам, рассматриваемым Конституционным Судом Российской Федерации, государственная пошлина уплачивается в следующих размерах:\n\n1) при направлении запроса или ходатайства - 6 750 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n2) при направлении жалобы организацией - 6 750 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n3) при направлении жалобы физическим лицом - 450 рублей. (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)","article_title":"Статья 333.23. Размеры государственной пошлины по делам, рассматриваемым Конституционным Судом Российской Федерации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"51cb9120574474c504d5f813ab1656037572a2a43255ae0a884ed9e9c2f8c665"},{"code_id":"NK_RF_2","article_number":"333.24","version_date":"2000-07-31","article_text":"1. За совершение нотариальных действий нотариусами государственных нотариальных контор и (или) должностными лицами органов исполнительной власти, органов местного самоуправления, уполномоченными в соответствии с законодательными актами Российской Федерации и (или) законодательными актами субъектов Российской Федерации на совершение нотариальных действий, государственная пошлина уплачивается в следующих размерах:\n\n1) за удостоверение доверенностей на совершение сделок (сделки), требующих (требующей) нотариальной формы в соответствии с законодательством Российской Федерации, - 200 рублей;\n\n2) за удостоверение прочих доверенностей, требующих нотариальной формы в соответствии с законодательством Российской Федерации, - 200 рублей;\n\n3) за удостоверение доверенностей, выдаваемых в порядке передоверия, в случаях, если такое удостоверение обязательно в соответствии с законодательством Российской Федерации, - 200 рублей;\n\n4) за удостоверение договоров об ипотеке, если данное требование установлено законодательством Российской Федерации:\n\nза удостоверение договоров об ипотеке жилого помещения в обеспечение возврата кредита (займа), предоставленного на приобретение или строительство жилого дома, квартиры, - 200 рублей;\n\nза удостоверение договоров об ипотеке другого недвижимого имущества, за исключением морских и воздушных судов, а также судов внутреннего плавания, - 0,3 процента суммы договора, но не более 3 000 рублей;\n\nза удостоверение договоров об ипотеке морских и воздушных судов, а также судов внутреннего плавания - 0,3 процента суммы договора, но не более 30 000 рублей;\n\n41) за удостоверение договоров купли-продажи и залога доли или части доли в уставном капитале общества с ограниченной ответственностью в зависимости от суммы договора:\n\nдо 1 000 000 рублей - 0,5 процента суммы договора, но не менее 1 500 рублей;\n\nот 1 000 001 рубля до 10 000 000 рублей включительно - 5 000 рублей плюс 0,3 процента суммы договора, превышающей 1 000 000 рублей;\n\nсвыше 10 000 001 рубля - 32 000 рублей плюс 0,15 процента суммы договора, превышающей 10 000 000 рублей, но не более 150 000 рублей;\n\n(Дополнение подпунктом - Федеральный закон от 06.12.2011 № 405-ФЗ)\n\n5) за удостоверение прочих договоров, предмет которых подлежит оценке, если такое удостоверение обязательно в соответствии с законодательством Российской Федерации, - 0,5 процента суммы договора, но не менее 300 рублей и не более 20 000 рублей;\n\n6) за удостоверение сделок, предмет которых не подлежит оценке и которые в соответствии с законодательством Российской Федерации должны быть нотариально удостоверены, - 500 рублей;\n\n7) за удостоверение договоров уступки требования по договору об ипотеке жилого помещения, а также по кредитному договору и договору займа, обеспеченному ипотекой жилого помещения, - 300 рублей;\n\n8) за удостоверение учредительных документов (копий учредительных документов) организаций - 500 рублей;\n\n9) за удостоверение соглашения об уплате алиментов - 250 рублей;\n\n10) за удостоверение брачного договора - 500 рублей;\n\n11) за удостоверение договоров поручительства - 0,5 процента суммы, на которую принимается обязательство, но не менее 200 рублей и не более 20 000 рублей;\n\n12) за удостоверение соглашения об изменении или о расторжении нотариально удостоверенного договора - 200 рублей;\n\n13) за удостоверение завещаний, за принятие закрытого завещания - 100 рублей;\n\n14) за вскрытие конверта с закрытым завещанием и оглашение закрытого завещания - 300 рублей;\n\n15) за удостоверение доверенностей на право пользования и (или) распоряжения имуществом, за исключением имущества, предусмотренного подпунктом 16 настоящего пункта:\n\nдетям, в том числе усыновленным, супругу, родителям, полнородным братьям и сестрам - 100 рублей;\n\nдругим физическим лицам - 500 рублей;\n\n16) за удостоверение доверенностей на право пользования и (или) распоряжения автотранспортными средствами:\n\nдетям, в том числе усыновленным, супругу, родителям, полнородным братьям и сестрам - 250 рублей;\n\nдругим физическим лицам - 400 рублей;\n\n17) за совершение морского протеста - 30 000 рублей;\n\n18) за свидетельствование верности перевода документа с одного языка на другой - 100 рублей за одну страницу перевода документа;\n\n19) за совершение исполнительной надписи - 0,5 процента взыскиваемой суммы, но не более 20 000 рублей;\n\n20) за принятие на депозит денежных сумм или ценных бумаг, если такое принятие на депозит обязательно в соответствии с законодательством Российской Федерации, - 0,5 процента принятой денежной суммы или рыночной стоимости ценных бумаг, но не менее 20 рублей и не более 20 000 рублей;\n\n21) за свидетельствование подлинности подписи, если такое свидетельствование обязательно в соответствии с законодательством Российской Федерации:\n\nна документах и заявлениях, за исключением банковских карточек и заявлений о регистрации юридических лиц, - 100 рублей;\n\nна банковских карточках и на заявлениях о регистрации юридических лиц (с каждого лица, на каждом документе) - 200 рублей;\n\n22) за выдачу свидетельства о праве на наследство по закону и по завещанию:\n\nдетям, в том числе усыновленным, супругу, родителям, полнородным братьям и сестрам наследодателя - 0,3 процента стоимости наследуемого имущества, но не более 100 000 рублей;\n\nдругим наследникам - 0,6 процента стоимости наследуемого имущества, но не более 1 000 000 рублей;\n\n23) за принятие мер по охране наследства - 600 рублей;\n\n24) за совершение протеста векселя в неплатеже, неакцепте и недатировании акцепта и за удостоверение неоплаты чека - 1 процент неоплаченной суммы, но не более 20 000 рублей;\n\n25) за выдачу дубликатов документов, хранящихся в делах государственных нотариальных контор, органов исполнительной власти, - 100 рублей;\n\n26) за совершение прочих нотариальных действий, для которых законодательством Российской Федерации предусмотрена обязательная нотариальная форма, - 100 рублей.\n\n2. Положения настоящей статьи применяются с учетом положений статьи 33325 настоящего Кодекса.","article_title":"Статья 333.24. Размеры государственной пошлины за совершение нотариальных действий","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3aa9da2e91b28cf871eb7b387e85c571f6c979f1d8115a31874b23a7c129d013"},{"code_id":"NK_RF_2","article_number":"333.25","version_date":"2000-07-31","article_text":"1. За совершение нотариальных действий государственная пошлина уплачивается с учетом следующих особенностей:\n\n1) за нотариальные действия, совершаемые вне помещений государственной нотариальной конторы, органов исполнительной власти и органов местного самоуправления, государственная пошлина уплачивается в размере, увеличенном в полтора раза;\n\n2) при удостоверении доверенности, выданной в отношении нескольких лиц, государственная пошлина уплачивается однократно;\n\n3) при наличии нескольких наследников (в частности, наследников по закону, по завещанию или наследников, имеющих право на обязательную долю в наследстве) государственная пошлина уплачивается каждым наследником;\n\n4) за выдачу свидетельства о праве на наследство, выдаваемого на основании решений суда о признании ранее выданного свидетельства о праве на наследство недействительным, государственная пошлина уплачивается в соответствии с порядком и в размерах, которые установлены настоящей главой. При этом сумма государственной пошлины, уплаченной за ранее выданное свидетельство, подлежит возврату в порядке, установленном статьей 33340 настоящего Кодекса. По заявлению плательщика государственная пошлина, уплаченная за ранее выданное свидетельство, подлежит зачету в счет государственной пошлины, подлежащей уплате за выдачу нового свидетельства, в течение одного года со дня вступления в законную силу соответствующего решения суда. В таком же порядке решается вопрос при повторном удостоверении договоров, признанных судом недействительными;\n\n5) при исчислении размера государственной пошлины за удостоверение договоров, подлежащих оценке, принимается сумма договора, указанная сторонами, но не ниже суммы, определенной в соответствии с подпунктами 7 - 10 настоящего пункта. При исчислении размера государственной пошлины за выдачу свидетельств о праве на наследство принимается стоимость наследуемого имущества, определенная в соответствии с подпунктами 7 - 10 настоящего пункта. При исчислении размера государственной пошлины за удостоверение сделок, направленных на отчуждение доли или части доли в уставном капитале общества с ограниченной ответственностью, а также сделок, устанавливающих обязательство по отчуждению доли или части доли в уставном капитале общества с ограниченной ответственностью, принимается сумма договора, указанная сторонами, но не ниже номинальной стоимости доли или части доли. При исчислении размера государственной пошлины за удостоверение договоров купли-продажи и залога доли или части доли в уставном капитале общества с ограниченной ответственностью принимается оценка доли или части доли как предмета залога, указанная сторонами договора залога, но не ниже номинальной стоимости доли, части доли соответственно. (В редакции федеральных законов от 19.07.2009 № 205-ФЗ; от 06.12.2011 № 405-ФЗ)\n\nПо выбору плательщика для исчисления государственной пошлины может быть представлен документ с указанием рыночной, кадастровой либо иной (номинальной) стоимости имущества, выданный лицами, указанными в подпунктах 7 - 10 настоящего пункта. Нотариусы и должностные лица, совершающие нотариальные действия, не вправе определять вид стоимости имущества (способ оценки) в целях исчисления государственной пошлины и требовать от плательщика представления документа, подтверждающего данный вид стоимости имущества (способ оценки). (В редакции федеральных законов от 29.11.2012 № 205-ФЗ, от 29.09.2019 № 325-ФЗ)\n\nВ случае представления нескольких документов, выданных лицами, указанными в подпунктах 7 - 10 настоящего пункта, с указанием различной стоимости имущества при исчислении размера государственной пошлины принимается наименьшая из указанных стоимостей имущества; (В редакции Федерального закона от 29.11.2012 № 205-ФЗ)\n\n(Подпункт в редакции Федерального закона от 31.12.2005 № 201-ФЗ)\n\n6) оценка стоимости наследственного имущества производится исходя из стоимости наследуемого имущества (курса Центрального банка Российской Федерации - в отношении иностранной валюты и ценных бумаг в иностранной валюте) на день открытия наследства;\n\n7) стоимость транспортных средств может определяться оценщиками, юридическими лицами, которые вправе заключить договор на проведение оценки согласно законодательству Российской Федерации об оценочной деятельности, или судебно-экспертными учреждениями органа юстиции; (В редакции Федерального закона от 29.11.2012 № 205-ФЗ)\n\n8) стоимость недвижимого имущества, за исключением земельных участков, может определяться оценщиками, юридическими лицами, которые вправе заключить договор на проведение оценки согласно законодательству Российской Федерации об оценочной деятельности, или организациями (органами) по учету объектов недвижимого имущества по месту его нахождения; (В редакции Федерального закона от 29.11.2012 № 205-ФЗ)\n\n9) стоимость земельных участков может определяться оценщиками, юридическими лицами, которые вправе заключить договор на проведение оценки согласно законодательству Российской Федерации об оценочной деятельности, или органами, осуществляющими государственный кадастровый учет и государственную регистрацию прав на недвижимое имущество; (В редакции федеральных законов от 29.11.2012 № 205-ФЗ; от 30.11.2016 № 401-ФЗ)\n\n10) стоимость имущества, не предусмотренного подпунктами 7 - 9 настоящего пункта, определяется оценщиками или юридическими лицами, которые вправе заключить договор на проведение оценки согласно законодательству Российской Федерации об оценочной деятельности; (В редакции Федерального закона от 29.11.2012 № 205-ФЗ)\n\n11) оценка стоимости патента, переходящего по наследству, производится исходя из всех сумм уплаченной на день смерти наследодателя государственной пошлины за патентование изобретения, промышленного образца или полезной модели. В таком же порядке определяется стоимость переходящих по наследству прав на получение патента;\n\n12) оценка переходящих по наследству имущественных прав производится из стоимости имущества (курса Центрального банка Российской Федерации - в отношении иностранной валюты и ценных бумаг в иностранной валюте), на которое переходят имущественные права, на день открытия наследства;\n\n13) оценка наследственного имущества, находящегося за пределами территории Российской Федерации, или переходящих на него по наследству имущественных прав определяется исходя из суммы, указанной в оценочном документе, составленном за границей должностными лицами компетентных органов и применяемом на территории Российской Федерации в соответствии с законодательством Российской Федерации.\n\n2. Положения настоящей статьи применяются с учетом положений статей 33335 и 33338 настоящего Кодекса.","article_title":"Статья 333.25. Особенности уплаты государственной пошлины при обращении за совершением нотариальных действий","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"648d87d84bfc84b9a55c00aacfd3508071488b360a80b14319f4b9c96d86666f"},{"code_id":"NK_RF_2","article_number":"333.26","version_date":"2000-07-31","article_text":"ского состояния и иными уполномоченными органами\n\n1. За государственную регистрацию актов гражданского состояния и другие юридически значимые действия, совершаемые органами записи актов гражданского состояния и иными уполномоченными органами, государственная пошлина уплачивается в следующих размерах:\n\n1) за государственную регистрацию заключения брака, включая выдачу свидетельства, - 350 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n2) за государственную регистрацию расторжения брака, включая выдачу свидетельств:\n\nпри взаимном согласии супругов, не имеющих общих несовершеннолетних детей, - 5000 рублей с каждого из супругов; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nпри расторжении брака в судебном порядке - 5000 рублей с каждого из супругов; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nпри расторжении брака по заявлению одного из супругов в случае, если другой супруг признан судом безвестно отсутствующим, недееспособным или осужденным за совершение преступления к лишению свободы на срок свыше трех лет, - 350 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n3) за государственную регистрацию установления отцовства, включая выдачу свидетельства об установлении отцовства, - 350 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n4) за государственную регистрацию перемены имени, включающего в себя фамилию, собственно имя и (или) отчество, включая выдачу свидетельства о перемене имени, - 5000 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 12.07.2024 № 176-ФЗ)\n\n5) за внесение исправлений и изменений в записи актов гражданского состояния, включая выдачу свидетельств, - 700 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 12.07.2024 № 176-ФЗ)\n\n6) за выдачу повторного свидетельства о государственной регистрации акта гражданского состояния - 500 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 12.07.2024 № 176-ФЗ)\n\n7) за выдачу физическим лицам справок из архивов органов записи актов гражданского состояния и иных уполномоченных органов - 350 рублей. (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 12.07.2024 № 176-ФЗ)\n\n(Пункт в редакции Федерального закона от 27.12.2009 № 374-ФЗ)\n\n2. Положения настоящей статьи применяются с учетом положений статьи 33327 настоящего Кодекса.","article_title":"Статья 333.26. Размеры государственной пошлины за государственную регистрацию актов гражданского состояния и другие юридически значимые действия, совершаемые органами записи актов граждан","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"aa60358b736ec06de391689040f1f4cf3386873d0a6a74687acf520e9aac0bec"},{"code_id":"NK_RF_2","article_number":"333.27","version_date":"2000-07-31","article_text":"1. При государственной регистрации актов гражданского состояния или совершении указанных в статье 33326 настоящего Кодекса действий государственная пошлина уплачивается с учетом следующих особенностей:\n\n1) при внесении исправлений и (или) изменений в записи актов гражданского состояния на основании заключения органа записи актов гражданского состояния государственная пошлина уплачивается в размере, установленном подпунктом 5 пункта 1 статьи 33326 настоящего Кодекса, независимо от количества записей актов гражданского состояния, в которые вносятся исправления и (или) изменения, и количества выданных свидетельств; (В редакции Федерального закона от 29.12.2004 № 204-ФЗ)\n\n2) за выдачу свидетельств о государственной регистрации актов гражданского состояния в связи с переменой имени государственная пошлина уплачивается в размере, установленном подпунктом 6 пункта 1 статьи 33326 настоящего Кодекса, за каждое свидетельство.\n\n2. За выдачу свидетельства о государственной регистрации акта гражданского состояния государственная пошлина не уплачивается, если соответствующая запись акта гражданского состояния восстановлена на основании решения суда.\n\n3. Положения настоящей статьи применяются с учетом положений статей 33335 и 33339 настоящего Кодекса.","article_title":"Статья 333.27. Особенности уплаты государственной пошлины за государственную регистрацию актов гражданского состояния и другие юридически значимые действия, совершаемые органами записи актов гражданского состояния и иными уполномоченными органами","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e3e441a3f17d420965bfa21282bef1ec5deac877db6d848536227c4134186258"},{"code_id":"NK_RF_2","article_number":"333.28","version_date":"2000-07-31","article_text":"1. За совершение действий, связанных с приобретением гражданства Российской Федерации или выходом из гражданства Российской Федерации, а также с въездом в Российскую Федерацию или выездом из Российской Федерации, государственная пошлина уплачивается в следующих размерах:\n\n1) за выдачу паспорта, удостоверяющего личность гражданина Российской Федерации за пределами территории Российской Федерации, - 2 000 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n2) за выдачу паспорта, удостоверяющего личность гражданина Российской Федерации за пределами территории Российской Федерации, содержащего электронный носитель информации (паспорта нового поколения), - 6000 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 03.07.2018 № 180-ФЗ, от 27.11.2023 № 539-ФЗ)\n\n3) за выдачу паспорта моряка, удостоверения личности моряка - 1 300 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n4) за внесение изменений в паспорт моряка, удостоверение личности моряка - 350 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n5) за выдачу паспорта, удостоверяющего личность гражданина Российской Федерации за пределами территории Российской Федерации, гражданину Российской Федерации в возрасте до 14 лет - 1 000 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n6) за выдачу паспорта, удостоверяющего личность гражданина Российской Федерации за пределами территории Российской Федерации, содержащего электронный носитель информации (паспорта нового поколения), гражданину Российской Федерации в возрасте до 14 лет - 3000 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 03.07.2018 № 180-ФЗ, от 27.11.2023 № 539-ФЗ)\n\n7) за внесение изменений в паспорт, удостоверяющий личность гражданина Российской Федерации за пределами территории Российской Федерации, - 500 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n8) за выдачу проездного документа беженца или продление срока действия указанного документа - 420 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 27.11.2023 № 539-ФЗ)\n\n9) за выдачу либо продление срока действия иностранному гражданину или лицу без гражданства, временно пребывающему в Российской Федерации, визы для:\n\nвыезда из Российской Федерации - 1200 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 27.11.2023 № 539-ФЗ)\n\nвыезда из Российской Федерации и последующего въезда в Российскую Федерацию - 1200 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 27.11.2023 № 539-ФЗ)\n\nмногократного пересечения Государственной границы Российской Федерации - 1920 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 27.11.2023 № 539-ФЗ)\n\n10) за предоставление федеральным органом исполнительной власти, ведающим вопросами иностранных дел, решения о выдаче обыкновенной однократной или двукратной визы, направляемого в дипломатическое представительство или консульское учреждение Российской Федерации, - 650 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n11) за предоставление федеральным органом исполнительной власти, ведающим вопросами иностранных дел, решения о выдаче обыкновенной многократной визы, направляемого в дипломатическое представительство или консульское учреждение Российской Федерации, - 1 000 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n12) за внесение федеральным органом исполнительной власти, ведающим вопросами иностранных дел, изменений в решение о выдаче визы - 350 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n13) за переадресацию федеральным органом исполнительной власти, ведающим вопросами иностранных дел, решения о выдаче визы в дипломатические представительства или консульские учреждения Российской Федерации по просьбе организации - 350 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n14) за первичную регистрацию организации в федеральном органе исполнительной власти, ведающем вопросами иностранных дел, или в его территориальном органе - 1 600 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n15) за ежегодную перерегистрацию организации в федеральном органе исполнительной власти, ведающем вопросами иностранных дел, или в его территориальном органе - 1 000 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n16) за выдачу, продление срока действия и восстановление виз иностранным гражданам и лицам без гражданства представительствами федерального органа исполнительной власти, ведающего вопросами иностранных дел, находящимися в пунктах пропуска через Государственную границу Российской Федерации, - в размерах, установленных Правительством Российской Федерации (в зависимости от видов осуществляемых действий), но не более 9 000 рублей за выдачу, продление срока действия и восстановление каждой визы;\n\n17) за выдачу приглашения на въезд в Российскую Федерацию иностранным гражданам или лицам без гражданства - 960 рублей за каждого приглашенного; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 27.11.2023 № 539-ФЗ)\n\n18) за выдачу вида на жительство иностранному гражданину или лицу без гражданства, в том числе в случае его замены, - 6000 рублей; (В редакции  федеральных законов от 02.08.2019 № 258-ФЗ, от 27.11.2023 № 539-ФЗ)\n\n19) за регистрацию иностранного гражданина или лица без гражданства по месту жительства в Российской Федерации, за исключением лиц, указанных в части 3 статьи 5 Федерального закона от 23 мая 2025 года № 121-ФЗ \"О внесении изменений в отдельные законодательные акты Российской Федерации и о проведении эксперимента по внедрению дополнительных механизмов учета иностранных граждан\", - 1000 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 27.11.2023 № 539-ФЗ, от 31.07.2025 № 271-ФЗ)\n\n191) за постановку иностранного гражданина или лица без гражданства на учет по месту пребывания, за исключением лиц, указанных в части 3 статьи 5 Федерального закона от 23 мая 2025 года № 121-ФЗ \"О внесении изменений в отдельные законодательные акты Российской Федерации и о проведении эксперимента по внедрению дополнительных механизмов учета иностранных граждан\", - 500 рублей; (Дополнение подпунктом - Федеральный закон от 31.07.2025 № 271-ФЗ)\n\n192) за продление срока временного пребывания иностранного гражданина в Российской Федерации, за исключением случаев, когда срок временного пребывания иностранного гражданина определяется сроком действия визы, - 1000 рублей; (Дополнение подпунктом - Федеральный закон от 31.07.2025 № 271-ФЗ)\n\n20) (Подпункт утратил силу - Федеральный закон от 27.07.2010 № 229-ФЗ)\n\n21) (Подпункт утратил силу - Федеральный закон от 27.07.2010 № 229-ФЗ)\n\n22) за выдачу иностранному гражданину или лицу без гражданства разрешения на временное проживание - 1920 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 14.07.2022 № 347-ФЗ, от 27.11.2023 № 539-ФЗ)\n\n221) за выдачу иностранному гражданину или лицу без гражданства разрешения на временное проживание в целях получения образования - 1920 рублей; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 347-ФЗ) (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\n23) за выдачу разрешений на привлечение и использование иностранных работников - 12 000 рублей за каждого привлекаемого иностранного работника; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 27.11.2023 № 539-ФЗ)\n\n231) за выдачу дубликатов разрешений на привлечение и использование иностранных работников, за внесение изменений в сведения, содержащиеся в разрешениях на привлечение и использование иностранных работников, - 2100 рублей; (Дополнение подпунктом - Федеральный закон от 31.07.2025 № 271-ФЗ)\n\n24) за выдачу разрешения на работу иностранному гражданину или лицу без гражданства - 4200 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 27.11.2023 № 539-ФЗ)\n\n241) за продление срока действия разрешения на работу иностранного гражданина или лица без гражданства - 4200 рублей; (Дополнение подпунктом - Федеральный закон от 31.07.2025 № 271-ФЗ)\n\n242) за выдачу дубликата разрешения на работу иностранного гражданина или лица без гражданства, за внесение изменений в сведения, содержащиеся в разрешении на работу иностранного гражданина или лица без гражданства, - 2100 рублей; (Дополнение подпунктом - Федеральный закон от 31.07.2025 № 271-ФЗ)\n\n25) за прием в гражданство Российской Федерации, выход из гражданства Российской Федерации, за установление факта наличия или отсутствия гражданства Российской Федерации - 4200 рублей; (В редакции  федеральных законов от 05.04.2010 № 41-ФЗ, от 21.07.2014 № 221-ФЗ, от 31.07.2023 № 389-ФЗ, от 27.11.2023 № 539-ФЗ)\n\n26) за выдачу документов, необходимых для установления и (или) выплаты в соответствии с пенсионным законодательством Российской Федерации страховой пенсии и (или) накопительной пенсии, а также пенсии по государственному пенсионному обеспечению, - 50 рублей за каждый документ; (В редакции Федерального закона от 29.06.2015 № 177-ФЗ)\n\n27) за выдачу либо переоформление патента иностранного гражданина или лица без гражданства - 4200 рублей; (Дополнение подпунктом - Федеральный закон от 31.07.2025 № 271-ФЗ)\n\n28) за выдачу дубликата патента иностранного гражданина или лица без гражданства, за внесение изменений в сведения, содержащиеся в патенте иностранного гражданина или лица без гражданства, - 2100 рублей. (Дополнение подпунктом - Федеральный закон от 31.07.2025 № 271-ФЗ)\n\n(Пункт в редакции Федерального закона от 27.12.2009 № 374-ФЗ)\n\n2. Положения настоящей статьи применяются с учетом положений статьи 33329 настоящего Кодекса.","article_title":"Статья 333.28. Размеры государственной пошлины за совершение действий, связанных с приобретением гражданства Российской Федерации или выходом из гражданства Российской Федерации, а также с въездом в Российскую Федерацию или выездом из Российской Федерации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ff67364499cd5d6bca9bdd5d3783f032331fcb022375de0eae983b72e956b5e7"},{"code_id":"NK_RF_2","article_number":"333.29","version_date":"2000-07-31","article_text":"За совершение указанных в статье 33328 настоящего Кодекса действий государственная пошлина уплачивается с учетом следующих особенностей:\n\n1) (Пункт утратил силу - Федеральный закон от 29.12.2004 № 204-ФЗ)\n\n2) при приеме в гражданство Российской Федерации физических лиц, имевших гражданство СССР, проживавших и проживающих в государствах, входивших в состав СССР, но не получивших гражданства этих государств и остающихся в результате этого лицами без гражданства, государственная пошлина не уплачивается. Если физическое лицо в заявлении о приеме в гражданство Российской Федерации одновременно просит принять в гражданство Российской Федерации своих несовершеннолетних детей, подопечных, государственная пошлина уплачивается в размере, определенном подпунктом 25 пункта 1 статьи 33328 настоящего Кодекса, как за рассмотрение одного заявления; (В редакции  федеральных законов от 31.12.2005 № 201-ФЗ, от 05.04.2010 № 41-ФЗ, от 31.07.2023 № 389-ФЗ)\n\n3) при приеме в гражданство Российской Федерации детей-сирот и детей, оставшихся без попечения родителей, государственная пошлина не уплачивается; (Дополнение пунктом - Федеральный закон от 21.07.2005 № 106-ФЗ)\n\n4) за выдачу гражданину Российской Федерации, местом жительства которого является Калининградская область, документов, предусмотренных подпунктами 1, 2, 5 и 6 пункта 1 статьи 33328 настоящего Кодекса, государственная пошлина не уплачивается; (Дополнение пунктом - Федеральный закон от 05.12.2005 № 155-ФЗ) (В редакции федеральных законов от 31.12.2005 № 201-ФЗ; от 27.12.2009 № 374-ФЗ)\n\n5) за выдачу, продление срока действия и восстановление в исключительных случаях виз иностранным гражданам и лицам без гражданства представительствами федерального органа исполнительной власти, ведающего вопросами иностранных дел, находящимися в пунктах пропуска через Государственную границу Российской Федерации, государственная пошлина может быть уплачена в иностранной валюте по курсу, установленному Центральным банком Российской Федерации на дату ее уплаты; (Дополнение пунктом - Федеральный закон от 27.12.2009 № 374-ФЗ)\n\n6) за регистрацию по месту жительства в Российской Федерации иностранных граждан и лиц без гражданства, являющихся участниками Государственной программы по оказанию содействия добровольному переселению в Российскую Федерацию соотечественников, проживающих за рубежом, а также членов их семей, совместно переселившихся на постоянное место жительства в Российскую Федерацию, государственная пошлина не уплачивается; (Дополнение пунктом - Федеральный закон от 21.04.2011 № 77-ФЗ)\n\n7) за постановку на учет по месту пребывания иностранных граждан и лиц без гражданства в гостинице или ином средстве размещения, в котором предоставляются услуги средств размещения, в организации отдыха детей и их оздоровления, в медицинской организации, оказывающей медицинскую помощь в стационарных условиях, в организации социального обслуживания, предоставляющей социальные услуги в стационарной форме, в учреждении, исполняющем уголовное или административное наказание, а также за постановку на учет по месту пребывания иностранных граждан и лиц без гражданства дипломатическими представительствами и консульскими учреждениями иностранного государства в Российской Федерации государственная пошлина не уплачивается, за исключением случаев, когда иностранные граждане и лица без гражданства осуществляют трудовую деятельность в указанных организациях. (Дополнение пунктом - Федеральный закон от 31.07.2025 № 271-ФЗ)","article_title":"Статья 333.29. Особенности уплаты государственной пошлины за совершение действий, связанных с приобретением гражданства Российской Федерации или выходом из гражданства Российской Федерации, а также с въездом в Российскую Федерацию или выездом из Российской Федерации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"01844c6b0183574490372bf3d955b2fd093314a4410d17a783144181e5699308"},{"code_id":"NK_RF_2","article_number":"333.3","version_date":"2000-07-31","article_text":"1. Ставки сбора за каждый объект животного мира устанавливаются в следующих размерах, если иное не установлено пунктами 2 и 3 настоящей статьи:\n\nНаименование объекта животного мира\n\nСтавка сбора в рублях (за одно животное)\n\n2. При изъятии молодняка (в возрасте до одного года) диких копытных животных ставки сбора за пользование объектами животного мира устанавливаются в размере 50 процентов ставок, установленных пунктом 1 настоящей статьи.\n\n3. Ставки сбора за каждый объект животного мира, указанный в пункте 1 настоящей статьи, устанавливаются в размере 0 рублей в случаях, если пользование такими объектами животного мира осуществляется в целях:\n\nохраны здоровья населения, устранения угрозы для жизни человека, предохранения от заболеваний сельскохозяйственных и домашних животных, регулирования видового состава объектов животного мира, предотвращения нанесения ущерба экономике, животному миру и среде его обитания, а также в целях воспроизводства объектов животного мира, осуществляемого в соответствии с разрешением уполномоченного органа исполнительной власти;\n\nизучения запасов, а также в научных целях в соответствии с законодательством Российской Федерации. (В редакции Федерального закона от 24.07.2009 № 209-ФЗ)\n\n4. Ставки сбора за каждый объект водных биологических ресурсов, за исключением морских млекопитающих, устанавливаются в следующих размерах, если иное не установлено пунктом 6 настоящей статьи:\n\nНаименование объекта водных биологических ресурсов\n\nСтавка сбора в рублях(за одну тонну)\n\nДальневосточный бассейн (внутренние морские воды, территориальное море, исключительная экономическая зона Российской Федерации и континентальный шельф Российской Федерации в Чукотском, Восточно-Сибирском, Беринговом, Охотском, Японском морях и Тихом океане)\n\nМорской окунь\n\nОсетровые*\n\nМойва, анчоус, ликоды, макрурусы, сайка, лемонема, бычки, рыбы-собаки, песчанка, акулы, скаты, кефалевые рыбы, прочие\n\nКраб камчатский\n\nКраб синий\n\nКраб равношипый\n\nКраб-стригун бэрди\n\nКраб-стригун опилио\n\nКраб-стригун ангулятус\n\nКраб-стригун красный\n\nКраб-стригун веррилла\n\nКраб-стригун таннери\n\nКраб коуэзи\n\nКраб колючий района южных Курильских островов\n\nКраб колючий других районов промысла\n\nКраб волосатый четырехугольный района юго-восточного Сахалина и залива Анива зоны Охотского моря и юго-западного Сахалина зоны Японского моря\n\nКраб волосатый четырехугольный других районов промысла\n\nКреветка углохвостая\n\nКреветка северная\n\nКреветка северная Берингова моря\n\nКреветка травяная\n\nКреветка гребенчатая\n\nДругие виды креветок\n\nКальмар подзоны Приморье\n\nМорской гребешок\n\nПрочие моллюски (мидии и другие)\n\nМорской еж серый\n\nМорской еж черный\n\nМорской еж прочий (палевый, многоиглый, зеленый и другие)\n\nПрочие водные биологические ресурсы\n\nСеверный бассейн (Белое море, внутренние морские воды, территориальное море, исключительная экономическая зона Российской Федерации и континентальный шельф Российской Федерации в море Лаптевых, Карском и Баренцевом морях и районе архипелага Шпицберген)\n\nАтлантический лосось (семга)\n\nСельдь чешско-печорская и беломорская\n\nПалтус черный\n\nМорской окунь\n\nРяпушка, корюшка, навага, зубатки\n\nСайка, мойва, пинагор, песчанка европейская, звездчатый скат, полярная акула, менек, прочие\n\nКраб камчатский\n\nКреветка северная\n\nКреветка шримс-медвежонок\n\nКреветки другие (эвфаузииды)\n\nМорской гребешок\n\nПрочие моллюски\n\nМорской еж зеленый\n\nКраб-стригун опилио\n\nБалтийский бассейн (внутренние морские воды, территориальное море, исключительная экономическая зона Российской Федерации и континентальный шельф Российской Федерации в Балтийском море, Вислинском, Куршском и Финском заливах)\n\nСалака (сельдь)\n\nШпрот (килька)\n\nАтлантический лосось (балтийский лосось)\n\nСиг-пыжьян\n\nКамбала-тюрбо\n\nКамбала других видов\n\nРыбец (сырть)\n\nРяпушка, лещ, щука, налим, колюшка, плотва, ерш, снеток, чехонь, красноперка, густера, прочие\n\nКаспийский бассейн (районы Каспийского моря, в которых Российская Федерация осуществляет юрисдикцию в отношении рыболовства)\n\nКилька (анчоусовидная, большеглазая, обыкновенная)\n\nСельдь (долгинская, каспийский пузанок, большеглазый пузанок, проходная-черноспинка)\n\nКрупный частик (кефаль, атерина, лещ, сазан, сом, густера, щука, прочие, за исключением судака и кутума)\n\nОсетровые*\n\nКрасноперка, линь, окунь, карась, прочие пресноводные в прилове\n\nАзово-Черноморский бассейн (внутренние морские воды и территориальное море, исключительная экономическая зона Российской Федерации в Черном море, районы Азовского моря с Таганрогским заливом, в которых Российская Федерация осуществляет юрисдикцию в отношении рыболовства)\n\nКамбала-калкан\n\nКефаль всех видов\n\nШпрот (килька)\n\nРыбец (сырть)\n\nОсетровые*\n\nСкат, чехонь, акула-катран, ставрида, атерина, бычки, скафарка, мерланг, прочие\n\nПрочие водные биологические ресурсы (моллюски, водоросли)\n\nВнутренние водные объекты (реки, водохранилища, озера)\n\nОсетровые*\n\nАтлантический лосось (балтийский лосось, семга), нельма, таймень, угорь\n\nБайкальский белый хариус, чир, муксун\n\nКунджа, мальма, голец, палия, форель всех видов, ленок, сиг, омуль, пыжьян, пелядь, усач, черноспинка, рыбец (сырть), жерех, хариус, шемая, кутум, сом, минога\n\nБелый амур, толстолобик\n\nКрупный частик (за исключением судака)\n\nРипус, тарань, вобла, ряпушка\n\nПрочие объекты водных биологических ресурсов\n\n______________________________\n\n* Сбор взимается в случае разрешенного промысла.\n\nС 2025 года ставки сбора за каждый объект водных биологических ресурсов, установленные настоящим пунктом, подлежат индексации на коэффициент-дефлятор, установленный на соответствующий календарный год.\n\n(Пункт в редакции  Федерального закона от 21.11.2022 № 444-ФЗ)\n\n5. Ставки сбора за каждый объект водных биологических ресурсов - морское млекопитающее устанавливаются в следующих размерах, если иное не установлено пунктом 6 настоящей статьи:\n\nНаименование объекта водных биологических ресурсов - морского млекопитающего\n\nСтавка сбора в рублях(за одну тонну)\n\n(Пункт в редакции Федерального закона от 29.11.2007 № 285-ФЗ)\n\nрыболовстве в целях аквакультуры (рыбоводства); (В редакции  Федерального закона от 21.11.2022 № 444-ФЗ)\n\nрыболовстве в научно-исследовательских и контрольных целях. (В редакции Федерального закона от 06.12.2007 № 333-ФЗ)\n\nВ целях настоящей главы градо- и поселкообразующими российскими рыбохозяйственными организациями признаются организации, которые удовлетворяют следующим критериям:\n\nосуществляют рыболовство на судах рыбопромыслового флота, принадлежащих им на праве собственности, или используют их на основании договора финансовой аренды (договора лизинга) или договоров фрахтования (бербоут-чартера и тайм-чартера);\n\nзарегистрированы в качестве юридического лица в соответствии с законодательством Российской Федерации до 1 января 2022 года;\n\nв общем доходе от реализации товаров (работ, услуг) доля дохода от реализации добытых (выловленных) ими водных биологических ресурсов и (или) иной продукции из водных биологических ресурсов, произведенной из добытых (выловленных) ими водных биологических ресурсов, составляет не менее 70 процентов за календарный год, предшествующий году выдачи разрешения на добычу (вылов) водных биологических ресурсов;\n\nчисленность работников с учетом совместно проживающих с ними членов семей по состоянию на 1 января календарного года, в котором осуществляется выдача разрешения на добычу (вылов) водных биологических ресурсов, составляет не менее половины численности населения соответствующего населенного пункта.\n\nВ целях настоящей главы рыболовецкими артелями (колхозами) признаются рыболовецкие артели (колхозы), осуществляющие рыболовство и (или) производство рыбной продукции из добытых (выловленных) ими водных биологических ресурсов (в том числе на судах рыбопромыслового флота, используемых на основании договора финансовой аренды (договора лизинга) или договоров фрахтования (бербоут-чартера и тайм-чартера) и реализующие эти уловы и продукцию, при условии, если в общем доходе от реализации товаров (работ, услуг) таких организаций доля дохода от реализации добытых (выловленных) ими водных биологических ресурсов и (или) произведенной из них рыбной продукции составляет не менее 70 процентов за календарный год, предшествующий году выдачи разрешения на добычу (вылов) водных биологических ресурсов.\n\n(Пункт в редакции  Федерального закона от 21.11.2022 № 444-ФЗ)","article_title":"Статья 333.3. Ставки сборов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"81f7da92405c204f5a7b5cfe352a749ac4dcaf2617b2b1570a5508485b7a0f08"},{"code_id":"NK_RF_2","article_number":"333.30","version_date":"2000-07-31","article_text":"При обращении в уполномоченный федеральный орган исполнительной власти за совершением действий по государственной регистрации программы для электронных вычислительных машин (далее - ЭВМ), базы данных или топологии интегральной микросхемы государственная пошлина уплачивается в следующих размерах:\n\n1) за рассмотрение заявки на государственную регистрацию программы для ЭВМ, базы данных или топологии интегральной микросхемы и принятие решения по результатам рассмотрения заявки - 5000 рублей;\n\n2) за рассмотрение заявления правообладателя о внесении изменений в Реестр программ для ЭВМ, Реестр баз данных или Реестр топологий интегральных микросхем и принятие решения по результатам рассмотрения заявления - 3000 рублей за каждую программу для ЭВМ, каждую базу данных или каждую топологию интегральной микросхемы;\n\n3) за рассмотрение заявления о государственной регистрации отчуждения исключительного права на зарегистрированные программу для ЭВМ, базу данных или топологию интегральной микросхемы по договору, залога такого пра\n\nва по договору или предоставления права использования зарегистрированной топологии интегральной микросхемы по договору, о внесении изменений в зарегистрированное распоряжение исключительным правом по соответствующему договору либо о прекращении зарегистрированного распоряжения исключительным правом по договору о предоставлении права использования или о залоге исключительного права на зарегистрированные программу для ЭВМ, базу данных или топологию интегральной микросхемы и принятие решения по результатам рассмотрения заявления - 5000 рублей и дополнительно 3000 рублей за предусмотренные договором каждую программу для ЭВМ, каждую базу данных или каждую топологию интегральной микросхемы свыше одной;\n\n4) за рассмотрение заявления о государственной регистрации перехода исключительного права на зарегистрированные программу для ЭВМ, базу данных или топологию интегральной микросхемы к другому лицу без договора и принятие решения по результатам рассмотрения заявления - 5000 рублей и дополнительно 3000 рублей за включенные в заявление каждую зарегистрированную программу для ЭВМ, каждую зарегистрированную базу данных или каждую зарегистрированную топологию интегральной микросхемы свыше одной.\n\n(Статья в редакции  Федерального закона от 23.11.2024 № 389-ФЗ)","article_title":"Статья 333.30. Размеры государственной пошлины за совершение уполномоченным федеральным органом исполнительной власти действий по государственной регистрации программы для электронных вычислительных машин, базы данных и топологии интегральной микросхемы","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"92c8e2945adcdd65106e07262d1b14b2c892473b96b9619f21f5ed4a1896f247"},{"code_id":"NK_RF_2","article_number":"333.31","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 15.10.2020 № 324-ФЗ)\n\n1) за опробование и клеймение государственным пробирным клеймом ювелирных и других изделий из драгоценных металлов: (В редакции Федерального закона от 02.05.2015 № 112-ФЗ)\n\nпо золотым изделиям - до 200 рублей за одну единицу; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\nпо серебряным изделиям - до 500 рублей за одну единицу; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\nпо платиновым изделиям - до 200 рублей за одну единицу; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\nпо палладиевым изделиям - до 200 рублей за одну единицу; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n2) за экспертизу ювелирных и других изделий из драгоценных металлов, экспертизу и геммологическую экспертизу драгоценных камней, за исключением случаев, предусмотренных подпунктами 3 и 4 настоящего пункта, - до 5 500 рублей за одну единицу; (В редакции федеральных законов от 21.07.2014 № 221-ФЗ; от 02.05.2015 № 112-ФЗ)\n\n3) за выполняемую федеральным органом исполнительной власти, осуществляющим функции по государственному контролю (надзору) за производством, использованием и обращением драгоценных металлов, за использованием и обращением драгоценных камней, для музеев экспертизу драгоценных металлов и драгоценных камней, а также вставок из различных материалов в изделиях - до 100 рублей за одну единицу; (В редакции Федерального закона от 15.10.2020 № 324-ФЗ)\n\n4) (Подпункт утратил силу - Федеральный закон от 29.11.2012 № 205-ФЗ)\n\n5) за проведение анализа материалов, содержащих драгоценные металлы, - до 2 500 рублей за определение одного элемента; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n6) за регистрацию именников - до 1 000 рублей за одну единицу измерения; (В редакции Федерального закона от 02.05.2015 № 112-ФЗ)\n\n7) за изготовление именников по обращениям изготовителей ювелирных и других изделий из драгоценных металлов - до 1 000 рублей за одну единицу измерения; (Дополнение подпунктом - Федеральный закон от 02.05.2015 № 112-ФЗ)\n\n8) за постановку по обращениям изготовителей ювелирных и других изделий из драгоценных металлов оттисков именников электроискровым методом - до 1 000 рублей за одну единицу измерения; (Дополнение подпунктом - Федеральный закон от 02.05.2015 № 112-ФЗ)\n\n9) за уничтожение на ювелирных и других изделиях из драгоценных металлов оттисков фальшивых пробирных клейм, именников, изготовление пробирных реактивов - до 1 000 рублей за одну единицу измерения; (Дополнение подпунктом - Федеральный закон от 02.05.2015 № 112-ФЗ)\n\n10) за хранение представленных на опробование и клеймение ювелирных и других изделий из драгоценных металлов сверх установленного Правительством Российской Федерации срока - до 1 000 рублей за одну единицу измерения. (Дополнение подпунктом - Федеральный закон от 02.05.2015 № 112-ФЗ)\n\n(Пункт в редакции Федерального закона от 27.12.2009 № 374-ФЗ)","article_title":"Статья 333.31. Размеры государственной пошлины за совершение действий федеральным органом исполнительной власти, осуществляющим функции по государственному контролю (надзору) за производством, использованием и обращением драгоценных металлов, за использованием и обращением драгоценных камней","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f365eaf76b0456bdf24b3bf0041a38cf7d2204754de8140dd31c857032ba86c9"},{"code_id":"NK_RF_2","article_number":"333.32","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 15.10.2020 № 324-ФЗ)\n\n1. Государственная пошлина за совершение действий, указанных в статье 33331 настоящего Кодекса, уплачивается:\n\n1) до выдачи изделий - при предъявлении ювелирных, других изделий из драгоценных металлов на опробование и клеймение; (В редакции федеральных законов от 29.12.2004 № 203-ФЗ; от 02.05.2015 № 112-ФЗ)\n\n2) до выдачи результатов экспертизы - при предъявлении различных предметов, изделий, материалов и камней на экспертизу. (В редакции Федерального закона от 31.12.2005 № 201-ФЗ)\n\nПри проведении экспертизы на территориях музеев и экспертизы драгоценных камней по запросу правоохранительных органов государственная пошлина уплачивается после проведения экспертизы и оформления соответствующих документов, но до выдачи результатов экспертизы. (В редакции федеральных законов от 31.12.2005 № 201-ФЗ, от 02.05.2015 № 112-ФЗ)\n\n1) при выдаче заклейменных изделий в течение одних суток с момента принятия изделий - на 200 процентов;\n\n2) при выдаче заклейменных изделий в течение двух суток с момента принятия изделий - на 100 процентов;\n\n3) при выдаче результатов экспертизы или результатов анализов в течение одних суток с момента принятия изделий - на 200 процентов.\n\n1) при предъявлении изделий с закрепленными камнями (вставками), за исключением изделий, предъявляемых после ремонта, - на 100 процентов;\n\n2) при предъявлении изделий, составные части (детали) которых изготовлены из различных сплавов драгоценных металлов, - на 100 процентов. При этом размер государственной пошлины устанавливается по драгоценному металлу основной части изделия, на которую налагается основное государственное пробирное клеймо;\n\n3) при предъявлении изделий, предъявляемых в индивидуальной упаковке или с прикрепленными ярлыками (бирками, пломбами и тому подобное), работа с которыми связана с дополнительными затратами времени, - на 50 процентов.","article_title":"Статья 333.32. Особенности уплаты государственной пошлины за совершение действий федеральным органом исполнительной власти, осуществляющим функции по государственному контролю (надзору) за производством, использованием и обращением драгоценных металлов, за использованием и обращением драгоценных камней","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"544c3a885901dbb492408d85d0d9d9932c0aa3a0bb8ee4aaad2d6a52c29b3b9a"},{"code_id":"NK_RF_2","article_number":"33332.1","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 07.03.2017 № 25-ФЗ, от 31.07.2025 № 299-ФЗ)\n\n1) за проведение этической экспертизы, экспертизы документов лекарственного препарата для получения разрешения на проведение клинического исследования лекарственного препарата для медицинского применения - 135 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n2) за проведение экспертизы документов, представленных для определения возможности рассматривать лекарственный препарат для медицинского применения при государственной регистрации в качестве орфанного лекарственного препарата, - 420 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n3) за проведение экспертизы документов лекарственного препарата для получения разрешения на проведение международного многоцентрового клинического исследования лекарственного препарата для медицинского применения - 210 000 рублей;\n\n4) за проведение этической экспертизы, экспертизы документов лекарственного препарата для получения разрешения на проведение пострегистрационного клинического исследования лекарственного препарата для медицинского применения - 135 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n5) (Подпункт утратил силу - Федеральный закон от 29.11.2021 № 382-ФЗ)\n\n6) (Подпункт утратил силу - Федеральный закон от 29.11.2021 № 382-ФЗ)\n\n7) за проведение экспертизы качества лекарственного средства и экспертизы отношения ожидаемой пользы к возможному риску применения лекарственного препарата для медицинского применения, в отношении которого проведены международные многоцентровые клинические исследования, часть из которых проведена в Российской Федерации, при государственной регистрации лекарственного препарата - 325 000 рублей;\n\n8) за проведение экспертизы качества лекарственного средства и экспертизы отношения ожидаемой пользы к возможному риску применения лекарственного препарата для ветеринарного применения при его государственной регистрации - 215 000 рублей;\n\n9) за выдачу разрешения на проведение клинического исследования лекарственного препарата для медицинского применения - 5 000 рублей;\n\n10) за выдачу разрешения на проведение международного многоцентрового клинического исследования лекарственного препарата для медицинского применения - 5 000 рублей;\n\n11) за выдачу разрешения на проведение пострегистрационного клинического исследования лекарственного препарата для медицинского применения - 5 000 рублей;\n\n12) за выдачу регистрационного удостоверения лекарственного препарата - 10 000 рублей;\n\n13) за подтверждение государственной регистрации лекарственного препарата для медицинского применения - 172 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n14) за подтверждение государственной регистрации лекарственного препарата для ветеринарного применения - 70 000 рублей;\n\n15) за внесение в документы, содержащиеся в регистрационном досье на зарегистрированный лекарственный препарат для медицинского применения, изменений, требующих проведения экспертизы лекарственных средств в части экспертизы качества лекарственного средства и (или) экспертизы отношения ожидаемой пользы к возможному риску применения лекарственного препарата для медицинского применения, - 490 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n16) за внесение в документы, содержащиеся в регистрационном досье на зарегистрированный лекарственный препарат для медицинского применения, изменений, не требующих проведения экспертизы лекарственных средств для медицинского применения, - 5 000 рублей;\n\n17) за включение в государственный реестр лекарственных средств фармацевтической субстанции, произведенной для реализации, - 253 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n18) за внесение в документы на фармацевтическую субстанцию, произведенную для реализации и включенную в государственный реестр лекарственных средств, изменений, требующих проведения экспертизы лекарственных средств, - 253 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n19) за внесение в документы на фармацевтическую субстанцию, произведенную для реализации и включенную в государственный реестр лекарственных средств, изменений, не требующих проведения экспертизы лекарственных средств, - 5 000 рублей;\n\n20) за внесение в документы, содержащиеся в регистрационном досье на зарегистрированный лекарственный препарат для ветеринарного применения, изменений, требующих проведения экспертизы лекарственных средств для ветеринарного применения, - 70 000 рублей;\n\n21) за внесение в документы, содержащиеся в регистрационном досье на зарегистрированный лекарственный препарат для ветеринарного применения, изменений, не требующих проведения экспертизы лекарственных средств для ветеринарного применения, - 2 600 рублей;\n\n22) за выдачу дубликата регистрационного удостоверения лекарственного препарата - 2 000 рублей.\n\n1) за проведение экспертизы лекарственного препарата для медицинского применения при его регистрации - 325 000 рублей;\n\n2) за оценку экспертного отчета об оценке безопасности, эффективности и качества лекарственного препарата для медицинского применения - 325 000 рублей;\n\n3) за проведение экспертизы лекарственного препарата с хорошо изученным медицинским применением при его регистрации - 250 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n4) за оценку экспертного отчета об оценке безопасности, эффективности и качества лекарственного препарата с хорошо изученным медицинским применением при его регистрации - 165 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n5) за подтверждение регистрации лекарственного препарата для медицинского применения - 207 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n6) за внесение в документы, содержащиеся в регистрационном досье зарегистрированного лекарственного препарата для медицинского применения, изменений, требующих проведения экспертизы лекарственного препарата для медицинского применения, - 150 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n7) за внесение в документы, содержащиеся в регистрационном досье зарегистрированного лекарственного препарата для медицинского применения, изменений, не требующих проведения экспертизы лекарственного препарата для медицинского применения, - 5 000 рублей;\n\n8) за приведение регистрационного досье лекарственного препарата для медицинского применения в соответствие с требованиями Евразийского экономического союза - 115 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n9) за выдачу регистрационного удостоверения лекарственного препарата для медицинского применения - 10 000 рублей;\n\n10) за выдачу дубликата регистрационного удостоверения лекарственного препарата для медицинского применения - 2 000 рублей.\n\n(Дополнение пунктом - Федеральный закон от 07.03.2017 № 25-ФЗ)\n\n1) за проведение экспертизы ветеринарного лекарственного средства в целях регистрации ветеринарного лекарственного препарата - 461 000 рублей;\n\n2) за проведение экспертизы документов на ветеринарный лекарственный препарат в рамках проведения процедуры его регистрации - 360 000 рублей;\n\n3) за проведение экспертизы ветеринарного лекарственного средства в целях подтверждения регистрации ветеринарного лекарственного препарата - 164 000 рублей;\n\n4) за проведение экспертизы документов на ветеринарный лекарственный препарат в рамках проведения процедуры подтверждения его регистрации - 149 000 рублей;\n\n5) за проведение экспертизы регистрационного досье ветеринарного лекарственного препарата и экспертизы образцов ветеринарного лекарственного средства в рамках процедуры внесения изменений в указанное регистрационное досье - 323 000 рублей;\n\n6) за проведение экспертизы регистрационного досье ветеринарного лекарственного препарата без проведения экспертизы образцов ветеринарного лекарственного средства в рамках процедуры внесения изменений в указанное регистрационное досье - 191 000 рублей;\n\n7) за внесение изменений в документы, содержащиеся в регистрационном досье ветеринарного лекарственного препарата, без проведения экспертизы указанного регистрационного досье и экспертизы образцов ветеринарного лекарственного средства в рамках процедуры внесения изменений в указанное регистрационное досье - 11 000 рублей;\n\n8) за проведение экспертизы документов на ветеринарный лекарственный препарат в рамках процедуры внесения изменений в регистрационное досье ветеринарного лекарственного препарата - 231 000 рублей;\n\n9) за проведение экспертизы ветеринарного лекарственного средства в целях при\n\nведения регистрационного досье ветеринарного лекарственного препарата в соответствие с требованиями Евразийского экономического союза - 323 000 рублей;\n\n10) за проведение экспертизы документов на ветеринарный лекарственный препарат в рамках процедуры приведения регистрационного досье ветеринарного лекарственного препарата в соответствие с требованиями Евразийского экономического союза - 220 000 рублей;\n\n11) за принятие решения о возможности признания регистрации ветеринарного лекарственного препарата, зарегистрированного в рамках Евразийского экономического союза, в государствах, присоединившихся к Евразийскому экономическому союзу после регистрации ветеринарного лекарственного препарата, - 44 000 рублей;\n\n12) за проведение экспертизы документов на ветеринарный лекарственный препарат в целях признания регистрации ветеринарного лекарственного препарата - 320 000 рублей.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2025 № 299-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 05.04.2010 № 41-ФЗ) (В редакции Федерального закона от 29.12.2014 № 480-ФЗ)","article_title":"Статья 33332.1. Размеры государственной пошлины за совершение действий уполномоченным федеральным органом исполнительной власти при осуществлении государственной регистрации лекарственных препаратов и регистрации лекарственных препаратов для медицинского применения, ветеринарных лекарственных препаратов в целях формирования общего рынка лекарственных средств в рамках Евразийского экономического союза","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f844fe1bdca445cc3c2d0b73516c2109e99fb46869ca270239f069c4a0123934"},{"code_id":"NK_RF_2","article_number":"33332.2","version_date":"2000-07-31","article_text":"1. За совершение уполномоченным федеральным органом исполнительной власти действий, связанных с осуществлением государственной регистрации медицинских изделий в соответствии с Федеральным законом от 21 ноября 2011 года № 323-ФЗ \"Об основах охраны здоровья граждан в Российской Федерации\", государственная пошлина уплачивается в следующих размерах:\n\n1) за выдачу регистрационного удостоверения на медицинское изделие - 11 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n2) за проведение экспертизы качества, эффективности и безопасности медицинского изделия (в зависимости от класса потенциального риска его применения в соответствии с номенклатурной классификацией медицинских изделий, утвержденной федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере здравоохранения) при его государственной регистрации:\n\nкласс 1 - 72 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nкласс 2а - 104 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nкласс 2б - 136 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nкласс 3 - 184 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n3) за внесение в документы, содержащиеся в регистрационном досье медицинского изделия, изменений, не требующих проведения экспертизы качества, эффективности и безопасности медицинского изделия, - 2 500 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n4) за проведение экспертизы качества, эффективности и безопасности медицинского изделия (в зависимости от класса потенциального риска его применения в соответствии с номенклатурной классификацией медицинских изделий, утвержденной федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере здравоохранения) при внесении изменений в документы, содержащиеся в регистрационном досье медицинского изделия:\n\nкласс 1 - 32 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nкласс 2а - 48 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nкласс 2б - 64 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nкласс 3 - 104 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n5) за выдачу дубликата регистрационного удостоверения на медицинское изделие - 2 500 рублей. (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n2. За совершение уполномоченным федеральным органом исполнительной власти действий, связанных с осуществлением регистрации медицинских изделий, предназначенных для обращения на общем рынке медицинских изделий в рамках Евразийского экономического союза, в соответствии с правом Евразийского экономического союза, государственная пошлина уплачивается в следующих размерах:\n\n1) за выдачу регистрационного удостоверения медицинского изделия - 11 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n2) за проведение экспертизы безопасности, качества и эффективности медицинского изделия (в зависимости от класса потенциального риска его применения в соответствии с правом Евразийского экономического союза) при его регистрации:\n\nкласс 1 - 72 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nкласс 2а - 104 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nкласс 2б - 136 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nкласс 3 - 184 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n3) за внесение в документы, содержащиеся в регистрационном досье медицинского изделия, изменений, не требующих проведения экспертизы безопасности, качества и эффективности медицинского изделия, - 2 500 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n4) за проведение экспертизы безопасности, качества и эффективности медицинского изделия (в зависимости от класса потенциального риска его применения в соответствии с правом Евразийского экономического союза) при внесении изменений в документы, содержащиеся в регистрационном досье медицинского изделия:\n\nкласс 1 - 32 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nкласс 2а - 48 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nкласс 2б - 64 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nкласс 3 - 104 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n5) за выдачу дубликата регистрационного удостоверения медицинского изделия - 2 500 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n6) за согласование экспертного заключения об оценке безопасности, эффективности и качества медицинского изделия при его регистрации (в зависимости от класса потенциального риска его применения в соответствии с правом Евразийского экономического союза):\n\nкласс 1 - 72 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nкласс 2а - 104 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nкласс 2б - 136 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nкласс 3 - 184 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n7) за согласование экспертного заключения об оценке безопасности, эффективности и качества медицинского изделия при внесении изменений в документы, содержащиеся в регистрационном досье медицинского изделия (в зависимости от класса потенциального риска его применения в соответствии с правом Евразийского экономического союза):\n\nкласс 1 - 32 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nкласс 2а - 48 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nкласс 2б - 64 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nкласс 3 - 104 000 рублей. (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 25.11.2013 № 317-ФЗ) (В редакции Федерального закона от 07.03.2017 № 25-ФЗ)","article_title":"Статья 33332.2. Размеры государственной пошлины за совершение действий уполномоченным федеральным органом исполнительной власти при осуществлении государственной регистрации медицинских изделий и регистрации медицинских изделий, предназначенных для обращения на общем рынке медицинских изделий в рамках Евразийского экономического союза","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2e8ad617cef14a067c200227b9a0725244b1646592cda2b5f389b39c7145d079"},{"code_id":"NK_RF_2","article_number":"33332.3","version_date":"2000-07-31","article_text":"За совершение уполномоченным федеральным органом исполнительной власти действий, связанных с осуществлением государственной регистрации биомедицинских клеточных продуктов в соответствии с Федеральным законом от 23 июня 2016 года № 180-ФЗ \"О биомедицинских клеточных продуктах\", государственная пошлина уплачивается в следующих размерах (в зависимости от видов осуществляемых действий):\n\n1) за проведение экспертизы качества биомедицинского клеточного продукта, экспертизы документов для получения разрешения на проведение клинического исследования биомедицинского клеточного продукта и этической экспертизы возможности проведения клинического исследования биомедицинского клеточного продукта при обращении за государственной регистрацией биомедицинского клеточного продукта - 580 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n2) за проведение экспертизы эффективности биомедицинского клеточного продукта и экспертизы отношения ожидаемой пользы к возможному риску применения биомедицинского клеточного продукта при государственной регистрации биомедицинского клеточного продукта - 220 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n3) за проведение экспертизы эффективности биомедицинского клеточного продукта и экспертизы отношения ожидаемой пользы к возможному риску применения биомедицинского клеточного продукта, в отношении которого проведены международные многоцентровые клинические исследования, часть из которых проведена в Российской Федерации, при обращении за государственной регистрацией биомедицинского клеточного продукта - 415 000 рублей; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n4) за выдачу разрешения на проведение клинического исследования биомедицинского клеточного продукта - 5 000 рублей;\n\n5) за выдачу регистрационного удостоверения биомедицинского клеточного продукта - 5 000 рублей;\n\n6) за выдачу дубликата регистрационного удостоверения биомедицинского клеточного продукта - 5 000 рублей;\n\n7) за подтверждение государственной регистрации биомедицинского клеточного продукта - 50 000 рублей;\n\n8) за внесение в документы, содержащиеся в регистрационном досье на зарегистрированный биомедицинский клеточный продукт, изменений, требующих проведения биомедицинской экспертизы биомедицинского клеточного продукта, - 75 000 рублей;\n\n9) за внесение в документы, содержащиеся в регистрационном досье на зарегистрированный биомедицинский клеточный продукт, изменений, не требующих проведения биомедицинской экспертизы биомедицинского клеточного продукта, - 5 000 рублей;\n\n10) за выдачу разрешения на проведение международного многоцентрового клинического исследования биомедицинского клеточного продукта - 100 000 рублей;\n\n11) за выдачу разрешения на проведение пострегистрационного клинического исследования биомедицинского клеточного продукта - 100 000 рублей.\n\n(Дополнение статьей - Федеральный закон от 07.03.2017 № 25-ФЗ)","article_title":"Статья 33332.3. Размеры государственной пошлины за совершение действий уполномоченным федеральным органом исполнительной власти при осуществлении государственной регистрации биомедицинских клеточных продуктов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9d532b7f7551f4876979bf1363d959292e338de098d08dedf90aab4a494fe88e"},{"code_id":"NK_RF_2","article_number":"33332.4","version_date":"2000-07-31","article_text":"За совершение уполномоченным федеральным органом исполнительной власти действий при предоставлении, переоформлении и подтверждении разрешения на применение незарегистрированного медицинского изделия для диагностики in vitro в соответствии с Федеральным законом от 21 ноября 2011 года № 323-ФЗ \"Об основах охраны здоровья граждан в Российской Федерации\" государственная пошлина уплачивается в следующих размерах:\n\n1) за предоставление разрешения на применение незарегистрированного медицинского изделия для диагностики in vitro - 9 500 рублей;\n\n2) за переоформление разрешения на применение незарегистрированного медицинского изделия для диагностики in vitro - 2 500 рублей;\n\n3) за подтверждение разрешения на применение незарегистрированного медицинского изделия для диагностики in vitro - 7 000 рублей;\n\n4) за проведение экспертизы качества, безопасности и эффективности незарегистрированного медицинского изделия для диагностики in vitro в целях предоставления разрешения на его применение - 65 800 рублей;\n\n5) за проведение экспертизы качества, безопасности и эффективности незарегистрированного медицинского изделия для диагностики in vitro в целях подтверждения разрешения на его применение - 54 500 рублей.\n\n(Дополнение статьей - Федеральный закон от 29.11.2021 № 382-ФЗ)","article_title":"Статья 33332.4. Размеры государственной пошлины за совершение действий уполномоченным федеральным органом исполнительной власти при предоставлении, переоформлении и подтверждении разрешения на применение незарегистрированного медицинского изделия для диагностики in vitro","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1c9983f0b948b7da1993b10a7e5de953b80c310ac3320f659839ab3f691c0dd4"},{"code_id":"NK_RF_2","article_number":"333.33","version_date":"2000-07-31","article_text":"1. Государственная пошлина уплачивается в следующих размерах:\n\n1) за государственную регистрацию юридического лица, за исключением государственной регистрации ликвидации юридических лиц, государственной регистрации политических партий и региональных отделений политических партий, государственной регистрации общероссийских общественных организаций инвалидов и отделений, являющихся их структурными подразделениями, государственной регистрации международных компаний, - 4 000 рублей; (В редакции федеральных законов от 18.07.2011 № 235-ФЗ, от 26.03.2022 № 66-ФЗ)\n\n11) за государственную регистрацию международной компании - 150 000 рублей; (Дополнение подпунктом - Федеральный закон от 26.03.2022 № 66-ФЗ) (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\n12) за ежегодное подтверждение статуса международной компании - 150 000 рублей; (Дополнение подпунктом - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\n2) за государственную регистрацию политической партии, а также каждого регионального отделения политической партии - 3 500 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n21) за государственную регистрацию общероссийских общественных организаций инвалидов и отделений, являющихся их структурными подразделениями, - 1 400 рублей; (Дополнение подпунктом - Федеральный закон от 18.07.2011 № 235-ФЗ) (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n3) за государственную регистрацию изменений, вносимых в учредительные документы юридического лица, а также за государственную регистрацию ликвидации юридического лица, за исключением случаев, когда ликвидация юридического лица производится в порядке применения процедуры банкротства, - 20 процентов размера государственной пошлины, установленного подпунктом 1 настоящего пункта;\n\n31) за государственную регистрацию изменений, вносимых в учредительные документы общероссийских общественных организаций инвалидов и отделений, являющихся их структурными подразделениями, - 100 рублей; (Дополнение подпунктом - Федеральный закон от 21.07.2014 № 221-ФЗ)\n\n4) за внесение сведений о некоммерческой организации в государственный реестр саморегулируемых организаций (за включение некоммерческой организации в Единый государственный реестр саморегулируемых организаций) - 6 500 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n41) за внесение сведений о юридическом лице в государственный реестр микрофинансовых организаций - 1 500 рублей; (Дополнение подпунктом - Федеральный закон от 05.07.2010 № 153-ФЗ) (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n42) (Дополнение подпунктом - Федеральный закон от 05.07.2010 № 153-ФЗ) (Утратил силу  - Федеральный закон от 13.07.2020 № 197-ФЗ)\n\n43) за принятие решения по заявлению о внесении сведений о юридическом лице в государственный реестр профессиональных коллекторских организаций - 100 000 рублей; (Дополнение подпунктом - Федеральный закон от 03.07.2016 № 246-ФЗ) (В редакции  Федерального закона от 13.12.2024 № 451-ФЗ)\n\n44) (Дополнение подпунктом - Федеральный закон от 03.07.2016 № 246-ФЗ) (Утратил силу  - Федеральный закон от 13.12.2024 № 451-ФЗ)\n\n45) за внесение сведений о юридическом лице в государственный реестр ломбардов - 1 500 рублей; (Дополнение подпунктом - Федеральный закон от 13.07.2020 № 197-ФЗ)\n\n46) за внесение сведений о юридическом лице в реестр операторов финансовых платформ в соответствии с Федеральным законом от 20 июля 2020 года № 211-ФЗ \"О совершении финансовых сделок с использованием финансовой платформы\" - 35 000 рублей; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\n5) за аккредитацию создаваемых на территории Российской Федерации филиалов, представительств иностранных организаций государств, не являющихся членами Евразийского экономического союза, - 120 000 рублей за каждый филиал, за каждое представительство; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n51) за аккредитацию создаваемых на территории Российской Федерации филиалов, представительств иностранных организаций государств - членов Евразийского экономического союза - 4000 рублей за каждый филиал, за каждое представительство; (Дополнение подпунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n6) за государственную регистрацию физического лица в качестве индивидуального предпринимателя - 800 рублей;\n\n7) за государственную регистрацию прекращения физическим лицом деятельности в качестве индивидуального предпринимателя - 20 процентов размера государственной пошлины, установленного подпунктом 6 настоящего пункта;\n\n8) за повторную выдачу свидетельства о государственной регистрации физического лица в качестве индивидуального предпринимателя или свидетельства о государственной регистрации юридического лица - 20 процентов размера государственной пошлины, уплаченной за государственную регистрацию;\n\n9) за выдачу свидетельства о регистрации лица, совершающего операции с прямогонным бензином, - 3 500 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n91) за выдачу свидетельства о регистрации лица, совершающего операции с бензолом, параксилолом, ортоксилолом, - 3 500 рублей; (Дополнение подпунктом - Федеральный закон от 24.11.2014 № 366-ФЗ)\n\n92) за выдачу свидетельства о регистрации лица, совершающего операции со средними дистиллятами, - 3 500 рублей; (Дополнение подпунктом - Федеральный закон от 23.11.2015 № 323-ФЗ)\n\n93) за выдачу свидетельства о регистрации лица, совершающего операции по переработке средних дистиллятов, - 3 500 рублей; (Дополнение подпунктом - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\n94) за выдачу свидетельства о регистрации лица, совершающего операции по переработке нефтяного сырья, - 3 500 рублей; (Дополнение подпунктом - Федеральный закон от 03.08.2018 № 301-ФЗ)\n\n95) за выдачу свидетельства о регистрации лица, совершающего операции по переработке этана, - 3 500 рублей; (Дополнение подпунктом - Федеральный закон от 15.10.2020 № 321-ФЗ)\n\n96) за выдачу свидетельства о регистрации лица, совершающего операции по переработке СУГ, - 3 500 рублей; (Дополнение подпунктом - Федеральный закон от 15.10.2020 № 321-ФЗ)\n\n10) за выдачу свидетельства о регистрации организации, совершающей операции с этиловым спиртом, - 3 500 рублей; (В редакции федеральных законов от 21.07.2014 № 221-ФЗ, от 29.09.2019 № 326-ФЗ)\n\n11) за государственную регистрацию средства массовой информации, за внесение изменений в запись о регистрации средства массовой информации (в том числе связанных с изменением тематики или специализации), продукция которого предназначена для распространения преимущественно на всей территории Российской Федерации, за ее пределами, на территориях двух и более субъектов Российской Федерации, - 8 000 рублей; (В редакции Федерального закона от 29.07.2017 № 253-ФЗ)\n\n12) за государственную регистрацию средства массовой информации, за внесение изменений в запись о регистрации средства массовой информации (в том числе связанных с изменением тематики или специализации), продукция которого предназначена для распространения преимущественно на территории субъекта Российской Федерации, территории муниципального образования, - 4 000 рублей; (В редакции Федерального закона от 29.07.2017 № 253-ФЗ)\n\n13) за выдачу разрешения на распространение продукции зарубежного периодическо\n\nго печатного издания на территории Российской Федерации - 8 000 рублей; (В редакции Федерального закона от 29.07.2017 № 253-ФЗ)\n\n14) (Подпункт утратил силу - Федеральный закон от 29.07.2017 № 253-ФЗ)\n\n15) (Подпункт утратил силу - Федеральный закон от 05.04.2010 № 41-ФЗ)\n\n16) за регистрацию иностранного гражданина и лица без гражданства, проживающего на территории Российской Федерации, по месту жительства - 350 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n17) за выдачу паспорта гражданина Российской Федерации - 300 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n18) за выдачу паспорта гражданина Российской Федерации взамен утраченного или пришедшего в негодность - 1 500 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n19) за государственную регистрацию договора о залоге транспортных средств, включая выдачу свидетельств, - 1 600 рублей; (В редакции федеральных законов от 02.11.2013 № 306-ФЗ; от 21.07.2014 № 221-ФЗ)\n\n20) за выдачу дубликата свидетельства о государственной регистрации договора о залоге транспортных средств взамен утраченного или пришедшего в негодность - 800 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n21) за государственный кадастровый учет и государственную регистрацию прав на предприятие как имущественный комплекс, а также за государственную регистрацию перехода прав на предприятие как имущественный комплекс, сделок с предприятием как имущественным комплексом, если такие сделки подлежат государственной регистрации в соответствии с федеральным законом, ограничений прав и обременений предприятия как имущественного комплекса - 0,2 процента стоимости имущества, имущественных и иных прав, входящих в состав предприятия как имущественного комплекса, определенной на дату обращения за совершением юридически значимого действия, но не менее 0,2 процента цены сделки, являющейся основанием перехода права собственности на предприятие как имущественный комплекс, и не более 1 000 000 рублей; (В редакции  Федерального закона от 29.10.2024 № 362-ФЗ)\n\n22) за государственную регистрацию прав, ограничений прав и обременений объектов недвижимости, сделок с объектом недвижимости, если такие сделки подлежат государственной регистрации в соответствии с федеральным законом, за исключением юридически значимых действий, предусмотренных подпунктами 21, 221, 224, 24 - 26, 261, 262, 272, 28 - 31, 61 и 801 настоящего пункта: (В редакции  федеральных законов от 29.09.2019 № 325-ФЗ, от 02.07.2021 № 305-ФЗ, от 05.12.2022 № 493-ФЗ, от 12.07.2024 № 176-ФЗ, от 31.07.2025 № 275-ФЗ)\n\nдля физических лиц: (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nв отношении объекта недвижимости или доли в праве общей долевой собственности на объект недвижимости, если кадастровая стоимость объекта недвижимости не определена, объекта недвижимости или доли в праве общей долевой собственности на объект недвижимости, кадастровая стоимость которого или ее часть, соответствующая размеру доли в праве общей долевой собственности на объект недвижимости, не превышает 20 000 000 рублей, - 4000 рублей; (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ) (В редакции  Федерального закона от 31.07.2025 № 275-ФЗ)\n\nв отношении объекта недвижимости или доли в праве общей долевой собственности на объект недвижимости, кадастровая стоимость которого или ее часть, соответствующая размеру доли в праве общей долевой собственности на объект недвижимости, превышает 20 000 000 рублей, - 0,02 процента кадастровой стоимости объекта недвижимости или ее части, соответствующей размеру доли в праве общей долевой собственности на объект недвижимости, определенной в отношении этого объекта недвижимости на дату обращения за совершением юридически значимого действия, но не менее 0,02 процента цены сделки, являющейся основанием перехода права собственности на соответствующие объект недвижимости или долю в праве общей долевой собственности на объект недвижимости, и не более 500 000 рублей; (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ) (В редакции  Федерального закона от 31.07.2025 № 275-ФЗ)\n\nдля организаций, за исключением организаций, указанных в абзаце восьмом настоящего подпункта: (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nв отношении объекта недвижимости или доли в праве общей долевой собственности на объект недвижимости, если кадастровая стоимость объекта недвижимости не определена, объекта недвижимости или доли в праве общей долевой собственности на объект недвижимости, кадастровая стоимость которого или ее часть, соответствующая размеру доли в праве общей долевой собственности на объект недвижимости, не превышает 22 000 000 рублей, - 44 000 рублей; (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ) (В редакции  Федерального закона от 31.07.2025 № 275-ФЗ)\n\nв отношении объекта недвижимости или доли в праве общей долевой собственности на объект недвижимости, кадастровая стоимость которого или ее часть, соответствующая размеру доли в праве общей долевой собственности на объект недвижимости, превышает 22 000 000 рублей, - 0,2 процента кадастровой стоимости объекта недвижимости или ее части, соответствующей размеру доли в праве общей долевой собственности на объект недвижимости, определенной в отношении этого объекта недвижимости на дату обращения за совершением юридически значимого действия, но не менее 0,2 процента цены сделки, являющейся основанием перехода права собственности на соответствующие объект недвижимости или долю в праве общей долевой собственности на объект недвижимости, и не более 1 000 000 рублей; (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ) (В редакции  Федерального закона от 31.07.2025 № 275-ФЗ)\n\nдля религиозных организаций одного вероисповедания, являющихся сторонами заключенного между ними договора пожертвования недвижимого имущества религиозного назначения, - 2000 рублей. (Дополнение абзацем - Федеральный закон от 19.12.2023 № 611-ФЗ) (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nСумма государственной пошлины, подлежащая уплате в соответствии с абзацами четвертым и седьмым настоящего подпункта, округляется до полных 100 рублей в меньшую сторону; (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n221) за государственную регистрацию права общей долевой собственности владельцев инвестиционных паев на недвижимое имущество, составляющее паевой инвестиционный фонд (приобретаемое для включения в состав паевого инвестиционного фонда), ограничения этого права и обременений данного имущества или сделок с данным имуществом: (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 29.09.2019 № 325-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nв отношении объекта недвижимости или доли в праве общей долевой собственности на объект недвижимости, если кадастровая стоимость объекта недвижимости не определена, объекта недвижимости или доли в праве общей долевой собственности на объект недвижимости, кадастровая стоимость которого или ее часть, соответствующая размеру доли в праве общей долевой собственности на объект недвижимости, не превышает 22 000 000 рублей, - 44 000 рублей; (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ) (В редакции  Федерального закона от 31.07.2025 № 275-ФЗ)\n\nв отношении объекта недвижимости или доли в праве общей долевой собственности на объект недвижимости, кадастровая стоимость которого или ее часть, соответствующая размеру доли в праве общей долевой собственности на объект недвижимости, превышает 22 000 000 рублей, - 0,2 процента кадастровой стоимости объекта недвижимости или ее части, соответствующей размеру доли в праве общей долевой собственности на объект недвижимости, определенной в отношении этого объекта недвижимости на дату обращения за совершением юридически значимого действия, но не менее 0,2 процента цены сделки, являющейся основанием перехода права собственности на соответствующие объект недвижимости или долю в праве общей долевой собственности на объект недвижимости, и не более 1 000 000 рублей; (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ) (В редакции  Федерального закона от 31.07.2025 № 275-ФЗ)\n\nв отношении предприятия как имущественного комплекса - 0,2 процента стоимости имущества, имущественных и иных прав, входящих в состав предприятия как имущественного комплекса, определенной на дату обращения за совершением юридически значимого действия, но не менее 0,2 процента цены сделки, являющейся основанием перехода права собственности на предприятие как имущественный комплекс, и не более 1 000 000 рублей; (Дополнение абзацем - Федеральный закон от 29.10.2024 № 362-ФЗ)\n\nСумма государственной пошлины, подлежащая уплате в соответствии с абзацами третьим и четвертым настоящего подпункта, округляется до полных 100 рублей в меньшую сторону; (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ) (В редакции  Федерального закона от 29.10.2024 № 362-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 05.04.2010 № 41-ФЗ) (В редакции Федерального закона от 29.11.2012 № 205-ФЗ)\n\n222) за государственный кадастровый учет создаваемых, созданных (образованных) объектов недвижимости без одновременной государственной регистрации прав, за исключением юридически значимых действий, предусмотренных подпунктом 223 настоящего пункта: (В редакции  Федерального закона от 31.07.2025 № 275-ФЗ)\n\nдля физических лиц - 2000 рублей;\n\nдля организаций - 22 000 рублей;\n\n(Дополнение подпунктом - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n223) за государственный кадастровый учет в связи с изменением сведений об объекте недвижимости:\n\nдля физических лиц - 1000 рублей;\n\nдля организаций - 2000 рублей;\n\n(Дополнение подпунктом - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n224) за осуществляемые одновременно государственный кадастровый учет и государственную регистрацию прав на создаваемые, созданные (образованные) объекты недвижимости, за исключением юридически значимых действий, предусмотренных подпунктом 262 настоящего пункта:\n\nдля физических лиц - 6000 рублей;\n\nдля организаций - 66 000 рублей;\n\n(Дополнение подпунктом - Федеральный закон от 12.07.2024 № 176-ФЗ) (В редакции  Федерального закона от 31.07.2025 № 275-ФЗ)\n\n23) (Подпункт утратил силу - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n24) за государственный кадастровый учет или государственную регистрацию права собственности физического лица на земельный участок, предназначенный для ведения личного подсобного хозяйства, ведения гражданами садоводства или огородничества для собственных нужд, индивидуального гаражного или индивидуального жилищного строительства, осуществления крестьянским (фермерским) хозяйством своей деятельности, либо на создаваемый или созданный на таком земельном участке объект недвижимого имущества - 700 рублей; (В редакции  Федерального закона от 31.07.2025 № 275-ФЗ)\n\n241) за осуществляемые одновременно государственный кадастровый учет и государственную регистрацию права собственности физического лица на земельный участок, предназначенный для ведения личного подсобного хозяйства, ведения гражданами садоводства или огородничества для собственных нужд, индивидуального гаражного или индивидуального жилищного строительства, осуществления крестьянским (фермерским) хозяйством своей деятельности, либо на создаваемый или созданный на таком земельном участке объект недвижимого имущества - 1000 рублей; (Дополнение подпунктом - Федеральный закон от 12.07.2024 № 176-ФЗ) (В редакции  Федерального закона от 31.07.2025 № 275-ФЗ)\n\n25) за государственную регистрацию прав, ограничений прав и обременений земельных участков из земель сельскохозяйственного назначения, сделок с такими земельными участками, если данные сделки подлежат государственной регистрации в соответствии с федеральным законом, - 700 рублей; (В редакции  федеральных законов от 29.09.2019 № 325-ФЗ, от 12.07.2024 № 176-ФЗ)\n\n251) за осуществляемые одновременно государственный кадастровый учет и государственную регистрацию прав на земельный участок из земель сельскохозяйственного назначения - 1000 рублей; (Дополнение подпунктом - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n26) за государственную регистрацию доли в праве общей собственности на земельные участки из земель сельскохозяйственного назначения - 200 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 12.07.2024 № 176-ФЗ)\n\n261) за государственную регистрацию прав, ограничений прав и обременений объектов сетей газораспределения и сетей газопотребления, созданных при выполнении мероприятий по подключению (технологическому присоединению) объектов капитального строительства, а также за государственную регистрацию сделок с указанными объектами недвижимости, если такие сделки подлежат государственной регистрации в соответствии с федеральным законом - 2 000 рублей; (Дополнение подпунктом - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n262) за осуществляемые одновременно государственный кадастровый учет и государственную регистрацию прав на объекты сетей газораспределения и сетей газопотребления, созданные при выполнении мероприятий по подключению (технологическому присоединению) объектов капитального строительства, - 4000 рублей; (Дополнение подпунктом - Федеральный закон от 31.07.2025 № 275-ФЗ)\n\n27) за внесение изменений в записи Единого государственного реестра недвижимости о правах, об ограничениях прав и обременениях недвижимого имущества, за исключением юридически значимых действий, предусмотренных подпунктом 281 настоящего пункта: (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nдля физических лиц - 700 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nдля организаций - 2000 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 12.07.2024 № 176-ФЗ)\n\n271) за государственную регистрацию перехода права собственности на объект недвижимости в связи с реорганизацией юридического лица в форме преобразования - 2000 рублей; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 374-ФЗ) (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\n272) за государственную регистрацию:\n\nдоговоров аренды, безвозмездного пользования, в том числе договоров аренды, безвозмездного пользования частями объектов недвижимости, регистрация которых осуществляется одновременно с государственным кадастровым учетом таких частей объектов недвижимости, уступки прав требования по договорам аренды, безвозмездного пользования, если такие договоры подлежат регистрации в Едином государственном реестре недвижимости: (В редакции  Федерального закона от 31.07.2025 № 275-ФЗ)\n\nдля физических лиц - 4000 рублей;\n\nдля организаций - 44 000 рублей;\n\nсоглашения об изменении или о расторжении договора аренды, безвозмездного пользования, если такой договор зарегистрирован в Едином государственном реестре недвижимости: (В редакции  Федерального закона от 31.07.2025 № 275-ФЗ)\n\nдля физических лиц - 700 рублей;\n\nдля организаций - 2000 рублей;\n\n(Дополнение подпунктом - Федеральный закон от 05.12.2022 № 493-ФЗ) (В редакции  Федерального закона от 29.10.2024 № 362-ФЗ)\n\n28) за государственную регистрацию, за исключением юридически значимых действий, предусмотренных подпунктами 25 и 61 настоящего пункта, ипотеки, включая внесение в Единый государственный реестр недвижимости записи об ипотеке как обременении объекта недвижимости: (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nдля физических лиц - 1 000 рублей;\n\nдля организаций - 4 000 рублей;\n\n(Подпункт в редакции Федерального закона от 22.10.2014 № 312-ФЗ)\n\n281) за внесение изменений и дополнений в регистрационную запись об ипотеке: (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nдля физических лиц - 400 рублей; (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nдля организаций - 1200 рублей. (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nВ случае, если договор об ипотеке или договор, включающий соглашение об ипотеке, обеспечивающее исполнение обязательства, за исключением договора, влекущего возникновение ипотеки на основании закона, заключен между физическим лицом и юридическим лицом, государственная пошлина за юридически значимые действия, предусмотренные подпунктом 28 настоящего пункта и настоящим подпунктом, взимается в размерах, установленных для физических лиц;\n\n(Дополнение подпунктом - Федеральный закон от 22.10.2014 № 312-ФЗ)\n\n29) за государственную регистрацию:\n\nсмены залогодержателя вследствие уступки прав по основному обязательству, обеспеченному ипотекой, либо по договору об ипотеке, в том числе сделки по уступке прав требования, включая внесение в Единый государственный реестр недвижимости записи об ипотеке, осуществляемой при смене залогодержателя, - 2000 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 29.09.2019 № 325-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nсмены владельца закладной, в том числе сделки по уступке прав требования, включая внесение в Единый государственный реестр недвижимости записи об ипотеке, осуществляемой при смене владельца закладной, - 1000 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 29.09.2019 № 325-ФЗ, от 12.07.2024 № 176-ФЗ)\n\n30) за государственную регистрацию:\n\nдоговора участия в долевом строительстве:\n\nдля физических лиц - 700 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nдля организаций - 12 000 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nсоглашения об изменении или о расторжении договора участия в долевом строительстве, уступки прав требования по договору участия в долевом строительстве, включая внесение соответствующих изменений в Единый государственный реестр недвижимости, - 350 рублей; (В редакции федеральных законов от 21.07.2014 № 221-ФЗ, от 29.09.2019 № 325-ФЗ)\n\n31) за государственную регистрацию сервитутов, в том числе сервитутов, предусматривающих право ограниченного пользования частями земельных участков, государственная регистрация которых осуществляется одновременно с государственным кадастровым учетом таких частей земельных участков: (В редакции  Федерального закона от 31.07.2025 № 275-ФЗ)\n\nв интересах физических лиц - 1 500 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\nв интересах организаций - 6 000 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n32) (Подпункт утратил силу  - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n33) (Подпункт утратил силу - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\n34) за выдачу заключения (разрешительного документа) на вывоз культурных ценностей:\n\nфизическим лицам - 5 процентов стоимости вывозимых культурных ценностей, но не более 1 000 000 рублей;\n\nфизическим лицам, зарегистрированным в качестве индивидуальных предпринимателей, и юридическим лицам - 10 процентов стоимости вывозимых культурных ценностей;\n\n(Подпункт в редакции Федерального закона от 28.12.2017 № 430-ФЗ)\n\n341) (Дополнение подпунктом - Федеральный закон от 28.12.2017 № 430-ФЗ) (Утратил силу  - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n342) за выдачу паспорта на музыкальный инструмент или смычок - 1 000 рублей; (Дополнение подпунктом - Федеральный закон от 28.12.2017 № 430-ФЗ) (В редакции Федерального закона от 22.12.2020 № 457-ФЗ)\n\n343) за выдачу удостоверения эксперта по культурным ценностям - 4 000 рублей; (Дополнение подпунктом - Федеральный закон от 28.12.2017 № 430-ФЗ)\n\n35) за выдачу заключения (разрешительного документа) на временный вывоз культурных ценностей, в том числе при продлении срока временного вывоза культурных ценностей:\n\nв случае временного вывоза культурных ценностей, включенных в состав Музейного фонда Российской Федерации, - 0,01 процента страховой ст\n\nоимости временно вывозимых культурных ценностей, но не более 5 000 рублей;\n\nв случае временного вывоза культурных ценностей, находящихся в собственности физических или юридических лиц, за исключением культурных ценностей, включенных в состав Музейного фонда Российской Федерации, - 0,01 процента стоимости временно вывозимых культурных ценностей, но не более 5 000 рублей;\n\n(Подпункт в редакции Федерального закона от 22.12.2020 № 457-ФЗ)\n\n351) за нанесение меток в соответствии с Законом Российской Федерации от 15 апреля 1993 года № 4804-I \"О вывозе и ввозе культурных ценностей\":\n\nна струнный смычковый музыкальный инструмент или смычок, отнесенные по результатам экспертизы культурных ценностей к культурным ценностям, либо к культурным ценностям, имеющим особое значение, либо к культурным ценностям, в отношении которых правом Евразийского экономического союза установлен разрешительный порядок вывоза, а также включенные в состав Музейного фонда Российской Федерации, - 2000 рублей;\n\nна струнный смычковый музыкальный инструмент или смычок, не указанные в абзаце втором настоящего подпункта, - 500 рублей;\n\n(Дополнение подпунктом - Федеральный закон от 19.12.2023 № 611-ФЗ)\n\n36) за государственную регистрацию транспортных средств и совершение иных регистрационных действий, связанных:\n\nс выдачей государственных регистрационных знаков на автомобили, в том числе взамен утраченных или пришедших в негодность, - 3000 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 31.07.2025 № 271-ФЗ)\n\nс выдачей государственных регистрационных знаков на тракторы, самоходные дорожно-строительные машины, коммунальные, сельскохозяйственные машины, внедорожные автомототранспортные средства и прицепы к ним, в том числе взамен утраченных или пришедших в негодность, - 1500 рублей; (В редакции  Федерального закона от 31.07.2025 № 271-ФЗ)\n\nс выдачей паспорта самоходной машины и других видов техники, в том числе взамен утраченного или пришедшего в негодность, - 800 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 03.07.2018 № 180-ФЗ, от 31.07.2025 № 271-ФЗ)\n\nс оформлением электронного паспорта самоходной машины и других видов техники, с внесением изменений в электронный паспорт самоходной машины и других видов техники, - 2000 рублей; (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nс выдачей свидетельства о регистрации машины, в том числе взамен утраченного или пришедшего в негодность, - 500 рублей; (В редакции Федерального закона от 03.07.2018 № 180-ФЗ)\n\nс выдачей свидетельства о регистрации транспортного средства, в том числе взамен утраченного или пришедшего в негодность: (Дополнение абзацем - Федеральный закон от 03.07.2018 № 180-ФЗ)\n\nизготавливаемого из расходных материалов на бумажной основе, - 1500 рублей; (Дополнение абзацем - Федеральный закон от 03.07.2018 № 180-ФЗ) (В редакции  Федерального закона от 31.07.2025 № 271-ФЗ)\n\nизготавливаемого из расходных материалов на пластиковой основе нового поколения, - 4500 рублей; (Дополнение абзацем - Федеральный закон от 03.07.2018 № 180-ФЗ) (В редакции  Федерального закона от 31.07.2025 № 271-ФЗ)\n\nс выдачей паспорта транспортного средства, в том числе взамен утраченного или пришедшего в негодность, - 1200 рублей; (Дополнение абзацем - Федеральный закон от 31.07.2025 № 271-ФЗ)\n\nс выдачей государственных регистрационных знаков на прицепы и мототранспортные средства, в том числе взамен утраченных или пришедших в негодность, - 2250 рублей; (Дополнение абзацем - Федеральный закон от 31.07.2025 № 271-ФЗ)\n\n37) (Подпункт утратил силу - Федеральный закон от 31.07.2025 № 271-ФЗ)\n\n38) за внесение изменений в выданный ранее паспорт самоходной машины и других видов техники - 350 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 03.07.2018 № 180-ФЗ, от 31.07.2025 № 271-ФЗ)\n\n381) за внесение изменений в паспорт транспортного средства - 525 рублей; (Дополнение подпунктом - Федеральный закон от 31.07.2025 № 271-ФЗ)\n\n39) за выдачу государственных регистрационных знаков транспортных средств \"Транзит\", в том числе взамен утраченных или пришедших в негодность:\n\nизготавливаемых из расходных материалов на металлической основе, на автомобили и прицепы - 2400 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 31.07.2025 № 271-ФЗ)\n\nизготавливаемых из расходных материалов на металлической основе, на тракторы, самоходные дорожно-строительные машины, коммунальные, сельскохозяйственные машины, внедорожные автомототранспортные средства и прицепы к ним - 800 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 31.07.2025 № 271-ФЗ)\n\nизготавливаемых из расходных материалов на бумажной основе, - 300 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 31.07.2025 № 271-ФЗ)\n\n40) за выдачу свидетельства на высвободившийся номерной агрегат, в том числе взамен утраченного или пришедшего в негодность, - 350 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n41) за выдачу диагностической карты, содержащей сведения о соответствии или несоответствии транспортного средства обязательным требованиям безопасности транспортных средств, в том числе взамен утраченной или пришедшей в негодность, в случаях, предусмотренных частью 1 статьи 54 Федерального закона от 7 февраля 2011 года № 3-ФЗ \"О полиции\", - 300 рублей; (В редакции Федерального закона от 28.07.2012 № 130-ФЗ)\n\n411) (Дополнение подпунктом - Федеральный закон от 21.11.2011 № 330-ФЗ) (Утратил силу - Федеральный закон от 28.07.2012 № 130-ФЗ)\n\n412) за выдачу документа о прохождении технического осмотра тракторов, самоходных дорожно-строительных и иных самоходных машин и прицепов к ним - 400 рублей; (Дополнение подпунктом - Федеральный закон от 29.11.2012 № 205-ФЗ) (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n42) (Подпункт утратил силу - Федеральный закон от 28.07.2012 № 130-ФЗ)\n\n43) за выдачу удостоверения тракториста-машиниста (тракториста), временного удостоверения на право управления самоходными машинами, в том числе взамен утраченного или пришедшего в негодность: (В редакции федеральных законов от 29.11.2012 № 205-ФЗ; от 03.07.2018 № 180-ФЗ)\n\nизготавливаемого из расходных материалов на бумажной основе, - 500 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\nизготавливаемого из расходных материалов на пластиковой основе, - 2 000 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n431) за выдачу национального водительского удостоверения, в том числе взамен утраченного или пришедшего в негодность:\n\nизготавливаемого из расходных материалов на пластиковой основе, - 4000 рублей; (В редакции  Федерального закона от 31.07.2025 № 271-ФЗ)\n\nизготавливаемого из расходных материалов на пластиковой основе нового поколения, - 6000 рублей; (В редакции  Федерального закона от 31.07.2025 № 271-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 03.07.2018 № 180-ФЗ)\n\n44) за выдачу международного водительского удостоверения, в том числе взамен утраченного или пришедшего в негодность, - 3200 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 31.07.2025 № 271-ФЗ)\n\n45) (Подпункт утратил силу - Федеральный закон от 03.07.2018 № 180-ФЗ)\n\n46) за выдачу свидетельства о соответствии транспортного средства с внесенными в его конструкцию изменениями требованиям безопасности, в том числе взамен утраченного или пришедшего в негодность, - 4500 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 03.07.2018 № 180-ФЗ, от 28.06.2022 № 208-ФЗ, от 31.07.2025 № 271-ФЗ)\n\n461) за выдачу разрешения на внесение изменений в конструкцию находящегося в эксплуатации колесного транспортного средства, в том числе взамен утраченного или пришедшего в негодность, - 3000 рублей; (Дополнение подпунктом - Федеральный закон от 28.06.2022 № 208-ФЗ) (В редакции  Федерального закона от 31.07.2025 № 271-ФЗ)\n\n462) за выдачу свидетельства о допуске транспортных средств к перевозке опасных грузов, в том числе взамен утраченного или пришедшего в негодность, - 2250 рублей; (Дополнение подпунктом - Федеральный закон от 28.06.2022 № 208-ФЗ) (В редакции  Федерального закона от 31.07.2025 № 271-ФЗ)\n\n463) за продление срока действия свидетельства о допуске транспортных средств к перевозке опасных грузов - 1500 рублей; (Дополнение подпунктом - Федеральный закон от 28.06.2022 № 208-ФЗ) (В редакции  Федерального закона от 31.07.2025 № 271-ФЗ)\n\n47) за выдачу организациям, осуществляющим образовательную деятельность, свидетельств о соответствии требованиям оборудования и оснащенности образовательного процесса для рассмотрения вопроса соответствующими органами об аккредитации и о предоставлении указанным организациям лицензий на право подготовки трактористов и машинистов самоходных машин - 1 600 рублей; (В редакции федеральных законов от 21.07.2014 № 221-ФЗ, от 27.11.2017 № 346-ФЗ, от 29.11.2021 № 383-ФЗ)\n\n48) за проставление апостиля - 2 500 рублей за каждый документ; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n49) за признание иностранного образования и (или) иностранной квалификации, осуществляемое федеральным органом исполнительной власти, осуществляющим функции по контролю и надзору в сфере образования, - 6 500 рублей; (В редакции  Федерального закона от 29.12.2022 № 583-ФЗ)\n\n491) за выдачу свидетельства о признании документа иностранного государства об ученой степени или документа иностранного государства об ученом звании - 5 500 рублей; (Дополнение подпунктом - Федеральный закон от 03.12.2011 № 385-ФЗ) (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n50) (Подпункт утратил силу - Федеральный закон от 29.12.2022 № 583-ФЗ)\n\n501) за выдачу дубликата свидетельства о признании документа иностранного государства об ученой степени или документа иностранного государства об ученом звании - 300 рублей; (Дополнение подпунктом - Федеральный закон от 03.12.2011 № 385-ФЗ) (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n51) за легализацию документов - 350 рублей за каждый документ; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n52) за истребование документов с территории иностранных государств - 350 рублей за каждый документ; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n53) за совершение уполномоченным органом действий, связанных с государственной регистрацией выпусков (дополнительных выпусков) эмиссионных ценных бумаг:\n\nза государственную регистрацию выпуска (дополнительного выпуска) эмиссионных ценных бумаг, размещаемых путем подписки, - 0,2 процента номинальной суммы выпуска (дополнительного выпуска), но не более 200 000 рублей;\n\nза государственную регистрацию выпуска (дополнительного выпуска) эмиссионных ценных бумаг, размещаемых иными способами, за исключением подписки, - 35 000 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\nза государственную регистрацию отчета об итогах выпуска (дополнительного выпуска) эмиссионных ценных бумаг, за исключением случая регистрации такого отчета одновременно с государственной регистрацией выпуска (дополнительного выпуска) эмиссионных ценных бумаг, - 35 000 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\nза регистрацию проспекта ценных бумаг (в случае, если государственная регистрация выпуска (дополнительного выпуска) эмиссионных ценных бумаг и (или) программы облигаций не сопровождалась регистрацией их проспекта) - 35 000 рублей; (В редакции федеральных законов от 21.07.2014 № 221-ФЗ, от 02.07.2021 № 305-ФЗ)\n\nза государственную регистрацию выпуска российских депозитарных расписок, выпуска (дополнительного выпуска) опционов эмитента - 325 000 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\nза государственную регистрацию проспекта российских депозитарных расписок, опционов эмитента (в случае, если государственная регистрация выпуска российских депозитарных расписок, выпуска (дополнительного выпуска) опционов эмитента не сопровождалась регистрацией их проспекта) - 35 000 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\nза государственную регистрацию изменений, вносимых в решение о выпуске эмиссионных ценных бумаг, зарегистрированный документ, содержащий условия размещения эмиссионных ценных бумаг, программу облигаций и (или) проспект ценных бумаг, - 35 000 рублей; (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\nза предварительное рассмотрение документов, необходимых для государственной регистрации выпуска (дополнительного выпуска) ценных бумаг, - 160 000 рублей; (Дополнение абзацем - Федеральный закон от 29.12.2012 № 282-ФЗ) (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\nза регистрацию основной части проспекта ценных бумаг - 325 000 рублей; (Дополнение абзацем - Федеральный закон от 29.12.2012 № 282-ФЗ) (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\nза государственную регистрацию программы облигаций - 35 000 рублей; (Дополнение абзацем - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n54) за совершение уполномоченным органом действий, связанных с регистрацией пенсионных и страховых правил, а также правил формирования долгосрочных сбережений негосударственных пенсионных фондов: (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nза регистрацию пенсионных и страховых правил, а также правил формирования долгосрочных сбережений негосударственного пенсионного фонда - 3 500 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nза регистрацию изменений, вносимых в пенсионные и страховые правила, а также правила формирования долгосрочных сбережений негосударственного пенсионного фонда, - 1 600 рублей; (В редакции  федеральных законов от 21.07.2014 № 221-ФЗ, от 12.07.2024 № 176-ФЗ)\n\n55) за совершение следующих действий:\n\nза выдачу разрешения на размещение и (или) обращение эмиссионных ценных бумаг российских эмитентов за пределами Российской Федерации, в том числе посредством размещения в соответствии с иностранным правом ценных бумаг иностранных эмитентов, удостоверяющих права в отношении эмиссионных ценных бумаг российских эмитентов, - 35 000 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\nза выдачу разрешения, подтверждающего статус саморегулируемой организации профессиональных участников рынка ценных бумаг, саморегулируемой организации управляющих компаний акционерных инвестиционных фондов, паевых инвестиционных фондов и негосударственных пенсионных фондов, - 35 000 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n56) за совершение регистрационных действий, связанных с паевыми инвестиционными фондами:\n\nза регистрацию правил доверительного управления паевым инвестиционным фондом - 95 000 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\nза регистрацию изменений, вносимых в правила доверительного управления паевым инвестиционным фондом, - 16 000 рублей; (В редакции Федерального закона от 21.07.2014 № 221-ФЗ)\n\n57) за совершение регистрационных действий, связанных с осуществлением деятельности на рынке ценных бумаг:\n\nза регистрацию изменений, вносимых в правила осуществления клиринговой деятельности, - 35 000 рублей; (В редакции федеральных законов от 23.07.2013 № 251-ФЗ; от 21.07.2014 № 221-ФЗ)\n\nза регистрацию регламента специализированного депозитария ипотечного покрытия, акционерных инвестиционных фондов, паевых инвестиционных фондов и негосударственных пенсионных фондов, специализированного депозитария, обслуживающего средства пенсионных накоплений, переданных негосударственным пенсионным фондам, осуществляющим деятельность в качестве страховщика по обязательному пенсионному страхованию, или регламента специализированного депозитария, обслуживающего средства пенсионных накоплений, переданных Фондом пенсионного и социального страхования Российской Федерации частным управляющим компаниям и государственной управляющей компании, или регламента специализированного деп